int runtimeVxlTargetBodyHeight() {
    return static_cast<int>(std::lround(runtimeEnvDouble(
        "CONCORD_VXL_TARGET_BODY_HEIGHT",
        0.0,
        0.0,
        128.0
    )));
}

std::string runtimeVxlSizingCacheToken(const RuntimeVxlRasterSizing& sizing) {
    std::ostringstream stream;
    stream << "|vw" << static_cast<int>(std::lround(sizing.maxWidth * 10.0))
           << "|vh" << static_cast<int>(std::lround(sizing.maxHeight * 10.0))
           << "|vs" << static_cast<int>(std::lround(sizing.maxScale * 1000.0))
           << "|vfs" << static_cast<int>(std::lround(sizing.forcedFitScale * 10000.0))
           << "|vhpm" << static_cast<int>(std::lround(
                sizing.heightProjectionMultiplier * 1000.0
           ))
           << "|vf" << sizing.pixelFootprint
           << "|vo" << (sizing.modelOriginPivot ? 1 : 0)
           << "|vp" << (sizing.pointRaster ? 1 : 0)
           << "|vg" << (sizing.fillPointGaps ? 1 : 0);
    return stream.str();
}

std::string fileNameForShpImageId(const std::string& imageId) {
    if (imageId.empty()) {
        return "";
    }

    const std::string lower = toLowerAscii(imageId);
    if (!std::filesystem::path(lower).extension().empty()) {
        return imageId;
    }

    return imageId + ".shp";
}

bool runtimeFileNameHasExtension(
    const std::string& fileName,
    const std::string& extension
) {
    if (fileName.empty() || extension.empty()) {
        return false;
    }

    return toLowerAscii(std::filesystem::path(fileName).extension().string())
        == toLowerAscii(extension);
}

bool runtimeAuxiliaryResourceUsesShpBytes(
    const std::string& fileName,
    const ArtType* artType
) {
    if (runtimeFileNameHasExtension(fileName, ".shp")
        || runtimeFileNameHasExtension(fileName, ".sha")) {
        return true;
    }
    if (artType == nullptr || !artType->theater) {
        return false;
    }

    static constexpr std::array<const char*, 6> theaterExtensions{
        ".tem", ".sno", ".urb", ".des", ".lun", ".ubn"
    };
    return std::any_of(
        theaterExtensions.begin(),
        theaterExtensions.end(),
        [&fileName](const char* extension) {
            return runtimeFileNameHasExtension(fileName, extension);
        }
    );
}

std::string fileNameForVxlImageId(const std::string& imageId) {
    if (imageId.empty()) {
        return "";
    }

    const std::string lower = toLowerAscii(imageId);
    if (lower.size() >= 4
        && lower.substr(lower.size() - 4) == ".vxl") {
        return imageId;
    }

    return imageId + ".vxl";
}

std::string fileNameForHvaImageId(const std::string& imageId) {
    if (imageId.empty()) {
        return "";
    }

    const std::string lower = toLowerAscii(imageId);
    if (lower.size() >= 4
        && lower.substr(lower.size() - 4) == ".hva") {
        return imageId;
    }

    return imageId + ".hva";
}

bool findFileByNameCaseInsensitive(
    const std::string& rootPath,
    const std::string& fileName,
    std::string& resolvedPath
) {
    if (rootPath.empty() || fileName.empty()) {
        return false;
    }

    const std::filesystem::path root(rootPath);
    std::error_code errorCode;
    if (!std::filesystem::exists(root, errorCode)) {
        return false;
    }

    const std::string targetFileName = toLowerAscii(fileName);
    if (std::filesystem::is_regular_file(root, errorCode)) {
        if (toLowerAscii(root.filename().string()) == targetFileName) {
            resolvedPath = root.generic_string();
            return true;
        }
        return false;
    }

    if (!std::filesystem::is_directory(root, errorCode)) {
        return false;
    }

    std::filesystem::recursive_directory_iterator iterator(
        root,
        std::filesystem::directory_options::skip_permission_denied,
        errorCode
    );
    const std::filesystem::recursive_directory_iterator end;
    while (!errorCode && iterator != end) {
        const std::filesystem::directory_entry& entry = *iterator;
        if (entry.is_regular_file(errorCode)
            && toLowerAscii(entry.path().filename().string()) == targetFileName) {
            resolvedPath = entry.path().generic_string();
            return true;
        }
        iterator.increment(errorCode);
    }

    return false;
}

std::string normalizedLowerPath(std::string path) {
    std::replace(path.begin(), path.end(), '\\', '/');
    return toLowerAscii(std::move(path));
}

std::string runtimeMixExportsRootFromPath(const std::string& pathString) {
    if (pathString.empty()) {
        return "";
    }

    std::filesystem::path path(pathString);
    std::error_code errorCode;
    if (std::filesystem::is_regular_file(path, errorCode)) {
        path = path.parent_path();
    }

    for (std::filesystem::path current = path;
        !current.empty();
        current = current.parent_path()) {
        if (toLowerAscii(current.filename().string()) == "mix_exports") {
            return current.generic_string();
        }
        if (current == current.parent_path()) {
            break;
        }
    }
    return "";
}

std::string runtimeMixExportsRootForContext(
    const RuntimeMapRenderContext& context
) {
    std::string root = runtimeMixExportsRootFromPath(context.tileRootPath);
    if (!root.empty()) {
        return root;
    }
    root = runtimeMixExportsRootFromPath(context.structureRootPath);
    if (!root.empty()) {
        return root;
    }
    return runtimeMixExportsRootFromPath(context.assetRootPath);
}

const std::string& cachedRuntimeMixExportsRootForContext(
    const RuntimeMapRenderContext& context,
    RuntimeMapRenderCache& cache
) {
    if (!cache.mixExportsRootResolved
        || cache.mixExportsRootAssetPath != context.assetRootPath
        || cache.mixExportsRootStructurePath != context.structureRootPath
        || cache.mixExportsRootTilePath != context.tileRootPath) {
        cache.resolvedMixExportsRoot = runtimeMixExportsRootForContext(context);
        cache.mixExportsRootAssetPath = context.assetRootPath;
        cache.mixExportsRootStructurePath = context.structureRootPath;
        cache.mixExportsRootTilePath = context.tileRootPath;
        cache.mixExportsRootResolved = true;
    }
    return cache.resolvedMixExportsRoot;
}

int runtimeMixSearchPriority(const std::string& path) {
    const std::string lower = normalizedLowerPath(path);
    const std::string fileName =
        toLowerAscii(std::filesystem::path(lower).filename().string());
    if (fileName == "expandmd02.mix") {
        return -30;
    }
    if (fileName == "expandmd01.mix") {
        return -20;
    }
    if (fileName == "ra2md.mix") {
        return -10;
    }
    if (lower.find("/ra2md/localmd.mix") != std::string::npos) {
        return 0;
    }
    if (lower.find("/ra2md/conqmd.mix") != std::string::npos) {
        return 10;
    }
    if (lower.find("/ra2md/") != std::string::npos) {
        return 20;
    }
    if (lower.find("/ra2/local.mix") != std::string::npos) {
        return 30;
    }
    if (lower.find("/ra2/conquer.mix") != std::string::npos) {
        return 40;
    }
    if (fileName == "expand01.mix") {
        return 45;
    }
    if (fileName == "ra2.mix") {
        return 46;
    }
    if (lower.find("/ra2/") != std::string::npos) {
        return 50;
    }
    return 100;
}

bool isRuntimeSidebarResourceFileName(const std::string& fileName) {
    const std::string lowerFile = toLowerAscii(fileName);
    return lowerFile == "credits.shp"
        || lowerFile == "top.shp"
        || lowerFile == "side1.shp"
        || lowerFile == "side2.shp"
        || lowerFile == "side2b.shp"
        || lowerFile == "side3.shp"
        || lowerFile == "addon.shp"
        || lowerFile == "tabs.shp"
        || lowerFile == "tab00.shp"
        || lowerFile == "tab01.shp"
        || lowerFile == "tab02.shp"
        || lowerFile == "tab03.shp"
        || lowerFile == "diplobtn.shp"
        || lowerFile == "optbtn.shp"
        || lowerFile == "repair.shp"
        || lowerFile == "sell.shp"
        || lowerFile == "r-dn.shp"
        || lowerFile == "r-up.shp"
        || lowerFile == "gclock2.shp"
        || lowerFile == "power.shp"
        || lowerFile == "powerp.shp"
        || lowerFile == "radar.shp"
        || lowerFile == "pips.shp"
        || lowerFile == "sidebar.pal";
}

int runtimeMixSearchPriorityForFile(
    const std::string& path,
    const std::string& fileName
) {
    const std::string lowerPath = normalizedLowerPath(path);
    const std::string lowerFile = toLowerAscii(fileName);
    const std::string mixName =
        toLowerAscii(std::filesystem::path(lowerPath).filename().string());

    const bool loadingScreenResource =
        (lowerFile.rfind("ls800", 0) == 0
            && std::filesystem::path(lowerFile).extension().string() == ".shp")
        || lowerFile == "mplsu.pal"
        || lowerFile == "mplsuk.pal"
        || lowerFile == "mplsg.pal"
        || lowerFile == "mplsf.pal"
        || lowerFile == "mplsk.pal"
        || lowerFile == "mplsr.pal"
        || lowerFile == "mplsc.pal"
        || lowerFile == "mplsl.pal"
        || lowerFile == "mplsi.pal"
        || lowerFile == "mpyls.pal"
        || lowerFile == "mplsobs.pal";
    if (loadingScreenResource) {
        if (mixName == "loadmd.mix") {
            return -70;
        }
        if (mixName == "load.mix") {
            return -65;
        }
    }

    const bool sidebarResource =
        isRuntimeSidebarResourceFileName(lowerFile);
    if (sidebarResource) {
        if (mixName == "sidec02md.mix") {
            return -60;
        }
        if (mixName == "sidec01.mix" || mixName == "sidec02.mix") {
            return -55;
        }
        if (mixName == "conqmd.mix" || mixName == "conquer.mix") {
            return -20;
        }
    }

    const std::string extension =
        toLowerAscii(std::filesystem::path(lowerFile).extension().string());
    if (extension == ".shp" || extension == ".sha"
        || extension == ".vxl" || extension == ".hva") {
        if (mixName == "conqmd.mix") {
            return -50;
        }
        if (mixName == "conquer.mix") {
            return -45;
        }
        if (mixName == "cachemd.mix" || mixName == "cache.mix") {
            return -40;
        }
        if (mixName.rfind("iso", 0) == 0) {
            return -30;
        }
    }

    return runtimeMixSearchPriority(path);
}

bool isRuntimeObjectResourceMixCandidate(const std::string& path) {
    const std::string fileName =
        toLowerAscii(std::filesystem::path(path).filename().string());
    if (fileName.rfind("iso", 0) == 0
        && std::filesystem::path(fileName).extension().string() == ".mix") {
        return true;
    }
    static constexpr const char* ObjectMixNames[] = {
        "cachemd.mix",
        "conqmd.mix",
        "des.mix",
        "desert.mix",
        "expandmd02.mix",
        "expandmd01.mix",
        "genermd.mix",
        "localmd.mix",
        "loadmd.mix",
        "lun.mix",
        "lunar.mix",
        "ntrlmd.mix",
        "ra2md.mix",
        "snowmd.mix",
        "ubn.mix",
        "urbann.mix",
        "cameo.mix",
        "cameomd.mix",
        "sidec02md.mix",
        "cache.mix",
        "conquer.mix",
        "expand01.mix",
        "generic.mix",
        "local.mix",
        "load.mix",
        "neutral.mix",
        "ra2.mix",
        "sidec01.mix",
        "sidec02.mix",
        "sidenc01.mix",
        "sidenc02.mix",
        "sno.mix",
        "snow.mix",
        "tem.mix",
        "temperat.mix",
        "urb.mix",
        "urban.mix"
    };

    for (const char* candidate : ObjectMixNames) {
        if (fileName == candidate) {
            return true;
        }
    }
    return false;
}

int runtimeLooseResourceSearchPriority(const std::string& path) {
    const std::string lower = normalizedLowerPath(path);
    if (lower.find("/extracted_buildings/") != std::string::npos) {
        return 0;
    }
    if (lower.find("/ra2md/localmd/") != std::string::npos) {
        return 10;
    }
    if (lower.find("/ra2md/") != std::string::npos) {
        return 20;
    }
    if (lower.find("/ra2/") != std::string::npos) {
        return 30;
    }
    return 100;
}

bool isRuntimeObjectLooseExtension(const std::filesystem::path& path) {
    const std::string extension = toLowerAscii(path.extension().string());
    return extension == ".shp"
        || extension == ".vxl"
        || extension == ".hva"
        || extension == ".tem"
        || extension == ".urb"
        || extension == ".ubn"
        || extension == ".des"
        || extension == ".sno"
        || extension == ".lun";
}

void appendRuntimeLooseResourcePathsFromRoot(
    const std::filesystem::path& root,
    std::vector<std::string>& paths
) {
    std::error_code errorCode;
    if (std::filesystem::is_regular_file(root, errorCode)) {
        if (isRuntimeObjectLooseExtension(root)) {
            paths.push_back(root.generic_string());
        }
        return;
    }

    if (!std::filesystem::is_directory(root, errorCode)) {
        return;
    }

    std::filesystem::recursive_directory_iterator iterator(
        root,
        std::filesystem::directory_options::skip_permission_denied,
        errorCode
    );
    const std::filesystem::recursive_directory_iterator end;
    while (!errorCode && iterator != end) {
        const std::filesystem::directory_entry& entry = *iterator;
        if (entry.is_regular_file(errorCode)
            && isRuntimeObjectLooseExtension(entry.path())) {
            paths.push_back(entry.path().generic_string());
        }
        iterator.increment(errorCode);
    }
}

std::vector<std::filesystem::path> runtimeLooseObjectSearchRoots(
    const std::filesystem::path& assetRoot
) {
    return {
        assetRoot,
        assetRoot / "ra2md" / "localmd",
        assetRoot / "expandmd02",
        assetRoot / "expandmd01",
        assetRoot / "cameomd",
        assetRoot / "langmd",
        assetRoot / "language",
        assetRoot / "extracted_overlays"
    };
}

void ensureRuntimeLooseResourceIndex(
    const std::string& assetRootPath,
    RuntimeMapRenderCache& cache
) {
    if (cache.looseResourceIndexRootPath != assetRootPath) {
        cache.looseResourceIndexRootPath = assetRootPath;
        cache.looseResourceIndexBuilt = false;
        cache.looseResourcePathsByName.clear();
    }

    if (cache.looseResourceIndexBuilt || assetRootPath.empty()) {
        return;
    }

    cache.looseResourceIndexBuilt = true;
    const std::filesystem::path root(assetRootPath);
    std::error_code errorCode;
    if (!std::filesystem::is_directory(root, errorCode)) {
        return;
    }

    std::vector<std::string> paths;
    for (const std::filesystem::path& searchRoot :
        runtimeLooseObjectSearchRoots(root)) {
        appendRuntimeLooseResourcePathsFromRoot(searchRoot, paths);
    }

    // A custom asset root may not use the extracted RA2/YR folder layout.
    if (paths.empty()) {
        appendRuntimeLooseResourcePathsFromRoot(root, paths);
    }

    std::sort(
        paths.begin(),
        paths.end(),
        [](const std::string& left, const std::string& right) {
            const int leftPriority = runtimeLooseResourceSearchPriority(left);
            const int rightPriority = runtimeLooseResourceSearchPriority(right);
            if (leftPriority != rightPriority) {
                return leftPriority < rightPriority;
            }
            return normalizedLowerPath(left) < normalizedLowerPath(right);
        }
    );

    for (const std::string& path : paths) {
        const std::string key =
            toLowerAscii(std::filesystem::path(path).filename().string());
        cache.looseResourcePathsByName.try_emplace(key, path);
    }
}

bool findRuntimeLooseResourceByName(
    const std::string& rootPath,
    const std::string& assetRootPath,
    const std::string& fileName,
    RuntimeMapRenderCache& cache,
    std::string& resolvedPath
) {
    if (rootPath.empty() || fileName.empty()) {
        return false;
    }

    if (normalizedLowerPath(rootPath) == normalizedLowerPath(assetRootPath)) {
        ensureRuntimeLooseResourceIndex(assetRootPath, cache);
        const auto it =
            cache.looseResourcePathsByName.find(toLowerAscii(fileName));
        if (it == cache.looseResourcePathsByName.end()) {
            return false;
        }

        resolvedPath = it->second;
        return true;
    }

    return findFileByNameCaseInsensitive(rootPath, fileName, resolvedPath);
}

void ensureRuntimeMixArchivePaths(
    const std::string& assetRootPath,
    RuntimeMapRenderCache& cache
) {
    if (cache.mixArchiveRootPath != assetRootPath) {
        cache.mixArchiveRootPath = assetRootPath;
        cache.mixArchivePathsScanned = false;
        cache.mixArchivePaths.clear();
        cache.mixArchivesByPath.clear();
    }

    if (cache.mixArchivePathsScanned || assetRootPath.empty()) {
        return;
    }

    cache.mixArchivePathsScanned = true;
    const std::filesystem::path root(assetRootPath);
    std::error_code errorCode;
    if (!std::filesystem::is_directory(root, errorCode)) {
        return;
    }

    const auto addKnownMix = [&cache](const std::filesystem::path& path) {
        std::error_code existsError;
        if (!std::filesystem::is_regular_file(path, existsError)) {
            return;
        }
        const std::string pathString = path.generic_string();
        if (!isRuntimeObjectResourceMixCandidate(pathString)) {
            return;
        }
        if (std::find(
                cache.mixArchivePaths.begin(),
                cache.mixArchivePaths.end(),
                pathString
            ) == cache.mixArchivePaths.end()) {
            cache.mixArchivePaths.push_back(pathString);
        }
    };

    const std::filesystem::path ra2 = root / "ra2";
    const std::filesystem::path ra2md = root / "ra2md";
    const char* knownRa2mdMixes[] = {
        "conqmd.mix",
        "cachemd.mix",
        "localmd.mix",
        "loadmd.mix",
        "sidec02md.mix",
        "cameomd.mix",
        // Retail Yuri's Revenge calls this genermd.mix. Omitting it silently
        // falls back to RA2's generic.mix (including its unused fortress wall).
        "genermd.mix",
        "des.mix",
        "desert.mix",
        "lun.mix",
        "lunar.mix",
        "snowmd.mix",
        "ubn.mix",
        "urbann.mix",
        "isodes.mix",
        "isodesmd.mix",
        "isogenmd.mix",
        "isolun.mix",
        "isolunmd.mix",
        "isosnomd.mix",
        "isotemmd.mix",
        "isoubn.mix",
        "isoubnmd.mix",
        "isourbmd.mix"
    };
    const char* knownRa2Mixes[] = {
        "conquer.mix",
        "cache.mix",
        "local.mix",
        "load.mix",
        "sidec01.mix",
        "sidec02.mix",
        "sidenc01.mix",
        "sidenc02.mix",
        "cameo.mix",
        "generic.mix",
        "neutral.mix",
        "sno.mix",
        "snow.mix",
        "tem.mix",
        "temperat.mix",
        "urb.mix",
        "urban.mix",
        "isogen.mix",
        "isosnow.mix",
        "isotemp.mix",
        "isourb.mix"
    };
    for (const char* mixName : knownRa2mdMixes) {
        addKnownMix(ra2md / mixName);
    }
    for (const char* mixName : knownRa2Mixes) {
        addKnownMix(ra2 / mixName);
    }
    addKnownMix(root / "langmd" / "cameomd.mix");
    addKnownMix(root / "language" / "cameo.mix");
    addKnownMix(root / "expandmd02.mix");
    addKnownMix(root / "expandmd01.mix");
    addKnownMix(root / "ra2md.mix");
    addKnownMix(root / "expand01.mix");
    addKnownMix(root / "ra2.mix");

    if (!cache.mixArchivePaths.empty()) {
        std::sort(
            cache.mixArchivePaths.begin(),
            cache.mixArchivePaths.end(),
            [](const std::string& left, const std::string& right) {
                const int leftPriority = runtimeMixSearchPriority(left);
                const int rightPriority = runtimeMixSearchPriority(right);
                if (leftPriority != rightPriority) {
                    return leftPriority < rightPriority;
                }
                return normalizedLowerPath(left) < normalizedLowerPath(right);
            }
        );
        return;
    }

    std::filesystem::recursive_directory_iterator iterator(
        root,
        std::filesystem::directory_options::skip_permission_denied,
        errorCode
    );
    const std::filesystem::recursive_directory_iterator end;
    while (!errorCode && iterator != end) {
        const std::filesystem::directory_entry& entry = *iterator;
        if (entry.is_regular_file(errorCode)
            && toLowerAscii(entry.path().extension().string()) == ".mix") {
            const std::string path = entry.path().generic_string();
            if (isRuntimeObjectResourceMixCandidate(path)) {
                cache.mixArchivePaths.push_back(path);
            }
        }
        iterator.increment(errorCode);
    }

    std::sort(
        cache.mixArchivePaths.begin(),
        cache.mixArchivePaths.end(),
        [](const std::string& left, const std::string& right) {
            const int leftPriority = runtimeMixSearchPriority(left);
            const int rightPriority = runtimeMixSearchPriority(right);
            if (leftPriority != rightPriority) {
                return leftPriority < rightPriority;
            }
            return normalizedLowerPath(left) < normalizedLowerPath(right);
        }
    );
}

RuntimeMixArchiveCacheEntry* loadRuntimeMixArchiveFromCache(
    const std::string& mixPath,
    RuntimeMapRenderCache& cache
) {
    auto [it, inserted] = cache.mixArchivesByPath.try_emplace(mixPath);
    RuntimeMixArchiveCacheEntry& entry = it->second;
    if (!entry.loadAttempted) {
        entry.loadAttempted = true;
        entry.loaded = entry.archive.loadFromFile(mixPath)
            && entry.archive.isIndexReadable();
        entry.errorMessage = entry.archive.getErrorMessage();
        if (!entry.loaded && entry.errorMessage.empty()) {
            entry.errorMessage = "MIX archive index is not readable: " + mixPath;
        }
    }

    return entry.loaded ? &entry : nullptr;
}

bool loadRuntimeResourceBytesFromMixArchives(
    const std::string& assetRootPath,
    const std::string& fileName,
    RuntimeMapRenderCache& cache,
    std::vector<unsigned char>& bytes,
    std::string& sourceName,
    std::string& errorMessage
) {
    ensureRuntimeMixArchivePaths(assetRootPath, cache);

    std::vector<std::string> searchPaths = cache.mixArchivePaths;
    std::stable_sort(
        searchPaths.begin(),
        searchPaths.end(),
        [&fileName](const std::string& left, const std::string& right) {
            const int leftPriority =
                runtimeMixSearchPriorityForFile(left, fileName);
            const int rightPriority =
                runtimeMixSearchPriorityForFile(right, fileName);
            if (leftPriority != rightPriority) {
                return leftPriority < rightPriority;
            }
            return normalizedLowerPath(left) < normalizedLowerPath(right);
        }
    );

    for (const std::string& mixPath : searchPaths) {
        RuntimeMixArchiveCacheEntry* archiveEntry =
            loadRuntimeMixArchiveFromCache(mixPath, cache);
        if (archiveEntry == nullptr) {
            continue;
        }

        const MixEntry* mixEntry = archiveEntry->archive.findEntryByName(fileName);
        if (mixEntry == nullptr) {
            continue;
        }

        std::vector<std::uint8_t> entryBytes;
        if (!archiveEntry->archive.readEntryData(
                *mixEntry,
                entryBytes,
                errorMessage
            )) {
            return false;
        }

        bytes.assign(entryBytes.begin(), entryBytes.end());
        sourceName = mixPath + "!" + fileName;
        return true;
    }

    errorMessage = "resource was not found in loose files or MIX archives: "
        + fileName;
    return false;
}

bool runtimePathUsesDefaultAssetRoot(
    const std::string& resourcePath,
    const std::string& assetRootPath
);

bool runtimeAssetRootHasMixArchives(
    const std::string& assetRootPath,
    RuntimeMapRenderCache& cache
) {
    ensureRuntimeMixArchivePaths(assetRootPath, cache);
    return !cache.mixArchivePaths.empty();
}

bool loadRuntimeResourceBytesByName(
    const std::vector<std::string>& looseRootPaths,
    const std::string& assetRootPath,
    const std::string& fileName,
    RuntimeMapRenderCache& cache,
    std::vector<unsigned char>& bytes,
    std::string& sourceName,
    std::string& errorMessage
) {
    bytes.clear();
    sourceName.clear();
    errorMessage.clear();

    const auto tryLooseRoot = [&](const std::string& rootPath)
        -> std::optional<bool> {
        std::string resolvedPath;
        if (!findRuntimeLooseResourceByName(
                rootPath, assetRootPath, fileName, cache, resolvedPath)) {
            return std::nullopt;
        }
        if (!loadBytes(resolvedPath, bytes, errorMessage)) {
            return false;
        }
        sourceName = resolvedPath;
        errorMessage.clear();
        return true;
    };

    // Explicit roots outside the default exports retain caller overrides.
    for (const std::string& rootPath : looseRootPaths) {
        if (!runtimePathUsesDefaultAssetRoot(rootPath, assetRootPath)) {
            if (const auto loaded = tryLooseRoot(rootPath); loaded.has_value()) {
                return *loaded;
            }
        }
    }

    // Stock archives are authoritative over default exported loose copies.
    if (loadRuntimeResourceBytesFromMixArchives(
            assetRootPath,
            fileName,
            cache,
            bytes,
            sourceName,
            errorMessage
        )) {
        return true;
    }
    bytes.clear();
    sourceName.clear();
    if (runtimeAssetRootHasMixArchives(assetRootPath, cache)) {
        return false;
    }

    // A root without archives is a standalone loose/custom installation.
    for (const std::string& rootPath : looseRootPaths) {
        if (runtimePathUsesDefaultAssetRoot(rootPath, assetRootPath)) {
            if (const auto loaded = tryLooseRoot(rootPath); loaded.has_value()) {
                return *loaded;
            }
        }
    }

    return false;
}

bool equalAsciiNoCase(const std::string& left, const std::string& right) {
    return toLowerAscii(left) == toLowerAscii(right);
}

void addUniqueCandidate(std::vector<std::string>& candidates, const std::string& candidate) {
    if (!candidate.empty()
        && std::find(candidates.begin(), candidates.end(), candidate)
            == candidates.end()) {
        candidates.push_back(candidate);
    }
}

#include "render/geometry/RuntimeGeometryQueryDeclarations.inl"

char newTheaterCharForExtension(const std::string& tileExtension) {
    const std::string extension = toLowerAscii(tileExtension);
    if (extension == ".tem") {
        return 't';
    }
    if (extension == ".urb") {
        return 'u';
    }
    if (extension == ".ubn") {
        return 'n';
    }
    if (extension == ".des") {
        return 'd';
    }
    if (extension == ".lun") {
        return 'l';
    }
    if (extension == ".sno") {
        return 'a';
    }
    return '\0';
}

bool artIdSupportsNewTheater(const std::string& artId) {
    if (artId.size() < 2) {
        return false;
    }

    const char first =
        static_cast<char>(std::toupper(static_cast<unsigned char>(artId[0])));
    const char second =
        static_cast<char>(std::toupper(static_cast<unsigned char>(artId[1])));
    return (first == 'G' || first == 'N' || first == 'C' || first == 'Y')
        && (second == 'A'
            || second == 'T'
            || second == 'U'
            || second == 'D'
            || second == 'L'
            || second == 'N');
}

const UnitType* findObjectUnitTypeForRender(
    const RuntimeMapRenderContext& context,
    const WorldObjectInstance& object
) {
    if (const auto* metadata = runtimeGeometryMetadataForObject(object, context)) {
        return metadata->unit;
    }
    if (context.rules == nullptr) {
        return nullptr;
    }

    if (object.kind == WorldObjectKind::Infantry) {
        return context.rules->findUnitType("infantry", object.type);
    }

    if (object.kind != WorldObjectKind::Unit) {
        return nullptr;
    }

    const UnitType* unitType =
        context.rules->findUnitType("vehicle", object.type);
    if (unitType == nullptr) {
        unitType = context.rules->findUnitType("aircraft", object.type);
    }
    return unitType;
}

const UnitType* findUnitTypeByAnyRenderList(
    const RuntimeMapRenderContext& context,
    const std::string& id
) {
    if (context.rules == nullptr) {
        return nullptr;
    }

    if (const UnitType* infantry =
            context.rules->findUnitType("infantry", id)) {
        return infantry;
    }
    if (const UnitType* vehicle =
            context.rules->findUnitType("vehicle", id)) {
        return vehicle;
    }
    return context.rules->findUnitType("aircraft", id);
}

bool runtimeObjectUsesDockUnloadingClassForRender(
    const WorldObjectInstance& object
) {
    return equalAsciiNoCase(object.mission, "dock")
        || equalAsciiNoCase(object.mission, "unload")
        || equalAsciiNoCase(object.mission, "unloading");
}

bool runtimeObjectUsesDeployedUnloadingClassForRender(
    const WorldObjectInstance& object,
    const UnitType& unitType
) {
    if (!unitType.deployToLand || !unitType.isSimpleDeployer) {
        return false;
    }
    const std::string mission = toLowerAscii(object.mission);
    return object.deployed
        || mission == "deploying"
        || mission == "deployed"
        || mission == "deployedidle"
        || mission == "deployedfire"
        || mission == "deployedareafire"
        || mission == "deployedareafirecomplete"
        || mission == "undeploying";
}

const std::string* runtimeObjectUnloadingClassForRender(
    const WorldObjectInstance& object,
    const RuntimeMapRenderContext& context
) {
    if (object.kind != WorldObjectKind::Unit) {
        return nullptr;
    }

    const UnitType* unitType = findObjectUnitTypeForRender(context, object);
    if (unitType == nullptr || unitType->unloadingClass.empty()) {
        return nullptr;
    }

    if (!runtimeObjectUsesDockUnloadingClassForRender(object)
        && !runtimeObjectUsesDeployedUnloadingClassForRender(
            object,
            *unitType
        )) {
        return nullptr;
    }

    return &unitType->unloadingClass;
}

std::string resolveObjectVisualTypeIdForRender(
    const WorldObjectInstance& object,
    const RuntimeMapRenderContext& context
) {
    if (const auto* metadata = runtimeGeometryMetadataForObject(object, context)) {
        return metadata->visualTypeId;
    }
    const std::string* unloadingClass =
        runtimeObjectUnloadingClassForRender(object, context);
    return unloadingClass == nullptr ? object.type : *unloadingClass;
}

bool runtimeRenderUsesArcticArt(const RuntimeMapRenderContext& context) {
    if (context.theater != nullptr && !context.theater->getTileExtension().empty())
        return runtimeArcticTheater(context.theater->getTileExtension());
    return context.mapFacts != nullptr && runtimeArcticTheater(context.mapFacts->theater);
}

std::string resolveObjectArtId(
    const WorldObjectInstance& object,
    const RuntimeMapRenderContext& context
) {
    if (const auto* metadata = runtimeGeometryMetadataForObject(object, context)) {
        return metadata->artId;
    }
    if (context.rules == nullptr) {
        return resolveObjectVisualTypeIdForRender(object, context);
    }

    const std::string visualTypeId =
        resolveObjectVisualTypeIdForRender(object, context);

    if (object.kind == WorldObjectKind::Structure) {
        const BuildingType* buildingType =
            context.rules->findBuildingType(object.type);
        if (buildingType != nullptr) {
            return runtimeArcticArtId(buildingType->image.empty() ? object.type : buildingType->image,
                buildingType->alternateArcticArt, runtimeRenderUsesArcticArt(context));
        }
        return object.type;
    }

    if (object.kind == WorldObjectKind::Infantry) {
        const UnitType* infantryType =
            findUnitTypeByAnyRenderList(context, visualTypeId);
        if (infantryType != nullptr) {
            return runtimeArcticArtId(infantryType->image.empty() ? visualTypeId : infantryType->image,
                infantryType->alternateArcticArt, runtimeRenderUsesArcticArt(context));
        }
        return visualTypeId;
    }

    const UnitType* vehicleType =
        findUnitTypeByAnyRenderList(context, visualTypeId);
    if (vehicleType != nullptr) {
        return runtimeArcticArtId(vehicleType->image.empty() ? visualTypeId : vehicleType->image,
            vehicleType->alternateArcticArt, runtimeRenderUsesArcticArt(context));
    }
    return visualTypeId;
}

const ArtType* findArtTypeForObject(
    const WorldObjectInstance& object,
    const RuntimeMapRenderContext& context
) {
    if (const auto* metadata = runtimeGeometryMetadataForObject(object, context)) {
        return metadata->art;
    }
    if (context.art == nullptr) {
        return nullptr;
    }

    const std::string artId = resolveObjectArtId(object, context);
    const ArtType* artType = context.art->findArtType(artId);
    if (artType != nullptr) {
        return artType;
    }

    const std::string visualTypeId =
        resolveObjectVisualTypeIdForRender(object, context);
    if (!equalAsciiNoCase(visualTypeId, object.type)) {
        artType = context.art->findArtType(visualTypeId);
        if (artType != nullptr) {
            return artType;
        }
    }

    return context.art->findArtType(object.type);
}

bool runtimeArtShadowEnabled(
    const ArtType* artType,
    bool categoryDefault
) {
    if (artType == nullptr || !artType->shadowSpecified) {
        return categoryDefault;
    }
    return artType->shadow;
}

bool runtimeObjectRulesSuppressShadow(
    const WorldObjectInstance& object,
    const RuntimeMapRenderContext& context
);

bool runtimeObjectUsesImplicitSpriteUnitFacingLayout(
    const WorldObjectInstance& object,
    const RuntimeMapRenderContext& context
) {
    const ArtType* artType = findArtTypeForObject(object, context);
    return object.kind == WorldObjectKind::Unit
        && artType != nullptr
        && !artType->voxel
        && artType->facings <= 0
        && artType->walkFrames > 0;
}

bool runtimeObjectSourceHasSplitShadow(
    const WorldObjectInstance& object,
    const RuntimeMapRenderContext& context
) {
    if (runtimeObjectUsesImplicitSpriteUnitFacingLayout(object, context)
        && runtimeObjectRulesSuppressShadow(object, context)) {
        return false;
    }
    return runtimeArtShadowEnabled(findArtTypeForObject(object, context), true);
}

bool runtimeObjectRulesSuppressShadow(
    const WorldObjectInstance& object,
    const RuntimeMapRenderContext& context
) {
    if (context.rules == nullptr) {
        return false;
    }
    if (object.kind == WorldObjectKind::Structure) {
        const BuildingType* building =
            context.rules->findBuildingType(object.type);
        return building != nullptr && building->noShadow;
    }
    const UnitType* unit = findObjectUnitTypeForRender(context, object);
    return unit != nullptr && unit->noShadow;
}

bool runtimeObjectShouldRenderShadow(
    const WorldObjectInstance& object,
    const RuntimeMapRenderContext& context
) {
    return (object.alive || object.mission == "CrashingWreck" || runtimeStructureIsSelling(object))
        && !object.rubble
        && context.shadowsEnabled
        && !object.submerged
        && !object.cloaked
        && runtimeObjectSourceHasSplitShadow(object, context)
        && !runtimeObjectRulesSuppressShadow(object, context);
}

int runtimeObjectVoxelShadowSection(
    const WorldObjectInstance& object,
    const RuntimeMapRenderContext& context
) {
    const ArtType* artType = findArtTypeForObject(object, context);
    return artType == nullptr || artType->shadowIndex < 0
        ? 0
        : artType->shadowIndex;
}

int runtimeEffectiveVoxelShadowSection(int requested, int sectionCount) {
    return requested >= 0 && requested < sectionCount ? requested : 0;
}

int runtimeObjectMaxHealthForRender(
    const WorldObjectInstance& object,
    const RuntimeMapRenderContext& context
) {
    if (context.rules == nullptr) {
        return 0;
    }

    if (object.kind == WorldObjectKind::Structure) {
        const BuildingType* buildingType =
            context.rules->findBuildingType(object.type);
        return buildingType == nullptr ? 0 : buildingType->strength;
    }

    const UnitType* unitType = context.rules->findUnitType(
        object.kind == WorldObjectKind::Infantry ? "infantry" : "vehicle",
        object.type
    );
    if (unitType == nullptr && object.kind == WorldObjectKind::Unit) {
        unitType = context.rules->findUnitType("aircraft", object.type);
    }
    return unitType == nullptr ? 0 : unitType->strength;
}

bool runtimeObjectIsDamaged(
    const WorldObjectInstance& object,
    const RuntimeMapRenderContext& context
) {
    if (object.health <= 0) {
        return false;
    }

    const int maxHealth = runtimeObjectMaxHealthForRender(object, context);
    return maxHealth > 0 && object.health * 2 < maxHealth;
}

bool runtimeObjectIsRenderableRubble(const WorldObjectInstance& object) {
    return object.kind == WorldObjectKind::Structure
        && object.rubble
        && !object.alive;
}

bool runtimeObjectIsGroundRubble(
    const WorldObjectInstance& object,
    const RuntimeMapRenderContext& context
) {
    return runtimeObjectIsRenderableRubble(object)
        && !runtimeBuildingCollapseForObject(context.buildingCollapses, object.instanceId,
            context.animationTick, context.fixedTickHz);
}

bool runtimeWorldObjectBodyShouldRender(const WorldObjectInstance& object) {
    return object.alive || runtimeObjectIsRenderableRubble(object) || runtimeStructureIsSelling(object);
}

bool runtimeStructureShouldRenderLiveLayers(
    const WorldObjectInstance& object
) {
    return object.kind == WorldObjectKind::Structure
        && object.alive
        && !object.rubble;
}

bool runtimeTerrainObjectShouldRender(const WorldTerrainObject& object) {
    return object.alive;
}

bool runtimeTerrainObjectIsDamaged(const WorldTerrainObject& object) {
    return object.alive
        && object.health > 0
        && object.strength > 0
        && static_cast<long long>(object.health) * 2
            < static_cast<long long>(object.strength);
}

const RuntimeGateRenderSnapshot* runtimeGateSnapshotForObject(
    const RuntimeMapRenderContext& context,
    int objectId
) {
    if (objectId < 0 || context.gateSnapshots == nullptr) {
        return nullptr;
    }
    const auto found = std::find_if(
        context.gateSnapshots->begin(),
        context.gateSnapshots->end(),
        [objectId](const RuntimeGateRenderSnapshot& snapshot) {
            return snapshot.objectId == objectId;
        }
    );
    return found == context.gateSnapshots->end() ? nullptr : &*found;
}

bool runtimeObjectUsesGateArtForRender(
    const WorldObjectInstance& object,
    const RuntimeMapRenderContext& context,
    const ArtType* artType
) {
    if (!runtimeStructureShouldRenderLiveLayers(object)
        || object.buildAnimTicksRemaining > 0
        || artType == nullptr
        || artType->gateStages <= 0
        || runtimeGateSnapshotForObject(context, object.instanceId) == nullptr) {
        return false;
    }
    if (context.rules == nullptr) {
        return true;
    }
    const BuildingType* buildingType =
        context.rules->findBuildingType(object.type);
    return buildingType != nullptr && buildingType->gate;
}

int runtimeGateStageForSnapshot(
    const RuntimeGateRenderSnapshot& snapshot,
    int gateStages
) {
    const int finalStage = std::max(0, gateStages);
    double progress = std::isfinite(snapshot.normalizedProgress)
        ? snapshot.normalizedProgress
        : 0.0;
    progress = std::clamp(progress, 0.0, 1.0);
    const int forwardStage = std::clamp(
        static_cast<int>(std::lround(
            progress * static_cast<double>(finalStage)
        )),
        0,
        finalStage
    );
    switch (snapshot.phase) {
    case RuntimeGateRenderPhase::Closed:
        return 0;
    case RuntimeGateRenderPhase::Opening:
        return forwardStage;
    case RuntimeGateRenderPhase::Open:
        return finalStage;
    case RuntimeGateRenderPhase::Closing:
        return finalStage - forwardStage;
    }
    return 0;
}

int runtimeGateFrameForObject(
    const WorldObjectInstance& object,
    const RuntimeMapRenderContext& context,
    const ArtType* artType,
    int visibleFrameCount
) {
    if (visibleFrameCount <= 0
        || !runtimeObjectUsesGateArtForRender(object, context, artType)) {
        return -1;
    }
    const RuntimeGateRenderSnapshot* snapshot =
        runtimeGateSnapshotForObject(context, object.instanceId);
    if (snapshot == nullptr || artType == nullptr) {
        return -1;
    }

    const int healthyBankSize = artType->gateStages + 1;
    int frame = std::min(
        runtimeGateStageForSnapshot(*snapshot, artType->gateStages),
        visibleFrameCount - 1
    );
    if (!runtimeObjectIsDamaged(object, context)) {
        return frame;
    }

    // Stock gates store a complete damaged transition immediately after the
    // healthy 0..GateStages bank, followed by the rubble frame.
    if (healthyBankSize > 0
        && visibleFrameCount >= healthyBankSize * 2) {
        frame += healthyBankSize;
        return std::min(
            frame,
            std::min(visibleFrameCount - 1, healthyBankSize * 2 - 1)
        );
    }
    return -1;
}

std::string resolveObjectSpriteImageId(
    const WorldObjectInstance& object,
    const RuntimeMapRenderContext& context
) {
    if (const auto* metadata = runtimeGeometryMetadataForObject(object, context)) {
        return metadata->spriteImageId;
    }
    const std::string artId = resolveObjectArtId(object, context);
    const ArtType* artType = context.art == nullptr
        ? nullptr
        : context.art->findArtType(artId);
    if (artType == nullptr && context.art != nullptr) {
        const std::string visualTypeId =
            resolveObjectVisualTypeIdForRender(object, context);
        if (!equalAsciiNoCase(visualTypeId, object.type)) {
            artType = context.art->findArtType(visualTypeId);
        }
    }
    if (artType == nullptr && context.art != nullptr) {
        artType = context.art->findArtType(object.type);
    }

    if (artType == nullptr) {
        return artId;
    }

    const std::string imageId = artType->image.empty() ? artId : artType->image;
    if (context.specialMechanismSnapshots != nullptr)
        for (const auto& snapshot : *context.specialMechanismSnapshots)
            if ((snapshot.kind == "missileDeck" || snapshot.kind == "noSpawnDeck") && snapshot.objectId == object.instanceId)
                return imageId + "WO";
    return imageId;
}

std::vector<std::string> resolveObjectSpriteImageIdCandidates(
    const WorldObjectInstance& object,
    const RuntimeMapRenderContext& context
) {
    std::vector<std::string> candidates;
    const std::string artId = resolveObjectArtId(object, context);
    const ArtType* artType = context.art == nullptr
        ? nullptr
        : context.art->findArtType(artId);
    if (artType == nullptr && context.art != nullptr) {
        const std::string visualTypeId =
            resolveObjectVisualTypeIdForRender(object, context);
        if (!equalAsciiNoCase(visualTypeId, object.type)) {
            artType = context.art->findArtType(visualTypeId);
        }
    }
    if (artType == nullptr && context.art != nullptr) {
        artType = context.art->findArtType(object.type);
    }

    const std::string baseName =
        artType == nullptr
            ? artId
            : (artType->image.empty() ? artId : artType->image);
    if (baseName.empty()) {
        return candidates;
    }

    const std::filesystem::path basePath(baseName);
    if (!basePath.extension().empty()) {
        addUniqueCandidate(candidates, basePath.filename().string());
        return candidates;
    }

    const std::string lowerBaseName = toLowerAscii(baseName);
    if (artType != nullptr
        && artType->newTheater
        && context.theater != nullptr
        && artIdSupportsNewTheater(artId)
        && lowerBaseName.size() >= 2) {
        const char newTheaterChar =
            newTheaterCharForExtension(context.theater->getTileExtension());
        if (newTheaterChar != '\0') {
            std::string newTheaterName = lowerBaseName;
            newTheaterName[1] = newTheaterChar;
            addUniqueCandidate(candidates, newTheaterName);

            std::string genericName = lowerBaseName;
            genericName[1] = 'g';
            addUniqueCandidate(candidates, genericName);
        }
    }

    addUniqueCandidate(candidates, baseName);
    return candidates;
}

std::vector<std::string> resolveObjectVoxelImageIdCandidates(
    const WorldObjectInstance& object,
    const RuntimeMapRenderContext& context
) {
    std::vector<std::string> candidates;
    const std::string artId = resolveObjectArtId(object, context);
    const std::string visualTypeId =
        resolveObjectVisualTypeIdForRender(object, context);
    if (context.specialMechanismSnapshots != nullptr)
        for (const auto& snapshot : *context.specialMechanismSnapshots)
            if ((snapshot.kind == "missileDeck" || snapshot.kind == "noSpawnDeck") && snapshot.objectId == object.instanceId)
                addUniqueCandidate(candidates, resolveObjectSpriteImageId(object, context));
    addUniqueCandidate(candidates, artId);

    if (object.kind == WorldObjectKind::Unit) {
        addUniqueCandidate(candidates, visualTypeId);
        addUniqueCandidate(candidates, object.type);
    }

    const std::string spriteImageId =
        resolveObjectSpriteImageId(object, context);
    addUniqueCandidate(candidates, spriteImageId);

    if (context.art != nullptr) {
        const ArtType* objectArtType = context.art->findArtType(object.type);
        if (objectArtType != nullptr && !objectArtType->image.empty()) {
            addUniqueCandidate(candidates, objectArtType->image);
        }
    }

    return candidates;
}

std::vector<std::string> resolveAuxiliarySpriteImageIdCandidates(
    const std::string& imageId,
    const RuntimeMapRenderContext& context,
    const ArtType* fallbackArtType = nullptr
) {
    std::vector<std::string> candidates;
    if (imageId.empty()) {
        return candidates;
    }

    const ArtType* artType = context.art == nullptr
        ? nullptr
        : context.art->findArtType(imageId);
    const std::string baseName =
        artType == nullptr || artType->image.empty()
            ? imageId
            : artType->image;
    if (baseName.empty()) {
        return candidates;
    }

    const std::filesystem::path basePath(baseName);
    if (!basePath.extension().empty()) {
        addUniqueCandidate(candidates, basePath.filename().string());
        return candidates;
    }

    const std::string lowerBaseName = toLowerAscii(baseName);
    if (artType != nullptr
        && artType->theater
        && context.theater != nullptr) {
        const std::string theaterExtension =
            context.theater->getTileExtension();
        if (!theaterExtension.empty()) {
            addUniqueCandidate(
                candidates,
                lowerBaseName + theaterExtension
            );
            addUniqueCandidate(candidates, baseName + theaterExtension);
        }
    }
    // Stock grinder B/D layers omit NewTheater, but their normal and snow
    // canvases are separate G/A resources just like their building body.
    const bool grinderLayer=lowerBaseName.rfind("yagrnd_",0)==0;
    // Buildup filenames belong to the building's NewTheater policy even
    // when the MK image has no separate ART entry. Other auxiliary layers
    // keep their own policy; a palette fallback alone does not opt them in.
    const bool buildupNewTheater = fallbackArtType != nullptr
        && fallbackArtType->newTheater
        && equalAsciiNoCase(trimAsciiForRender(imageId),
            trimAsciiForRender(fallbackArtType->buildup));
    if (((artType != nullptr && (artType->newTheater || grinderLayer))
            || buildupNewTheater)
        && context.theater != nullptr
        && artIdSupportsNewTheater(baseName)
        && lowerBaseName.size() >= 2) {
        const char newTheaterChar =
            newTheaterCharForExtension(context.theater->getTileExtension());
        if (newTheaterChar != '\0') {
            std::string newTheaterName = lowerBaseName;
            newTheaterName[1] = newTheaterChar;
            addUniqueCandidate(candidates, newTheaterName);

            std::string genericName = lowerBaseName;
            genericName[1] = 'g';
            addUniqueCandidate(candidates, genericName);
        }
    }

    addUniqueCandidate(candidates, baseName);
    if (!equalAsciiNoCase(baseName, imageId)) {
        addUniqueCandidate(candidates, imageId);
    }
    return candidates;
}

bool objectUsesVoxelArt(
    const WorldObjectInstance& object,
    const RuntimeMapRenderContext& context
) {
    const ArtType* artType = findArtTypeForObject(object, context);
    return artType != nullptr && artType->voxel;
}

bool runtimeObjectHasTurretForRender(
    const WorldObjectInstance& object,
    const RuntimeMapRenderContext& context
) {
    if (const auto* metadata = runtimeGeometryMetadataForObject(object, context)) {
        return metadata->turret;
    }
    if (context.rules == nullptr || object.kind != WorldObjectKind::Unit) {
        return false;
    }

    const std::string visualTypeId =
        resolveObjectVisualTypeIdForRender(object, context);
    const UnitType* unitType =
        context.rules->findUnitType("vehicle", visualTypeId);
    if (unitType == nullptr) {
        unitType = context.rules->findUnitType("aircraft", visualTypeId);
    }
    return unitType != nullptr && unitType->turret;
}

int parseRuntimeOptionalInt(const std::string& value, int defaultValue = 0) {
    if (value.empty()) {
        return defaultValue;
    }

    try {
        return std::stoi(value);
    } catch (...) {
        return defaultValue;
    }
}

POINT runtimeFacingScreenVector(int facing) {
    if (facing < 0) {
        return {0, 0};
    }

    constexpr double pi = 3.14159265358979323846;
    const double screenRadians =
        (static_cast<double>(positiveModulo(facing, 256)) * 2.0 * pi / 256.0)
        - (pi / 2.0);
    return {
        static_cast<LONG>(std::lround(std::cos(screenRadians) * 1024.0)),
        static_cast<LONG>(std::lround(std::sin(screenRadians) * 1024.0))
    };
}

std::array<double, 3> runtimeVxlProjectionAxes();

POINT runtimeVoxelTurretOffset(
    const WorldObjectInstance& object,
    const RuntimeMapRenderContext& context,
    double fitScale = 0.0
) {
    const ArtType* artType = findArtTypeForObject(object, context);
    if (artType == nullptr || artType->turretOffset.empty()) {
        return {0, 0};
    }

    const int offsetLeptons = parseRuntimeOptionalInt(artType->turretOffset);
    if (offsetLeptons == 0) {
        return {0, 0};
    }

    // TurretOffset is model-space art data.  Apply it for every voxel unit so
    // mods and less common vehicles do not need per-model pixel corrections.
    static const double offsetScale = runtimeEnvDouble(
        "CONCORD_VXL_TURRET_OFFSET_SCALE",
        1.0,
        0.0,
        1.0
    );
    if (offsetScale <= 0.0) {
        return {0, 0};
    }

    constexpr double pi = 3.14159265358979323846;
    constexpr int vxlFacingBucketCount = 32;
    const int facingBucket = worldObjectArtFacingBucket(
        object.facing,
        vxlFacingBucketCount
    );
    const double facingAngle =
        static_cast<double>(facingBucket - 8)
        * ((pi * 2.0) / static_cast<double>(vxlFacingBucketCount));
    const double modelOffset =
        static_cast<double>(offsetLeptons) * 0.18 * offsetScale;
    const double rotatedX = modelOffset * std::cos(facingAngle);
    const double rotatedY = modelOffset * std::sin(facingAngle);
    const double effectiveScale = fitScale > 0.0 ? fitScale : 0.50;
    const auto projection = runtimeVxlProjectionAxes();
    const double screenX = (rotatedX - rotatedY) * projection[0] * effectiveScale;
    const double screenY = (rotatedX + rotatedY) * projection[1] * effectiveScale;
    return {
        static_cast<LONG>(std::lround(screenX)),
        static_cast<LONG>(std::lround(screenY))
    };
}

bool runtimeObjectLooksAircraftForRender(
    const WorldObjectInstance& object,
    const RuntimeMapRenderContext& context
) {
    if (const auto* metadata = runtimeGeometryMetadataForObject(object, context)) {
        return metadata->aircraft;
    }
    if (context.rules == nullptr
        || (object.kind != WorldObjectKind::Unit
            && object.kind != WorldObjectKind::Infantry)) {
        return false;
    }

    const UnitType* aircraftType =
        context.rules->findUnitType("aircraft", object.type);
    if (aircraftType != nullptr) {
        return true;
    }

    const UnitType* flyingType = object.kind == WorldObjectKind::Infantry
        ? context.rules->findUnitType("infantry", object.type)
        : context.rules->findUnitType("vehicle", object.type);
    if (flyingType == nullptr) {
        return false;
    }

    const std::string speedType = toLowerAscii(flyingType->speedType);
    const std::string movementZone = toLowerAscii(flyingType->movementZone);
    const std::string category = toLowerAscii(flyingType->category);
    const std::string locomotor = toLowerAscii(flyingType->locomotor);
    return flyingType->jumpJet
        || flyingType->consideredAircraft
        || containsText(speedType, "air")
        || containsText(speedType, "fly")
        || containsText(speedType, "winged")
        || containsText(movementZone, "air")
        || containsText(movementZone, "fly")
        || containsText(category, "air")
        || containsText(locomotor, "air")
        || containsText(locomotor, "fly");
}

constexpr int runtimeVoxelFacingBucketCount = 32;

int facingBucketForObject(
    const WorldObjectInstance& object,
    int facingCount
) {
    return worldObjectArtFacingBucket(object.facing, facingCount);
}

int facingBucketForFacingValue(
    int facing,
    int facingCount
) {
    return worldObjectArtFacingBucket(facing, facingCount);
}

int facingBucketForDirectionalShp(
    int facing,
    int facingCount
) {
    if (facingCount <= 1 || facing < 0) {
        return 0;
    }

    // Regular RA2 infantry/sequence SHPs store directional strips as
    // N, NW, W, SW, S, SE, E, NE. Runtime facings use the opposite,
    // clockwise screen order (N, NE, E, ...), so reverse the direction
    // without applying the authored map/VXL 45-degree conversion.
    const int reversedFacing = positiveModulo(-facing, 256);
    return (
        (reversedFacing * facingCount) + 128
    ) / 256 % facingCount;
}

int facingBucketForImplicitSpriteUnit(
    int facing,
    int facingCount
) {
    if (facingCount <= 1 || facing < 0) {
        return 0;
    }

    // Stock DLPH/SQD/DRON are the mobile-SHP exception: their implicit
    // direction strips run N, NE, E, SE, S, SW, W, NW (OpenRA Facings: -8).
    // Keep their clockwise source order instead of reversing it like the
    // regular infantry sequence layout.
    const int normalizedFacing = positiveModulo(facing, 256);
    return (
        (normalizedFacing * facingCount) + 128
    ) / 256 % facingCount;
}

int runtimeOreGatherFacingBucket(int facing) {
    if (facing < 0) {
        return 0;
    }

    // OREGATH's eight authored groups run N, NW, W, SW, S, SE, E, NE.
    // Normal object art uses the opposite screen-space order with a 45-degree
    // authored-facing bias, so using the generic bucket directly points the
    // gather pixels beside or behind the harvester.
    const int reversedFacing = positiveModulo(-facing, 256);
    return ((reversedFacing * 8) + 128) / 256 % 8;
}

int runtimeAnimationFrameDelayTicks(const ArtType* artType, int fixedTickHz) {
    return std::max(1, runtimeRuleFramesToTicks(
        runtimeRuleAnimationDelayFrames(artType ? artType->rate : 0), fixedTickHz));
}

int runtimeInfantrySequenceDelayTicks(const ArtType* artType, int fixedTickHz) {
    // Preserve the existing nominal sequence cadence pending a separate
    // InfantryClass sequence-rate comparison. AnimType::Rate is independent.
    const int legacyTicks = !artType || artType->rate <= 0 ? 6
        : std::clamp((900 + artType->rate / 2) / artType->rate, 1, 36);
    return std::max(1, static_cast<int>((static_cast<long long>(legacyTicks)
        * std::clamp(fixedTickHz, 1, 1000) + 29) / 30));
}

int selectRuntimeInfantryIdleFrame(
    const RuntimeMapRenderContext& context,
    const WorldObjectInstance& object,
    const ArtType& artType,
    int frameCount
) {
    struct IdleSequenceChoice {
        int start = 0;
        int frames = 0;
    };

    const IdleSequenceChoice choices[2] = {
        {artType.idle1StartFrame, artType.idle1Frames},
        {artType.idle2StartFrame, artType.idle2Frames}
    };
    const int seed = std::abs(
        (object.instanceId * 97)
        + (object.x * 37)
        + (object.y * 53)
        + (object.subCell * 19)
    );
    const int adjustedTick = static_cast<int>(static_cast<long long>(context.animationTick) * 30 / std::max(1, context.fixedTickHz)) + (seed % 420);
    const int choiceIndex = ((adjustedTick / 360) + (seed % 2)) % 2;
    const IdleSequenceChoice choice = choices[choiceIndex];
    if (choice.frames <= 0) {
        return -1;
    }

    const int waitTicks = 84 + (seed % 180);
    const int frameRate = runtimeInfantrySequenceDelayTicks(&artType, 30);
    const int playTicks = std::max(1, choice.frames * frameRate);
    const int cycleTicks = waitTicks + playTicks;
    const int cyclePosition = adjustedTick % cycleTicks;
    if (cyclePosition < waitTicks) {
        return -1;
    }

    const int idleFrame =
        choice.start + ((cyclePosition - waitTicks) / frameRate) % choice.frames;
    return idleFrame >= 0 && idleFrame < frameCount ? idleFrame : -1;
}

int animationFrameStep(
    const RuntimeMapRenderContext& context,
    const ArtType* artType
) {
    return std::max(
        1,
        context.animationTick / runtimeAnimationFrameDelayTicks(artType, context.fixedTickHz)
    );
}

int selectRuntimeAuxiliaryAnimationFrame(
    const RuntimeMapRenderContext& context,
    const ArtType* artType,
    int frameCount,
    bool mainFramesOnlyFallback
) {
    if (frameCount <= 1) {
        return 0;
    }

    int start = 0;
    if (artType != nullptr) {
        if (artType->hasAnimationLoopStart) {
            start = artType->animationLoopStart;
        } else if (artType->hasAnimationStart) {
            start = artType->animationStart;
        }
    }
    start = std::clamp(start, 0, std::max(0, frameCount - 1));

    int endExclusive = mainFramesOnlyFallback
        ? runtimeVisibleMainFrameCount(frameCount, true)
        : frameCount;
    if (artType != nullptr && artType->hasAnimationLoopEnd) {
        endExclusive = artType->animationLoopEnd;
        if (endExclusive <= start) {
            endExclusive = start + 1;
        }
    } else if (artType != nullptr && artType->hasAnimationEnd) {
        const int base =
            artType->hasAnimationStart ? artType->animationStart : start;
        endExclusive = base + std::max(1, artType->animationEnd);
    }
    endExclusive = std::clamp(endExclusive, start + 1, frameCount);

    const int span = std::max(1, endExclusive - start);
    const int step = animationFrameStep(context, artType);
    if (artType != nullptr && artType->pingPong && span > 1) {
        const int cycle = (span * 2) - 2;
        int position = step % cycle;
        if (position >= span) {
            position = cycle - position;
        }
        return start + position;
    }

    return start + (step % span);
}

struct RuntimeObjectSequenceFrameResult {
    bool matched = false;
    int frameIndex = 0;
    std::string sequenceName;
};

void addRuntimeSequenceCandidate(
    std::vector<std::string>& candidates,
    const std::string& name
) {
    if (name.empty()) {
        return;
    }
    const std::string token = toLowerAscii(name);
    for (const std::string& candidate : candidates) {
        if (toLowerAscii(candidate) == token) {
            return;
        }
    }
    candidates.push_back(name);
}

bool runtimeMissionHasToken(
    const std::string& mission,
    const std::string& token
) {
    return mission.find(token) != std::string::npos;
}

bool runtimeObjectShouldUseMovingSequence(
    const WorldObjectInstance& object
) {
    return object.hasRenderPosition && object.renderMoveActive;
}

bool runtimeInfantryIsSwimmingForRender(
    const WorldObjectInstance& object, const RuntimeMapRenderContext& context,
    RuntimeMapRenderCache* cache
);

int runtimeUnitAnimationTick(
    const WorldObjectInstance& object, const RuntimeMapRenderContext& context
);

std::vector<std::string> runtimeSequenceCandidatesForObjectState(
    const WorldObjectInstance& object, bool swimming
) {
    const std::string mission = toLowerAscii(object.mission);
    std::vector<std::string> candidates;

    if (object.airborne && mission == "paradropdrop") {
        addRuntimeSequenceCandidate(candidates, "Paradrop");
    }
    const bool undeploying = runtimeMissionHasToken(mission, "undeploy");
    const bool deployedFire =
        runtimeMissionHasToken(mission, "deployedfire");
    const bool deployFire =
        !deployedFire && runtimeMissionHasToken(mission, "deployfire");
    const bool deployedIdle =
        runtimeMissionHasToken(mission, "deployedidle")
        || runtimeMissionHasToken(mission, "deployidle")
        || mission == "deployed"
        || (object.deployed
            && !undeploying
            && !deployedFire
            && !deployFire
            && !runtimeMissionHasToken(mission, "deploying"));
    const bool deploying =
        !undeploying
        && !deployedFire
        && !deployFire
        && !deployedIdle
        && runtimeMissionHasToken(mission, "deploy");
    const bool secondaryFire =
        runtimeMissionHasToken(mission, "secondary")
        || runtimeMissionHasToken(mission, "altfire");
    const bool firing =
        deployedFire
        || deployFire
        || secondaryFire
        || runtimeMissionHasToken(mission, "attack")
        || runtimeMissionHasToken(mission, "fire");
    const bool moving = runtimeObjectShouldUseMovingSequence(object);
    const bool shoveling = object.kind == WorldObjectKind::Infantry
        && !moving && mission == "harvestload";
    const bool carrying = object.kind == WorldObjectKind::Infantry
        && moving && mission == "return";
    if (swimming) {
        // Pursuit still uses Swim until the body stops to attack. Wet poses
        // also take precedence over a land prone/deployed state.
        if (moving) {
            addRuntimeSequenceCandidate(candidates, "Swim");
        } else if (firing) {
            addRuntimeSequenceCandidate(candidates, "WetAttack");
        } else if (runtimeMissionHasToken(mission, "idle1")) {
            addRuntimeSequenceCandidate(candidates, "WetIdle1");
        } else if (runtimeMissionHasToken(mission, "idle2")) {
            addRuntimeSequenceCandidate(candidates, "WetIdle2");
        }
        addRuntimeSequenceCandidate(candidates, "Tread");
    }
    if (object.airborne) {
        if (firing) {
            addRuntimeSequenceCandidate(candidates, "FireFly");
        } else if (moving) {
            addRuntimeSequenceCandidate(candidates, "Fly");
        } else {
            addRuntimeSequenceCandidate(candidates, "Hover");
        }
    }

    if (undeploying) {
        addRuntimeSequenceCandidate(candidates, "Undeploy");
    } else if (deploying) {
        addRuntimeSequenceCandidate(candidates, "Deploy");
    } else if (deployedFire) {
        addRuntimeSequenceCandidate(candidates, "DeployedFire");
        addRuntimeSequenceCandidate(candidates, "DeployFire");
        addRuntimeSequenceCandidate(candidates, "Fire");
        addRuntimeSequenceCandidate(candidates, "SecondaryFire");
        addRuntimeSequenceCandidate(candidates, "Deployed");
        addRuntimeSequenceCandidate(candidates, "FireUp");
    } else if (deployFire) {
        addRuntimeSequenceCandidate(candidates, "DeployFire");
        addRuntimeSequenceCandidate(candidates, "DeployedFire");
        addRuntimeSequenceCandidate(candidates, "Fire");
        addRuntimeSequenceCandidate(candidates, "SecondaryFire");
        addRuntimeSequenceCandidate(candidates, "Deployed");
        addRuntimeSequenceCandidate(candidates, "FireUp");
    } else if (deployedIdle) {
        addRuntimeSequenceCandidate(candidates, "DeployedIdle");
        addRuntimeSequenceCandidate(candidates, "DeployIdle");
        addRuntimeSequenceCandidate(candidates, "Deployed");
        addRuntimeSequenceCandidate(candidates, "Guard");
        addRuntimeSequenceCandidate(candidates, "Ready");
    } else if (secondaryFire) {
        if (object.prone) {
            addRuntimeSequenceCandidate(candidates, "SecondaryProne");
            addRuntimeSequenceCandidate(candidates, "FireProne");
        }
        addRuntimeSequenceCandidate(candidates, "SecondaryFire");
        addRuntimeSequenceCandidate(candidates, "Fire");
        addRuntimeSequenceCandidate(candidates, "FireUp");
    } else if (firing) {
        if (object.prone) {
            addRuntimeSequenceCandidate(candidates, "FireProne");
            addRuntimeSequenceCandidate(candidates, "SecondaryProne");
        }
        addRuntimeSequenceCandidate(candidates, "Fire");
        addRuntimeSequenceCandidate(candidates, "FireUp");
        addRuntimeSequenceCandidate(candidates, "SecondaryFire");
    }

    if (shoveling && !firing && !deploying && !undeploying) {
        addRuntimeSequenceCandidate(candidates, "Shovel");
    }
    if (moving && !firing && !deploying && !undeploying) {
        if (object.kind == WorldObjectKind::Infantry && !object.airborne
            && runtimeMissionHasToken(mission, "panic")) addRuntimeSequenceCandidate(candidates, "Panic");
        if (carrying) addRuntimeSequenceCandidate(candidates, "Carry");
        addRuntimeSequenceCandidate(
            candidates,
            object.prone ? "Crawl" : "Walk"
        );
        addRuntimeSequenceCandidate(
            candidates,
            object.prone ? "Walk" : "Crawl"
        );
    }

    if (!moving && !firing && !deploying && !undeploying && !deployedIdle) {
        if (object.prone) {
            addRuntimeSequenceCandidate(candidates, "Prone");
            addRuntimeSequenceCandidate(candidates, "Crawl");
            addRuntimeSequenceCandidate(candidates, "Ready");
        } else if (runtimeMissionHasToken(mission, "cheer")) {
            addRuntimeSequenceCandidate(candidates, "Cheer");
            addRuntimeSequenceCandidate(candidates, "Idle1");
        } else if (runtimeMissionHasToken(mission, "idle1")) {
            addRuntimeSequenceCandidate(candidates, "Idle1");
            addRuntimeSequenceCandidate(candidates, "Idle");
            addRuntimeSequenceCandidate(candidates, "Ready");
        } else if (runtimeMissionHasToken(mission, "idle2")) {
            addRuntimeSequenceCandidate(candidates, "Idle2");
            addRuntimeSequenceCandidate(candidates, "Idle");
            addRuntimeSequenceCandidate(candidates, "Ready");
        } else if (runtimeMissionHasToken(mission, "guard")) {
            addRuntimeSequenceCandidate(candidates, "Guard");
            addRuntimeSequenceCandidate(candidates, "Ready");
        } else {
            addRuntimeSequenceCandidate(candidates, "Ready");
            addRuntimeSequenceCandidate(candidates, "Guard");
        }
    }

    addRuntimeSequenceCandidate(candidates, "Ready");
    addRuntimeSequenceCandidate(candidates, "Guard");
    return candidates;
}

const ArtType::SequenceFrame* findRuntimeSequenceFrame(
    const ArtType& artType,
    const std::vector<std::string>& candidates
) {
    for (const std::string& candidate : candidates) {
        const std::string token = toLowerAscii(candidate);
        for (const ArtType::SequenceFrame& frame : artType.sequenceFrames) {
            if (frame.present && toLowerAscii(frame.name) == token) {
                return &frame;
            }
        }
    }
    return nullptr;
}

int runtimeSequenceFramePhase(
    const WorldObjectInstance& object,
    const RuntimeMapRenderContext& context,
    const ArtType& artType,
    const ArtType::SequenceFrame& frame,
    bool reversedDeployFallback
) {
    const int span = std::max(1, frame.frameCount);
    if (span <= 1) {
        return 0;
    }

    const std::string sequenceName = toLowerAscii(frame.name);
    if (runtimeObjectShouldUseMovingSequence(object)
        && (runtimeMissionHasToken(sequenceName, "walk")
            || runtimeMissionHasToken(sequenceName, "crawl")
            || sequenceName == "fly"
            || sequenceName == "swim"
            || sequenceName == "panic"
            || sequenceName == "carry")) {
        return worldObjectMovementAnimationPhase(object, span);
    }
    if ((runtimeMissionHasToken(sequenceName, "deploy")
            || runtimeMissionHasToken(sequenceName, "undeploy"))
        && object.buildAnimTicksTotal > 0) {
        const int total = std::max(1, object.buildAnimTicksTotal);
        const int done =
            std::clamp(total - object.buildAnimTicksRemaining, 0, total);
        int phase = (done * (span - 1)) / total;
        if (reversedDeployFallback) {
            phase = (span - 1) - phase;
        }
        return std::clamp(phase, 0, span - 1);
    }

    const int framePhaseSeed = std::abs(
        (object.instanceId * 31)
        + (object.x * 7)
        + (object.y * 11)
        + (object.subCell * 13)
        + (object.facing * 3)
    );
    int step = context.animationTick / runtimeInfantrySequenceDelayTicks(&artType, context.fixedTickHz);
    if (sequenceName == "shovel" || sequenceName == "tread" || sequenceName == "swim"
        || sequenceName == "wetattack" || sequenceName == "wetidle1"
        || sequenceName == "wetidle2") {
        const std::int64_t tick = runtimeUnitAnimationTick(object, context);
        const int delay = runtimeInfantrySequenceDelayTicks(&artType, context.fixedTickHz);
        step = static_cast<int>((tick / delay) % span);
    }
    return (step + framePhaseSeed) % span;
}

RuntimeObjectSequenceFrameResult selectRuntimeObjectSequenceFrame(
    const WorldObjectInstance& object,
    const RuntimeMapRenderContext& context,
    const ArtType* artType,
    int frameCount,
    RuntimeMapRenderCache* cache = nullptr
) {
    RuntimeObjectSequenceFrameResult result;
    if (artType == nullptr
        || artType->sequenceFrames.empty()
        || frameCount <= 1) {
        return result;
    }

    // Cheer changes only the displayed idle sequence, never orders or world state.
    if (context.playerCheerUntilTick && object.kind == WorldObjectKind::Infantry
        && !object.airborne && !object.deployed && !object.prone
        && !runtimeObjectShouldUseMovingSequence(object)
        && (toLowerAscii(object.mission) == "guard" || toLowerAscii(object.mission) == "idle")) {
        const auto cheer = context.playerCheerUntilTick->find(object.instanceId);
        if (cheer != context.playerCheerUntilTick->end() && cheer->second > context.animationTick) {
            WorldObjectInstance presentation = object;
            presentation.mission = "Cheer";
            return selectRuntimeObjectSequenceFrame(presentation, context, artType, frameCount, cache);
        }
    }
    int cacheFacingCount =
        artType->facings > 0 ? artType->facings : 8;
    cacheFacingCount = std::clamp(cacheFacingCount, 1, 32);
    const int cacheFacingBucket =
        cacheFacingCount > 1
            ? facingBucketForDirectionalShp(
                object.facing,
                cacheFacingCount
            )
            : 0;
    const std::string mission = toLowerAscii(object.mission);
    const bool movingSequence = runtimeObjectShouldUseMovingSequence(object);
    const bool swimming = runtimeInfantryIsSwimmingForRender(object, context, cache);
    const std::string cacheKey =
        artType->id
        + "|kind=" + toString(object.kind)
        + "|mission=" + mission
        + "|airborne=" + (object.airborne ? "1" : "0")
        + "|render=" + (object.hasRenderPosition ? "1" : "0")
        + "|moving=" + (movingSequence ? "1" : "0")
        + "|swimming=" + (swimming ? "1" : "0")
        + "|prone=" + (object.prone ? "1" : "0")
        + "|deployed=" + (object.deployed ? "1" : "0")
        + "|facing=" + std::to_string(cacheFacingBucket)
        + "|frames=" + std::to_string(frameCount);
    if (cache != nullptr) {
        const auto found = cache->sequenceFrameMetadataByKey.find(cacheKey);
        if (found != cache->sequenceFrameMetadataByKey.end()) {
            ++cache->sequenceFrameCacheHits;
            const RuntimeSequenceFrameMetadataCacheEntry& metadata =
                found->second;
            if (!metadata.matched) {
                return result;
            }
            const ArtType::SequenceFrame frame{
                metadata.sequenceName,
                true,
                metadata.startFrame,
                metadata.framesPerFacing,
                metadata.facingStride
            };
            const int phase = runtimeSequenceFramePhase(
                object,
                context,
                *artType,
                frame,
                metadata.reversedDeployFallback
            );
            int frameIndex =
                metadata.startFrame
                + (metadata.facingBucket * metadata.facingStride)
                + std::clamp(phase, 0, metadata.framesPerFacing - 1);
            if (frameIndex < 0 || frameIndex >= frameCount) {
                frameIndex %= frameCount;
                if (frameIndex < 0) {
                    frameIndex += frameCount;
                }
            }
            result.matched = true;
            result.frameIndex = frameIndex;
            result.sequenceName = metadata.sequenceName;
            return result;
        }
        ++cache->sequenceFrameCacheMisses;
    }

    const std::vector<std::string> candidates =
        runtimeSequenceCandidatesForObjectState(object, swimming);
    const ArtType::SequenceFrame* sequence =
        findRuntimeSequenceFrame(*artType, candidates);
    if (sequence == nullptr) {
        if (cache != nullptr) {
            cache->sequenceFrameMetadataByKey.emplace(
                cacheKey,
                RuntimeSequenceFrameMetadataCacheEntry{}
            );
        }
        return result;
    }

    const bool reversedDeployFallback =
        runtimeMissionHasToken(mission, "undeploy")
        && toLowerAscii(sequence->name) == "deploy";
    const int framesPerFacing = std::clamp(
        sequence->frameCount > 0 ? sequence->frameCount : 1,
        1,
        std::max(1, frameCount)
    );
    const int facingStride = std::max(
        framesPerFacing,
        sequence->facingMultiplier > 0
            ? sequence->facingMultiplier
            : framesPerFacing
    );
    int facingCount =
        sequence->facingMultiplier > 0
            ? (artType->facings > 0 ? artType->facings : 8)
            : 1;
    facingCount = std::clamp(facingCount, 1, 32);
    const int facingBucket =
        facingCount > 1
            ? facingBucketForDirectionalShp(object.facing, facingCount)
            : 0;
    const int phase = runtimeSequenceFramePhase(
        object,
        context,
        *artType,
        *sequence,
        reversedDeployFallback
    );
    int frameIndex =
        sequence->startFrame
        + (facingBucket * facingStride)
        + std::clamp(phase, 0, framesPerFacing - 1);
    if (frameIndex < 0 || frameIndex >= frameCount) {
        frameIndex %= frameCount;
        if (frameIndex < 0) {
            frameIndex += frameCount;
        }
    }

    result.matched = true;
    result.frameIndex = frameIndex;
    result.sequenceName = sequence->name;
    if (cache != nullptr) {
        RuntimeSequenceFrameMetadataCacheEntry metadata;
        metadata.matched = true;
        metadata.startFrame = sequence->startFrame;
        metadata.framesPerFacing = framesPerFacing;
        metadata.facingStride = facingStride;
        metadata.facingBucket = facingBucket;
        metadata.reversedDeployFallback = reversedDeployFallback;
        metadata.sequenceName = sequence->name;
        cache->sequenceFrameMetadataByKey.emplace(cacheKey, metadata);
    }
    return result;
}

#include "render/units/RuntimeUnitIdleAnimation.inl"

int selectRuntimeObjectShpFrame(
    const WorldObjectInstance& object,
    const RuntimeMapRenderContext& context,
    int frameCount,
    RuntimeMapRenderCache* cache = nullptr
) {
    if (frameCount <= 1) {
        return 0;
    }

    const ArtType* artType = findArtTypeForObject(object, context);
    if (object.kind == WorldObjectKind::Structure) {
        const int mainFrameCount = std::max(1, frameCount);
        if (runtimeObjectIsRenderableRubble(object)) {
            // RA2/YR stores the rubble image as the last visible main frame;
            // split shadow frames have already been removed by the caller.
            return mainFrameCount - 1;
        }
        const int gateFrame = runtimeGateFrameForObject(
            object,
            context,
            artType,
            mainFrameCount
        );
        if (gateFrame >= 0) {
            return gateFrame;
        }
        const BuildingType* building = context.rules == nullptr
            ? nullptr : context.rules->findBuildingType(object.type);
        if (building != nullptr && building->canBeOccupied) {
            // Civilian SHPs use normal/damaged/occupied/rubble main frames.
            // Yellow health remains usable; ConditionRed forces evacuation.
            const bool conditionRed = object.health <=
                static_cast<double>(std::max(1, building->strength))
                    * context.rules->getSpecialMechanismRules().conditionRed;
            if (conditionRed) return std::min(1, mainFrameCount - 1);
            if (!object.garrisonOccupantIds.empty() && mainFrameCount >= 3) return 2;
            return 0;
        }
        if (runtimeObjectIsDamaged(object, context)) {
            const int damagedFrame =
                artType != nullptr && artType->damageLevels > 1
                    ? artType->damageLevels - 1
                    : 1;
            return std::clamp(damagedFrame, 0, mainFrameCount - 1);
        }
        return 0;
    }

    const RuntimeObjectSequenceFrameResult sequenceFrame =
        selectRuntimeObjectSequenceFrame(
            object,
            context,
            artType,
            frameCount,
            cache
        );
    if (sequenceFrame.matched) {
        return sequenceFrame.frameIndex;
    }

    const bool implicitSpriteUnitFacings =
        runtimeObjectUsesImplicitSpriteUnitFacingLayout(object, context);
    int facingCount = implicitSpriteUnitFacings
        ? 8
        : artType == nullptr || artType->facings <= 0
            ? 1
            : artType->facings;
    facingCount = std::clamp(facingCount, 1, 32);
    const bool directionalShp =
        artType != nullptr && !artType->voxel;
    const int facingBucket = implicitSpriteUnitFacings
        ? facingBucketForImplicitSpriteUnit(object.facing, facingCount)
        : directionalShp
            ? facingBucketForDirectionalShp(object.facing, facingCount)
            : facingBucketForObject(object, facingCount);
    const bool movingSequence = runtimeObjectShouldUseMovingSequence(object);

    // Retail UnitClass::Fire starts an independent 2*FiringFrames-1
    // countdown. DrawAsSHP uses countdown/2, so the authored firing strip
    // runs backwards, before the movement/idle branches. ROF, WalkRate and
    // losing the target do not change this clock (0x74141A / 0x73C64B).
    const UnitType* firingUnit = findObjectUnitTypeForRender(context, object);
    if (implicitSpriteUnitFacings && artType->firingFrames > 0
        && firingUnit && firingUnit->organic && firingUnit->naval && firingUnit->navalTargeting == 3
        && object.alive && object.health > 0 && object.spriteFiringStartTick >= 0
        && context.animationTick >= object.spriteFiringStartTick) {
        const int firingStart = std::max(0, artType->startWalkFrame)
            + (artType->walkFrames + std::max(1, artType->standingFrames)) * facingCount;
        const auto elapsed = runtimeRuleFrameAtTick(
            context.animationTick - object.spriteFiringStartTick, context.fixedTickHz);
        const auto counter = static_cast<std::int64_t>(artType->firingFrames) * 2 - 1 - elapsed;
        if (counter >= 0 && firingStart + facingCount * artType->firingFrames <= frameCount)
            return firingStart + facingBucket * artType->firingFrames + static_cast<int>(counter / 2);
    }

    int startFrame = 0;
    int framesPerFacing = 1;
    if (object.kind == WorldObjectKind::Infantry) {
        if (!movingSequence && artType != nullptr) {
            const int idleFrame =
                selectRuntimeInfantryIdleFrame(context, object, *artType, frameCount);
            if (idleFrame >= 0) {
                return idleFrame;
            }
        }

        framesPerFacing = artType == nullptr || artType->standingFrames <= 0
            ? 1
            : artType->standingFrames;
        if (movingSequence
            && artType != nullptr
            && artType->walkFrames > 0) {
            startFrame = std::max(0, artType->startWalkFrame);
            framesPerFacing = artType->walkFrames;
        }
    } else {
        const UnitType* unit = findObjectUnitTypeForRender(context, object);
        const bool animateIdleWalk = !movingSequence && unit != nullptr && unit->idleRate > 0;
        if (!movingSequence && artType != nullptr
            && (artType->startStandFrame >= 0 || artType->standingFrames > 0)) {
            startFrame = std::max(0, artType->startStandFrame);
            framesPerFacing = std::max(1, artType->standingFrames);
        } else if (implicitSpriteUnitFacings) {
            const int walkStart = std::max(0, artType->startWalkFrame);
            if (movingSequence || animateIdleWalk) {
                startFrame = walkStart;
                framesPerFacing = artType->walkFrames;
            } else {
                const int standingStart =
                    walkStart + (artType->walkFrames * facingCount);
                if (standingStart + facingCount <= frameCount) {
                    startFrame = standingStart;
                    framesPerFacing = 1;
                } else {
                    startFrame = walkStart;
                    framesPerFacing = artType->walkFrames;
                }
            }
        } else {
            framesPerFacing = artType == nullptr || artType->walkFrames <= 0
                ? 1
                : artType->walkFrames;
            startFrame =
                (movingSequence || animateIdleWalk) && artType != nullptr
                    ? std::max(0, artType->startWalkFrame)
                    : 0;
        }
    }

    framesPerFacing = std::clamp(framesPerFacing, 1, frameCount);
    const int frameOffset =
        movingSequence
            ? worldObjectMovementAnimationPhase(object, framesPerFacing)
            : runtimeUnitIdleFrameOffset(object, context, artType, framesPerFacing);
    int frameIndex =
        startFrame
        + (facingBucket * framesPerFacing)
        + frameOffset;
    if (frameIndex < 0 || frameIndex >= frameCount) {
        frameIndex %= frameCount;
        if (frameIndex < 0) {
            frameIndex += frameCount;
        }
    }

    return frameIndex;
}

std::string trimNulls(const std::string& value) {
    const std::size_t end = value.find('\0');
    return end == std::string::npos ? value : value.substr(0, end);
}

void appendRuntimeSectionSample(std::string& sample, const std::string& name) {
    if (name.empty()) {
        return;
    }
    if (!sample.empty()) {
        sample += ",";
    }
    sample += name;
}

std::string readAsciiString(
    const std::vector<unsigned char>& bytes,
    std::size_t offset,
    std::size_t length
) {
    if (offset >= bytes.size()) {
        return "";
    }

    const std::size_t available = std::min(length, bytes.size() - offset);
    return trimNulls(std::string(
        reinterpret_cast<const char*>(bytes.data() + offset),
        available
    ));
}

bool parseRuntimeVxlMetadataFromBytes(
    const std::vector<unsigned char>& bytes,
    const std::string& sourceName,
    RuntimeVoxelMetadata& metadata,
    std::string& errorMessage
) {
    constexpr std::size_t signatureBytes = 16;
    constexpr std::size_t fixedHeaderBytes = 34;
    constexpr std::size_t embeddedPaletteBytes = 768;
    constexpr std::size_t sectionRecordBytes = 28;
    if (bytes.size() < fixedHeaderBytes + embeddedPaletteBytes) {
        errorMessage = "VXL file is too small: " + sourceName;
        return false;
    }

    const std::string signature = readAsciiString(bytes, 0, signatureBytes);
    if (signature != "Voxel Animation") {
        errorMessage = "VXL signature is not Voxel Animation: " + sourceName;
        return false;
    }

    const unsigned int sectionCount = readUInt32(bytes, 20);
    if (sectionCount > 1024) {
        errorMessage = "VXL section count is unreasonably large: " + sourceName;
        return false;
    }

    const std::size_t sectionTableOffset =
        fixedHeaderBytes + embeddedPaletteBytes;
    std::size_t sectionTableBytes = 0;
    if (!checkedMul(
            static_cast<std::size_t>(sectionCount),
            sectionRecordBytes,
            sectionTableBytes
        )) {
        errorMessage = "VXL section table overflowed: " + sourceName;
        return false;
    }

    if (sectionTableOffset + sectionTableBytes > bytes.size()) {
        errorMessage = "VXL section table is outside file: " + sourceName;
        return false;
    }

    metadata.vxlPath = sourceName;
    metadata.vxlSectionCount = static_cast<int>(sectionCount);
    metadata.vxlFileSize = static_cast<std::uint64_t>(bytes.size());
    metadata.vxlSectionSample.clear();
    const unsigned int sectionSampleCount = std::min<unsigned int>(sectionCount, 4U);
    for (unsigned int sectionIndex = 0;
        sectionIndex < sectionSampleCount;
        ++sectionIndex) {
        appendRuntimeSectionSample(
            metadata.vxlSectionSample,
            readAsciiString(
                bytes,
                sectionTableOffset
                    + (static_cast<std::size_t>(sectionIndex) * sectionRecordBytes),
                16
            )
        );
    }
    return true;
}

bool parseRuntimeVxlMetadata(
    const std::string& vxlPath,
    RuntimeVoxelMetadata& metadata,
    std::string& errorMessage
) {
    std::vector<unsigned char> bytes;
    if (!loadBytes(vxlPath, bytes, errorMessage)) {
        return false;
    }

    return parseRuntimeVxlMetadataFromBytes(
        bytes,
        vxlPath,
        metadata,
        errorMessage
    );
}

bool parseRuntimeHvaMetadataFromBytes(
    const std::vector<unsigned char>& bytes,
    const std::string& sourceName,
    RuntimeVoxelMetadata& metadata,
    std::string& errorMessage
) {
    constexpr std::size_t fixedHeaderBytes = 24;
    constexpr std::size_t sectionNameBytes = 16;
    constexpr std::size_t matrixFloatCount = 12;
    constexpr std::size_t matrixBytes = matrixFloatCount * 4;
    if (bytes.size() < fixedHeaderBytes) {
        errorMessage = "HVA file is too small: " + sourceName;
        return false;
    }

    const unsigned int frameCount = readUInt32(bytes, 16);
    const unsigned int sectionCount = readUInt32(bytes, 20);
    if (frameCount > 100000 || sectionCount > 1024) {
        errorMessage = "HVA frame or section count is unreasonably large: "
            + sourceName;
        return false;
    }

    std::size_t sectionNameTableBytes = 0;
    if (!checkedMul(
            static_cast<std::size_t>(sectionCount),
            sectionNameBytes,
            sectionNameTableBytes
        )) {
        errorMessage = "HVA section table overflowed: " + sourceName;
        return false;
    }

    std::size_t matrixDataOffset = 0;
    if (!checkedAdd(fixedHeaderBytes, sectionNameTableBytes, matrixDataOffset)) {
        errorMessage = "HVA matrix data offset overflowed: " + sourceName;
        return false;
    }

    std::size_t matrixCount = 0;
    if (!checkedMul(
            static_cast<std::size_t>(frameCount),
            static_cast<std::size_t>(sectionCount),
            matrixCount
        )) {
        errorMessage = "HVA matrix count overflowed: " + sourceName;
        return false;
    }

    std::size_t allMatrixBytes = 0;
    if (!checkedMul(matrixCount, matrixBytes, allMatrixBytes)) {
        errorMessage = "HVA matrix byte count overflowed: " + sourceName;
        return false;
    }

    if (matrixDataOffset + allMatrixBytes > bytes.size()) {
        errorMessage = "HVA matrix data is outside file: " + sourceName;
        return false;
    }

    metadata.hvaPath = sourceName;
    metadata.hvaFrameCount = static_cast<int>(frameCount);
    metadata.hvaSectionCount = static_cast<int>(sectionCount);
    metadata.hvaFileSize = static_cast<std::uint64_t>(bytes.size());
    metadata.hvaSectionSample.clear();
    const unsigned int sectionSampleCount = std::min<unsigned int>(sectionCount, 4U);
    for (unsigned int sectionIndex = 0;
        sectionIndex < sectionSampleCount;
        ++sectionIndex) {
        appendRuntimeSectionSample(
            metadata.hvaSectionSample,
            readAsciiString(
                bytes,
                fixedHeaderBytes
                    + (static_cast<std::size_t>(sectionIndex) * sectionNameBytes),
                sectionNameBytes
            )
        );
    }
    return true;
}

bool parseRuntimeHvaMetadata(
    const std::string& hvaPath,
    RuntimeVoxelMetadata& metadata,
    std::string& errorMessage
) {
    std::vector<unsigned char> bytes;
    if (!loadBytes(hvaPath, bytes, errorMessage)) {
        return false;
    }

    return parseRuntimeHvaMetadataFromBytes(
        bytes,
        hvaPath,
        metadata,
        errorMessage
    );
}

bool parseRuntimeHvaFrameTransformsFromBytes(
    const std::vector<unsigned char>& bytes,
    const std::string& sourceName,
    std::vector<RuntimeHvaTransform>& transforms,
    std::string& errorMessage,
    int frameIndex = 0
) {
    constexpr std::size_t fixedHeaderBytes = 24;
    constexpr std::size_t sectionNameBytes = 16;
    constexpr std::size_t matrixFloatCount = 12;
    constexpr std::size_t matrixBytes = matrixFloatCount * 4;
    if (bytes.size() < fixedHeaderBytes) {
        errorMessage = "HVA file is too small: " + sourceName;
        return false;
    }

    const unsigned int frameCount = readUInt32(bytes, 16);
    const unsigned int sectionCount = readUInt32(bytes, 20);
    if (frameCount == 0 || frameCount > 100000 || sectionCount == 0 || sectionCount > 1024
        || frameIndex < 0 || static_cast<unsigned int>(frameIndex) >= frameCount) {
        errorMessage = "HVA animation frame transform table is invalid: "
            + sourceName;
        return false;
    }

    std::size_t sectionNameTableBytes = 0;
    if (!checkedMul(
            static_cast<std::size_t>(sectionCount),
            sectionNameBytes,
            sectionNameTableBytes
        )) {
        errorMessage = "HVA section table overflowed: " + sourceName;
        return false;
    }

    std::size_t matrixOffset = 0;
    if (!checkedAdd(fixedHeaderBytes, sectionNameTableBytes, matrixOffset)) {
        errorMessage = "HVA matrix offset overflowed: " + sourceName;
        return false;
    }

    std::size_t firstFrameBytes = 0;
    if (!checkedMul(
            static_cast<std::size_t>(sectionCount),
            matrixBytes,
            firstFrameBytes
        )) {
        errorMessage = "HVA first frame byte count overflowed: " + sourceName;
        return false;
    }

    std::size_t frameOffset = 0;
    if (!checkedMul(static_cast<std::size_t>(frameIndex), firstFrameBytes, frameOffset)
        || !checkedAdd(matrixOffset, frameOffset, matrixOffset)
        || matrixOffset > bytes.size() || firstFrameBytes > bytes.size() - matrixOffset) {
        errorMessage = "HVA animation frame matrix data is outside file: "
            + sourceName;
        return false;
    }

    transforms.clear();
    transforms.reserve(sectionCount);
    for (unsigned int sectionIndex = 0; sectionIndex < sectionCount; ++sectionIndex) {
        const std::size_t transformOffset =
            matrixOffset
            + (static_cast<std::size_t>(sectionIndex) * matrixBytes);
        RuntimeHvaTransform transform;
        transform.valid = true;
        for (std::size_t i = 0; i < matrixFloatCount; ++i) {
            const double value = readFloat32(bytes, transformOffset + (i * 4));
            if (!std::isfinite(value)) {
                errorMessage = "HVA matrix contains a non-finite value: "
                    + sourceName;
                return false;
            }
            transform.m[i] = value;
        }
        transforms.push_back(transform);
    }

    return true;
}

