struct RuntimeVxlProjectionParams {
    double screenXScale = 1.38;
    double groundYScale = 0.72;
    double heightYScale = 1.55;
    double depthXYScale = 1.00;
    double depthZScale = 0.9290322581;
    double faceXYWeight = 1.00;
    double faceZWeight = 0.9290322581;
};

RuntimeVxlProjectionParams runtimeVxlProjectionParams() {
    RuntimeVxlProjectionParams params;
    params.screenXScale = runtimeEnvDouble(
        "CONCORD_VXL_PROJ_SCREEN_X",
        1.38,
        0.90,
        2.10
    );
    params.groundYScale = runtimeEnvDouble(
        "CONCORD_VXL_PROJ_GROUND_Y",
        0.72,
        0.45,
        1.10
    );
    params.heightYScale = runtimeEnvDouble(
        "CONCORD_VXL_PROJ_HEIGHT_Y",
        1.55,
        0.80,
        2.00
    );
    params.screenXScale *= runtimeEnvDouble(
        "CONCORD_VXL_SCREEN_X_SCALE_MUL",
        1.0,
        0.85,
        1.10
    );
    params.groundYScale *= runtimeEnvDouble(
        "CONCORD_VXL_SCREEN_Y_SCALE_MUL",
        1.0,
        0.90,
        1.10
    );
    params.heightYScale *= runtimeEnvDouble(
        "CONCORD_VXL_HEIGHT_Y_SCALE_MUL",
        1.0,
        0.90,
        1.15
    );
    params.depthXYScale = runtimeEnvDouble(
        "CONCORD_VXL_PROJ_DEPTH_XY",
        1.00,
        0.40,
        2.00
    );
    const double cameraZWeight =
        (2.0 * params.groundYScale)
        / std::max(0.000001, params.heightYScale);
    params.depthZScale = runtimeEnvDouble(
        "CONCORD_VXL_PROJ_DEPTH_Z",
        params.depthXYScale * cameraZWeight,
        0.40,
        3.50
    );
    params.faceXYWeight = runtimeEnvDouble(
        "CONCORD_VXL_FACE_XY_WEIGHT",
        1.00,
        0.20,
        2.50
    );
    params.faceZWeight = runtimeEnvDouble(
        "CONCORD_VXL_FACE_Z_WEIGHT",
        params.faceXYWeight * cameraZWeight,
        0.20,
        3.00
    );
    return params;
}

std::array<double, 3> runtimeVxlProjectionAxes() {
    const auto projection = runtimeVxlProjectionParams();
    return {projection.screenXScale, projection.groundYScale, projection.heightYScale};
}

RuntimeVxlProjectionParams runtimeVxlProjectionParamsForSizing(
    const RuntimeVxlRasterSizing& sizing
) {
    RuntimeVxlProjectionParams params = runtimeVxlProjectionParams();
    const double heightMultiplier = std::clamp(
        sizing.heightProjectionMultiplier,
        0.50,
        2.00
    );
    params.heightYScale *= heightMultiplier;
    params.depthZScale /= heightMultiplier;
    params.faceZWeight /= heightMultiplier;
    return params;
}

std::string runtimeVxlProjectionParamsCacheToken(
    const RuntimeVxlProjectionParams& params
) {
    const auto scaled = [](double value) {
        return std::to_string(static_cast<int>(std::lround(value * 100.0)));
    };
    return ":px" + scaled(params.screenXScale)
        + ":py" + scaled(params.groundYScale)
        + ":pz" + scaled(params.heightYScale)
        + ":pdx" + scaled(params.depthXYScale)
        + ":pdz" + scaled(params.depthZScale)
        + ":pfx" + scaled(params.faceXYWeight)
        + ":pfz" + scaled(params.faceZWeight);
}

std::string runtimeVxlProjectionParamsDiagnostic(
    const RuntimeVxlProjectionParams& params
) {
    std::ostringstream stream;
    stream << "proj(screenX=" << params.screenXScale
           << ",groundY=" << params.groundYScale
           << ",heightY=" << params.heightYScale
           << ",depthXY=" << params.depthXYScale
           << ",depthZ=" << params.depthZScale
           << ",faceXY=" << params.faceXYWeight
           << ",faceZ=" << params.faceZWeight
           << ",mulX=" << runtimeEnvDouble(
                "CONCORD_VXL_SCREEN_X_SCALE_MUL",
                1.0,
                0.85,
                1.10
           )
           << ",mulY=" << runtimeEnvDouble(
                "CONCORD_VXL_SCREEN_Y_SCALE_MUL",
                1.0,
                0.90,
                1.10
           )
           << ",mulH=" << runtimeEnvDouble(
                "CONCORD_VXL_HEIGHT_Y_SCALE_MUL",
                1.0,
                0.90,
                1.15
           )
           << ")";
    return stream.str();
}

