std::string runtimeVxlReferenceVplModeToken() {
    const char* rawValue = runtimeRendererEnvironmentValue("CONCORD_VXL_REFERENCE_VPL_MODE");
    if (rawValue == nullptr || rawValue[0] == '\0') {
        return "faithful";
    }

    const std::string value = toLowerAscii(rawValue);
    if (value == "off" || value == "none" || value == "raw-color") {
        return "off";
    }
    if (value == "raw" || value == "raw-normal" || value == "normal-index") {
        return "raw";
    }
    if (value == "continuous" || value == "cont") {
        return "continuous";
    }
    if (value == "faithful"
        || value == "westwood"
        || value == "authored"
        || value == "two-lobe") {
        return "faithful";
    }
    return "step";
}

std::string runtimeVxlVplSectionModeToken() {
    if (runtimeVxlRenderProfileIsReferenceLike()) {
        return runtimeVxlReferenceVplModeToken();
    }

    const char* rawValue = runtimeRendererEnvironmentValue("CONCORD_VXL_VPL_SECTION_MODE");
    if (rawValue == nullptr || rawValue[0] == '\0') {
        if (runtimeVxlRenderProfile() == RuntimeVxlRenderProfile::Westwood) {
            return "faithful";
        }
        return runtimeVxlPaletteLookupUsesRawNormalIndex()
            ? "raw"
            : "continuous";
    }

    const std::string value = toLowerAscii(rawValue);
    if (value == "raw" || value == "normal" || value == "normal-index") {
        return "raw";
    }
    if (value == "step" || value == "steps") {
        return "step";
    }
    if (value == "faithful"
        || value == "westwood"
        || value == "authored"
        || value == "two-lobe") {
        return "faithful";
    }
    return "continuous";
}

