double runtimeVxlVplNeutralSectionDefault(
    double maximumSection,
    const RuntimeMapRenderCache* cache = nullptr
) {
    const bool referenceProfile = runtimeVxlRenderProfileIsReferenceLike();
    const bool simpleProfile = runtimeVxlRenderProfileIsSimple();
    const char* referenceRaw =
        runtimeRendererEnvironmentValue("CONCORD_VXL_REFERENCE_VPL_NEUTRAL_SECTION");
    if (referenceProfile
        && referenceRaw != nullptr
        && referenceRaw[0] != '\0') {
        return runtimeEnvDouble(
            "CONCORD_VXL_REFERENCE_VPL_NEUTRAL_SECTION",
            11.0,
            0.0,
            maximumSection
        );
    }

    const char* sharedRaw = runtimeRendererEnvironmentValue("CONCORD_VXL_VPL_NEUTRAL_SECTION");
    if (sharedRaw != nullptr && sharedRaw[0] != '\0') {
        return runtimeEnvDouble(
            "CONCORD_VXL_VPL_NEUTRAL_SECTION",
            simpleProfile ? 11.0 : 13.0,
            0.0,
            maximumSection
        );
    }

    if (runtimeEnvFlag("CONCORD_VXL_VPL_IDENTITY_NEUTRAL", false)
        && cache != nullptr
        && cache->voxelPaletteLookupLoaded
        && cache->voxelPaletteSectionCount > 0) {
        return std::clamp(
            static_cast<double>(cache->voxelPaletteNeutralSection),
            0.0,
            maximumSection
        );
    }

    return simpleProfile ? 11.0 : 13.0;
}

