std::string runtimeVxlAtlasDumpDirectory() {
    const char* rawValue = runtimeRendererEnvironmentValue("CONCORD_VXL_DUMP_ATLAS");
    if (rawValue == nullptr || rawValue[0] == '\0') {
        return {};
    }
    return std::string(rawValue);
}

std::string runtimeVxlAtlasSafeToken(const std::string& value) {
    std::string result;
    result.reserve(value.size());
    for (char ch : value) {
        const unsigned char uch = static_cast<unsigned char>(ch);
        if (std::isalnum(uch) || ch == '_' || ch == '-') {
            result.push_back(ch);
        } else {
            result.push_back('_');
        }
    }
    return result.empty() ? "unknown" : result;
}

std::string runtimeTrimAscii(std::string value) {
    const auto notSpace = [](unsigned char ch) {
        return !std::isspace(ch);
    };
    value.erase(
        value.begin(),
        std::find_if(value.begin(), value.end(), notSpace)
    );
    value.erase(
        std::find_if(value.rbegin(), value.rend(), notSpace).base(),
        value.end()
    );
    return value;
}

bool runtimeVxlAtlasObjectAllowed(
    const std::string& objectType,
    const std::string& imageId
) {
    const char* rawValue = runtimeRendererEnvironmentValue("CONCORD_VXL_DUMP_ATLAS_OBJECTS");
    if (rawValue == nullptr || rawValue[0] == '\0') {
        return true;
    }

    const std::string objectLower = toLowerAscii(objectType);
    const std::string imageLower = toLowerAscii(imageId);
    std::stringstream stream(rawValue);
    std::string token;
    while (std::getline(stream, token, ',')) {
        token = toLowerAscii(runtimeTrimAscii(token));
        if (!token.empty()
            && (token == objectLower || token == imageLower)) {
            return true;
        }
    }
    return false;
}

bool runtimeVxlDumpSweepsEnabled() {
    const char* rawValue = runtimeRendererEnvironmentValue("CONCORD_VXL_DUMP_SWEEPS");
    if (rawValue == nullptr || rawValue[0] == '\0') {
        return true;
    }

    const std::string value = toLowerAscii(runtimeTrimAscii(rawValue));
    return value != "0"
        && value != "false"
        && value != "no"
        && value != "off";
}

std::string runtimeVxlDumpSweepGroup() {
    const char* rawValue = runtimeRendererEnvironmentValue("CONCORD_VXL_DUMP_SWEEP_GROUP");
    if (rawValue == nullptr || rawValue[0] == '\0') {
        return "all";
    }

    const std::string value = toLowerAscii(runtimeTrimAscii(rawValue));
    if (value == "light" || value == "lights" || value == "light-space") {
        return "light";
    }
    if (value == "raster"
        || value == "true-raster"
        || value == "raster-compare") {
        return "raster";
    }
    if (value == "fixedscale"
        || value == "fixed-scale"
        || value == "fixed") {
        return "fixedscale";
    }
    return "all";
}

std::vector<std::string> runtimeVxlDumpOwnerColorTokens() {
    const char* rawValue = runtimeRendererEnvironmentValue("CONCORD_VXL_DUMP_OWNER_COLORS");
    if (rawValue == nullptr || rawValue[0] == '\0') {
        return {};
    }
    std::vector<std::string> tokens;
    std::stringstream stream(rawValue);
    std::string token;
    while (std::getline(stream, token, ',')) {
        token = runtimeTrimAscii(token);
        if (!token.empty()) {
            tokens.push_back(toLowerAscii(token));
        }
    }
    return tokens;
}

COLORREF runtimeVxlOwnerColorFromToken(
    const std::string& token,
    COLORREF fallback
) {
    const std::string value = toLowerAscii(token);
    if (value == "blue") {
        return RGB(64, 120, 224);
    }
    if (value == "red") {
        return RGB(208, 48, 40);
    }
    if (value == "yellow") {
        return RGB(220, 196, 48);
    }
    if (value == "green") {
        return RGB(72, 168, 72);
    }
    if (value == "white" || value == "neutral") {
        return RGB(210, 210, 202);
    }
    return fallback;
}

bool writeRuntimeBgraBmp(
    const std::filesystem::path& path,
    int width,
    int height,
    const std::vector<std::uint32_t>& pixels
) {
    if (width <= 0 || height <= 0
        || pixels.size()
            < static_cast<std::size_t>(width) * static_cast<std::size_t>(height)) {
        return false;
    }

    std::filesystem::create_directories(path.parent_path());
    std::ofstream output(path, std::ios::binary | std::ios::trunc);
    if (!output) {
        return false;
    }

    const std::uint32_t pixelBytes =
        static_cast<std::uint32_t>(width * height * 4);
    const std::uint32_t fileBytes = 14U + 40U + pixelBytes;
    const auto writeU16 =
        [&output](std::uint16_t value) {
            output.put(static_cast<char>(value & 0xFFU));
            output.put(static_cast<char>((value >> 8) & 0xFFU));
        };
    const auto writeU32 =
        [&output](std::uint32_t value) {
            output.put(static_cast<char>(value & 0xFFU));
            output.put(static_cast<char>((value >> 8) & 0xFFU));
            output.put(static_cast<char>((value >> 16) & 0xFFU));
            output.put(static_cast<char>((value >> 24) & 0xFFU));
        };

    output.put('B');
    output.put('M');
    writeU32(fileBytes);
    writeU16(0);
    writeU16(0);
    writeU32(14U + 40U);
    writeU32(40U);
    writeU32(static_cast<std::uint32_t>(width));
    writeU32(static_cast<std::uint32_t>(height));
    writeU16(1);
    writeU16(32);
    writeU32(0);
    writeU32(pixelBytes);
    writeU32(2835);
    writeU32(2835);
    writeU32(0);
    writeU32(0);

    for (int y = height - 1; y >= 0; --y) {
        const std::size_t row =
            static_cast<std::size_t>(y) * static_cast<std::size_t>(width);
        for (int x = 0; x < width; ++x) {
            const std::uint32_t color =
                pixels[row + static_cast<std::size_t>(x)];
            output.put(static_cast<char>(color & 0xFFU));
            output.put(static_cast<char>((color >> 8) & 0xFFU));
            output.put(static_cast<char>((color >> 16) & 0xFFU));
            output.put(static_cast<char>((color >> 24) & 0xFFU));
        }
    }
    return static_cast<bool>(output);
}

class RuntimeScopedEnvironmentValue {
public:
    RuntimeScopedEnvironmentValue(std::string name, std::string value)
        : name_(std::move(name)) {
        const char* current = runtimeRendererEnvironmentValue(name_.c_str());
        if (current != nullptr) {
            hadValue_ = true;
            previousValue_ = current;
        }
#ifdef _WIN32
        _putenv_s(name_.c_str(), value.c_str());
#else
        setenv(name_.c_str(), value.c_str(), 1);
#endif
    }

    ~RuntimeScopedEnvironmentValue() {
#ifdef _WIN32
        _putenv_s(name_.c_str(), hadValue_ ? previousValue_.c_str() : "");
#else
        if (hadValue_) {
            setenv(name_.c_str(), previousValue_.c_str(), 1);
        } else {
            unsetenv(name_.c_str());
        }
#endif
    }

    RuntimeScopedEnvironmentValue(const RuntimeScopedEnvironmentValue&) = delete;
    RuntimeScopedEnvironmentValue& operator=(
        const RuntimeScopedEnvironmentValue&
    ) = delete;

private:
    std::string name_;
    std::string previousValue_;
    bool hadValue_ = false;
};

