RuntimeVoxelStripAtlasImage runtimeVoxelStripAtlasForCurrentEnvironment(
    const WorldObjectInstance& object,
    const RuntimeMapRenderContext& context,
    RuntimeMapRenderCache& cache,
    const std::vector<RuntimePaletteColor>& palette,
    bool ownerRemap,
    COLORREF remapColor
) {
    std::array<RuntimeVoxelStripFrame, 8> frames;
    const std::size_t count = buildRuntimeVoxelStripFramesForObject(
        object,
        context,
        cache,
        palette,
        ownerRemap,
        remapColor,
        frames
    );
    return makeRuntimeVoxelStripFramesAtlasImage(frames, count);
}

RuntimeVoxelStripAtlasImage runtimeVoxelStripAtlasWithEnvironment(
    const WorldObjectInstance& object,
    const RuntimeMapRenderContext& context,
    RuntimeMapRenderCache& cache,
    const std::vector<RuntimePaletteColor>& palette,
    bool ownerRemap,
    COLORREF remapColor,
    std::initializer_list<std::pair<const char*, const char*>> values
) {
    std::vector<std::unique_ptr<RuntimeScopedEnvironmentValue>> scopedValues;
    scopedValues.reserve(values.size());
    for (const auto& value : values) {
        scopedValues.push_back(std::make_unique<RuntimeScopedEnvironmentValue>(
            value.first,
            value.second
        ));
    }
    return runtimeVoxelStripAtlasForCurrentEnvironment(
        object,
        context,
        cache,
        palette,
        ownerRemap,
        remapColor
    );
}

