    int repairDepotLayers = 0;
    int repairDepotFrame = -1;
    int repairDepotPhase = 0;
    std::string repairDepotImage;
    int poweredLayers = 0;
    int lowPowerLayers = 0;
    int neutralSuppressedLayers = 0;
    int offlineHiddenLayers = 0;
    int offlinePausedVisibleLayers = 0;
    int offlineContinuingLayers = 0;
    int workLayers = 0;
    int factoryVehicleDoorLayers = 0;
    int factoryAirRoofLayers = 0;
    int shipyardProductionLayers = 0;
    int shipyardIdleLayers = 0;
    int shipyardProductionFrame = -1;
    std::string shipyardProductionImage;
    int damageFireOffsets = 0;
    int damageFireDrawn = 0;
    int damageFireCulled = 0;
    int damageFireMissing = 0;
    int firstDamageFireFrame = -1;
    int firstDrawnFrame = -1;
    int firstOfflinePausedVisibleFrame = -1;
    int firstOfflineContinuingFrame = -1;
    bool firstOfflineContinuingIsPowered = true;
    int firstWorkFrame = -1;
    bool firstDrawnRectValid = false;
    RECT firstDrawnLocalRect{0, 0, 0, 0};
    RECT firstDrawnGlobalRect{0, 0, 0, 0};
    std::string firstDrawnImage;
    std::string firstDamageFireImage;
    std::string firstDrawnResolvedImage;
    std::string firstDrawnSourcePath;
    std::string firstSpecialImage;
    std::string firstSpecialResolvedImage;
    std::string firstSpecialSourcePath;
    std::string firstOfflinePausedVisibleImage;
    std::string firstOfflineContinuingImage;
