class RuntimeTerrainTmpRendererMemoPort final : public RuntimeTerrainTmpMemoPort {
public:
    RuntimeTerrainTmpRendererMemoPort(
        const RuntimeMapRenderContext& context, RuntimeMapRenderCache& cache
    ) : context_(context), cache_(cache) {}
    bool find(
        int tileIndex, RuntimeTmpTileFile*& file, bool& updatesLastLoadError
    ) override {
        return findRuntimeGeometryTerrainTile(
            tileIndex, context_, cache_, file, updatesLastLoadError
        );
    }
    void remember(
        int tileIndex, RuntimeTmpTileFile* file, bool updatesLastLoadError
    ) override {
        rememberRuntimeGeometryTerrainTile(
            tileIndex, context_, cache_, file, updatesLastLoadError
        );
    }
private:
    const RuntimeMapRenderContext& context_;
    RuntimeMapRenderCache& cache_;
};

std::string runtimeTerrainTileLookupCacheRoot(
    const RuntimeMapRenderContext& context
) {
    return ::runtimeTerrainTileLookupCacheRoot(
        runtimeTerrainTmpContextForRender(context)
    );
}

RuntimeTmpTileFile* loadRuntimeTerrainTileForIndex(
    int tileIndex, const RuntimeMapRenderContext& context, RuntimeMapRenderCache& cache
) {
    RuntimeTerrainTmpRendererByteSource source(cache, &context);
    RuntimeTerrainTmpRendererMemoPort memo(context, cache);
    return ::loadRuntimeTerrainTileForIndex(
        tileIndex, runtimeTerrainTmpContextForRender(context), cache, source, memo
    );
}

const RuntimeTmpSubTileImage* resolveTerrainVisualCellImage(
    const TerrainCell& cell, const RuntimeMapRenderContext& context,
    RuntimeMapRenderCache& cache, bool* authoredEmptySubTile,
    RuntimeTerrainVisualCellInfo* info = nullptr
);

bool drawTerrainCellTexture(
    HDC dc,
    const RECT& viewport,
    const TerrainCell& cell,
    const POINT& center,
    const RuntimeMapCamera& camera,
    const RuntimeMapRenderContext& context,
    RuntimeMapRenderCache& cache,
    bool* authoredEmptySubTile = nullptr
) {
    bool authoredEmpty = false;
    const RuntimeTmpSubTileImage* image = resolveTerrainVisualCellImage(
        cell, context, cache, &authoredEmpty);
    if (authoredEmptySubTile) *authoredEmptySubTile = authoredEmpty;
    if (image == nullptr) {
        // Empty slots in authored multi-cell TMPs remain intentional transparency.
        return authoredEmpty;
    }
    return drawTmpTileImage(dc, viewport, center, context, camera, *image, cache.palette);
}

std::uint32_t packDibColor(COLORREF color) {
    return (static_cast<std::uint32_t>(GetRValue(color)) << 16)
        | (static_cast<std::uint32_t>(GetGValue(color)) << 8)
        | static_cast<std::uint32_t>(GetBValue(color));
}

std::uint32_t packDibColor(const RuntimePaletteColor& color) {
    return (static_cast<std::uint32_t>(color.r) << 16)
        | (static_cast<std::uint32_t>(color.g) << 8)
        | static_cast<std::uint32_t>(color.b);
}

void putLayerPixel(
    RuntimeTerrainLayerCache& layer,
    int x,
    int y,
    std::uint32_t color,
    int terrainCellIndex = -1,
    int surfaceCellIndex = -1
) {
    if (x < 0 || y < 0 || x >= layer.width || y >= layer.height) {
        return;
    }

    const std::size_t offset =
        (static_cast<std::size_t>(y)
            * static_cast<std::size_t>(layer.width))
        + static_cast<std::size_t>(x);
    layer.pixels[offset] = color;
    // A painter without authored TMP Z must not leave the hidden previous
    // tile eligible to reject a later pixel. Native put restores accepted Z.
    if (layer.terrainDepthWords.size() == layer.pixels.size()) {
        layer.terrainDepthWords[offset] = 0xffffU;
    }
    if (terrainCellIndex >= 0
        && layer.terrainCellIndices.size() == layer.pixels.size()) {
        layer.terrainCellIndices[offset] = terrainCellIndex;
    }
    const int surfaceOwner = surfaceCellIndex >= 0
        ? surfaceCellIndex : terrainCellIndex;
    if (surfaceOwner >= 0
        && layer.surfaceCellIndices.size() == layer.pixels.size()) {
        layer.surfaceCellIndices[offset] = surfaceOwner;
    }
}

void putLayerPixelZBuffered(
    RuntimeTerrainLayerCache& layer,
    std::vector<std::uint16_t>& zBuffer,
    int x,
    int y,
    std::uint16_t zValue,
    std::uint32_t color,
    int terrainCellIndex
) {
    if (x < 0 || y < 0 || x >= layer.width || y >= layer.height) {
        return;
    }
    const std::size_t index = static_cast<std::size_t>(y) * layer.width + x;
    if (index >= zBuffer.size() || zValue > zBuffer[index]) {
        return;
    }
    // TMP accepts equal Z (unlike the strict object SHP leaves). Color and
    // both ownership maps must describe the same accepted source pixel.
    putLayerPixel(layer, x, y, color, terrainCellIndex, terrainCellIndex);
    zBuffer[index] = zValue;
}
const RuntimeTmpSubTileImage* resolveRuntimeTerrainMetadata(
    int tileIndex,
    int subTileIndex,
    const RuntimeMapRenderContext& context,
    RuntimeMapRenderCache& cache
) {
    RuntimeTerrainTmpRendererByteSource source(cache, &context);
    RuntimeTerrainTmpRendererMemoPort memo(context, cache);
    return ::resolveRuntimeTerrainMetadata(
        tileIndex, subTileIndex, runtimeTerrainTmpContextForRender(context),
        cache, source, memo
    );
}

#include "render/units/RuntimeInfantrySwimAnimation.inl"

const RuntimeTmpSubTileImage* resolveTerrainCellImage(
    int tileIndex,
    int subTileIndex,
    const RuntimeMapRenderContext& context,
    RuntimeMapRenderCache& cache,
    bool* authoredEmptySubTile = nullptr
) {
    if (authoredEmptySubTile != nullptr) {
        *authoredEmptySubTile = false;
    }
    if (!context.useTileTextures
        || context.theater == nullptr
        || (context.tileRootPath.empty() && context.assetRootPath.empty())
        || !ensureRuntimePalette(context, cache)
    ) {
        return nullptr;
    }

    RuntimeTmpTileFile* tileFile = loadRuntimeTerrainTileForIndex(
        tileIndex,
        context,
        cache
    );
    if (tileFile == nullptr) {
        return nullptr;
    }
    if (runtimeTerrainSubTileIsAuthoredEmpty(*tileFile, subTileIndex)) {
        if (authoredEmptySubTile != nullptr) {
            *authoredEmptySubTile = true;
        }
        return nullptr;
    }
    return findRuntimeTerrainSubTileImage(*tileFile, subTileIndex);
}

const RuntimeTmpSubTileImage* resolveTerrainCellImage(
    const TerrainCell& cell,
    const RuntimeMapRenderContext& context,
    RuntimeMapRenderCache& cache,
    bool* authoredEmptySubTile = nullptr
) {
    const int tileIndex = cell.tileIndex == 65535 ? 0 : cell.tileIndex;
    const int subTileIndex = cell.tileIndex == 65535 ? 0 : cell.subTileIndex;
    return resolveTerrainCellImage(
        tileIndex,
        subTileIndex,
        context,
        cache,
        authoredEmptySubTile
    );
}

#include "render/terrain/RuntimeTerrainVisualVariants.inl"

std::uint64_t runtimePackedPaletteHash(
    const std::array<std::uint32_t, 256>& packedPalette
) {
    std::uint64_t hash = 1469598103934665603ULL;
    for (std::uint32_t color : packedPalette) {
        hash ^= static_cast<std::uint64_t>(color);
        hash *= 1099511628211ULL;
    }
    return hash;
}

const std::vector<std::uint32_t>& runtimePackedTmpPixels(
    const RuntimeTmpSubTileImage& image,
    const std::array<std::uint32_t, 256>& packedPalette
) {
    const std::size_t pixelCount =
        static_cast<std::size_t>(std::max(0, image.width))
        * static_cast<std::size_t>(std::max(0, image.height));
    const std::uint64_t paletteHash = runtimePackedPaletteHash(packedPalette);
    if (image.packedPixelPaletteHash == paletteHash
        && image.packedPixels.size() == pixelCount) {
        return image.packedPixels;
    }

    image.packedPixelPaletteHash = paletteHash;
    image.packedPixels.assign(pixelCount, 0);
    const std::size_t count =
        std::min(pixelCount, image.pixels.size());
    for (std::size_t index = 0; index < count; ++index) {
        const unsigned char paletteIndex = image.pixels[index];
        image.packedPixels[index] =
            paletteIndex == 0 ? 0 : packedPalette[paletteIndex];
    }
    return image.packedPixels;
}

bool drawTmpTileImageToLayer(
    RuntimeTerrainLayerCache& layer,
    int targetX,
    int targetY,
    const RuntimeTmpSubTileImage& image,
    const std::array<std::uint32_t, 256>& packedPalette,
    int terrainCellIndex = -1,
    int surfaceCellIndex = -1
) {
    if (image.width <= 0
        || image.height <= 0
        || image.pixels.size()
            < static_cast<std::size_t>(image.width)
                * static_cast<std::size_t>(image.height)
    ) {
        return false;
    }

    const int startY = std::max(0, -targetY);
    const int endY = std::min(image.height, layer.height - targetY);
    const int startX = std::max(0, -targetX);
    const int endX = std::min(image.width, layer.width - targetX);
    const std::vector<std::uint32_t>& packedPixels =
        runtimePackedTmpPixels(image, packedPalette);

    for (int y = startY; y < endY; ++y) {
        for (int x = startX; x < endX; ++x) {
            const std::uint32_t color =
                packedPixels[static_cast<std::size_t>(y * image.width + x)];
            // Transparency is palette index zero. An opaque black entry may
            // also pack to RGB zero and must still cover the terrain below.
            if (image.pixels[static_cast<std::size_t>(y * image.width + x)] == 0) {
                continue;
            }

            putLayerPixel(
                layer,
                targetX + x,
                targetY + y,
                color,
                terrainCellIndex,
                surfaceCellIndex
            );
        }
    }

    return true;
}

bool drawTmpTileImageToLayer(
    RuntimeTerrainLayerCache& layer,
    const POINT& center,
    const RuntimeMapCamera& camera,
    const RuntimeTmpSubTileImage& image,
    const std::array<std::uint32_t, 256>& packedPalette,
    int terrainCellIndex = -1,
    int surfaceCellIndex = -1
) {
    return drawTmpTileImageToLayer(
        layer,
        center.x - (camera.tileWidth / 2) + image.offsetX,
        center.y - (camera.tileHeight / 2) + image.offsetY,
        image,
        packedPalette,
        terrainCellIndex,
        surfaceCellIndex
    );
}

bool drawLowBridgeTmpImageToLayer(
    RuntimeTerrainLayerCache& layer,
    const POINT& center,
    const RuntimeTmpSubTileImage& image,
    const std::array<std::uint32_t, 256>& packedPalette,
    int surfaceCellIndex = -1
) {
    const int globalWidth =
        image.globalWidth > 0 ? image.globalWidth : image.width;
    const int globalHeight =
        image.globalHeight > 0 ? image.globalHeight : image.height;
    return drawTmpTileImageToLayer(
        layer,
        center.x - (globalWidth / 2) + image.offsetX,
        center.y - (globalHeight / 2) + image.offsetY,
        image,
        packedPalette,
        -1,
        surfaceCellIndex
    );
}

bool drawHighBridgeTmpImageToLayer(
    RuntimeTerrainLayerCache& layer,
    const POINT& center,
    const RuntimeTmpSubTileImage& image,
    const std::array<std::uint32_t, 256>& packedPalette,
    int surfaceCellIndex = -1
) {
    const int globalWidth =
        image.globalWidth > 0 ? image.globalWidth : image.width;
    const int globalHeight =
        image.globalHeight > 0 ? image.globalHeight : image.height;
    return drawTmpTileImageToLayer(
        layer,
        center.x - (globalWidth / 2) + image.offsetX,
        center.y - (globalHeight / 2) + image.offsetY,
        image,
        packedPalette,
        -1,
        surfaceCellIndex
    );
}

// Only standard native TMPs with complete base/extra Z data enter this path.
// Bridge adapters and custom color-only images retain their existing painter.
bool runtimeTmpImageHasNativeDepth(const RuntimeTmpSubTileImage& image) {
    constexpr std::size_t nativeDiamondPixels = 900;
    if (image.baseWidth != 60 || image.baseHeight != 30
        || image.basePixels.size() < nativeDiamondPixels
        || !image.hasBaseZData || image.baseZData.size() < nativeDiamondPixels) {
        return false;
    }
    if (!image.hasExtra) return true;
    const auto count = static_cast<std::size_t>(std::max(0, image.extraWidth))
        * static_cast<std::size_t>(std::max(0, image.extraHeight));
    return count > 0 && image.hasExtraZData
        && image.extraPixels.size() >= count && image.extraZData.size() >= count;
}

bool drawTmpTileImageZBufferedToLayer(
    RuntimeTerrainLayerCache& layer,
    std::vector<std::uint16_t>& zBuffer,
    const POINT& center,
    const TerrainCell& cell,
    const RuntimeMapCamera& camera,
    const RuntimeTmpSubTileImage& image,
    const std::array<std::uint32_t, 256>& packedPalette,
    int terrainCellIndex
) {
    if (camera.tileWidth != 60 || camera.tileHeight != 30
        || !runtimeTmpImageHasNativeDepth(image)) {
        return drawTmpTileImageToLayer(layer, center, camera, image,
            packedPalette, terrainCellIndex);
    }
    const int targetX = center.x - camera.tileWidth / 2;
    const int targetY = center.y - camera.tileHeight / 2;
    int rowWidth = 0;
    std::size_t sourceIndex = 0;
    for (int y = 0; y < image.baseHeight; ++y) {
        rowWidth += y < image.baseHeight / 2 ? 4 : -4;
        const int xStart = (image.baseWidth - rowWidth) / 2;
        for (int x = 0; x < rowWidth; ++x, ++sourceIndex) {
            const auto color = image.basePixels[sourceIndex];
            if (color == 0) continue;
            putLayerPixelZBuffered(layer, zBuffer,
                targetX + image.baseOffsetX + xStart + x,
                targetY + image.baseOffsetY + y,
                runtimeTmpNativeDepthWord(cell.x, cell.y, image.baseZData[sourceIndex]),
                packedPalette[color], terrainCellIndex);
        }
    }
    if (!image.hasExtra) return true;
    const int extraTargetX = targetX + image.extraOffsetX - image.baseOffsetX;
    const int extraTargetY = targetY + image.extraOffsetY - image.baseOffsetY;
    for (int y = 0; y < image.extraHeight; ++y) {
        for (int x = 0; x < image.extraWidth; ++x) {
            const auto source = static_cast<std::size_t>(y) * image.extraWidth + x;
            const auto color = image.extraPixels[source];
            if (color == 0) continue;
            putLayerPixelZBuffered(layer, zBuffer, extraTargetX + x, extraTargetY + y,
                runtimeTmpNativeDepthWord(cell.x, cell.y, image.extraZData[source]),
                packedPalette[color], terrainCellIndex);
        }
    }
    return true;
}
bool drawRuntimeAuxiliaryTmpSpriteToLayer(
    RuntimeTerrainLayerCache& layer,
    const POINT& center,
    const RuntimeMapRenderContext& context,
    const RuntimeMapCamera& camera,
    RuntimeMapRenderCache& cache,
    const std::array<std::uint32_t, 256>& packedPalette,
    const std::string& imageId,
    int frameIndex,
    int surfaceCellIndex = -1
) {
    if (imageId.empty()) {
        return false;
    }

    const std::vector<std::string> rootPaths = {
        context.assetRootPath,
        context.tileRootPath,
        context.structureRootPath
    };
    for (const std::string& fileName :
            resolveAuxiliaryTmpFileNameCandidates(imageId, context)) {
        RuntimeTmpTileFile* tileFile =
            loadRuntimeTmpTileByNameFromCache(
                rootPaths,
                context.assetRootPath,
                fileName,
                cache
            );
        if (tileFile == nullptr) {
            continue;
        }

        const RuntimeTmpSubTileImage* image =
            findRuntimeSubTileImage(*tileFile, frameIndex);
        if (image == nullptr) {
            continue;
        }

        return drawTmpTileImageToLayer(
            layer,
            center,
            camera,
            *image,
            packedPalette,
            -1,
            surfaceCellIndex
        );
    }

    return false;
}

bool drawRuntimeLowBridgeTmpSpriteToLayer(
    RuntimeTerrainLayerCache& layer,
    const POINT& center,
    const RuntimeMapRenderContext& context,
    RuntimeMapRenderCache& cache,
    const std::array<std::uint32_t, 256>& packedPalette,
    const std::string& imageId,
    int frameIndex,
    int surfaceCellIndex = -1
) {
    if (imageId.empty()) {
        return false;
    }

    const std::vector<std::string> rootPaths = {
        context.assetRootPath,
        context.tileRootPath,
        context.structureRootPath
    };
    for (const std::string& fileName :
            resolveAuxiliaryTmpFileNameCandidates(imageId, context)) {
        RuntimeTmpTileFile* tileFile =
            loadRuntimeTmpTileByNameFromCache(
                rootPaths,
                context.assetRootPath,
                fileName,
                cache
            );
        if (tileFile == nullptr) {
            continue;
        }

        if (runtimeTerrainSubTileIsAuthoredEmpty(*tileFile, frameIndex)) {
            return true;
        }
        const RuntimeTmpSubTileImage* image =
            findRuntimeTerrainSubTileImage(*tileFile, frameIndex);
        if (image == nullptr) {
            continue;
        }

        return drawLowBridgeTmpImageToLayer(
            layer,
            center,
            *image,
            packedPalette,
            surfaceCellIndex
        );
    }

    return false;
}

void stampRuntimeHighBridgePatchSurfaceOwnership(
    RuntimeTerrainLayerCache& layer, const POINT& center,
    const RuntimeTmpSubTileImage& image, int sourceCellIndex,
    const RuntimeMapCamera& camera, RuntimeMapRenderCache& cache
);

bool drawRuntimeHighBridgeTmpSpriteToLayer(
    RuntimeTerrainLayerCache& layer,
    const POINT& center,
    const RuntimeMapRenderContext& context,
    const RuntimeMapCamera& camera,
    RuntimeMapRenderCache& cache,
    const std::array<std::uint32_t, 256>& packedPalette,
    const std::string& imageId,
    int frameIndex,
    int surfaceCellIndex = -1
) {
    if (imageId.empty()) {
        return false;
    }

    const std::vector<std::string> rootPaths = {
        context.assetRootPath,
        context.tileRootPath,
        context.structureRootPath
    };
    for (const std::string& fileName :
            resolveAuxiliaryTmpFileNameCandidates(imageId, context)) {
        RuntimeTmpTileFile* tileFile =
            loadRuntimeTmpTileByNameFromCache(
                rootPaths,
                context.assetRootPath,
                fileName,
                cache
            );
        if (tileFile == nullptr) {
            continue;
        }

        const RuntimeTmpSubTileImage* image =
            findRuntimeSubTileImage(*tileFile, frameIndex);
        if (image == nullptr) {
            continue;
        }

        const bool drawn = drawHighBridgeTmpImageToLayer(
            layer,
            center,
            *image,
            packedPalette
        );
        if (drawn && surfaceCellIndex >= 0) {
            stampRuntimeHighBridgePatchSurfaceOwnership(layer, center, *image,
                surfaceCellIndex, camera, cache);
        }
        return drawn;
    }

    return false;
}

void drawDiamondToLayer(
    RuntimeTerrainLayerCache& layer,
    const POINT& center,
    int width,
    int height,
    COLORREF fillColor,
    int terrainCellIndex = -1
) {
    const int halfWidth = std::max(1, width / 2);
    const int halfHeight = std::max(1, height / 2);
    const std::uint32_t packedColor = packDibColor(fillColor);

    for (int dy = -halfHeight; dy <= halfHeight; ++dy) {
        const int y = center.y + dy;
        const int rowHalfWidth =
            ((halfHeight - std::abs(dy)) * halfWidth) / halfHeight;
        for (int dx = -rowHalfWidth; dx <= rowHalfWidth; ++dx) {
            putLayerPixel(
                layer,
                center.x + dx,
                y,
                packedColor,
                terrainCellIndex
            );
        }
    }
}

int runtimeFloorToBucket(int value, int bucketSize) {
    if (bucketSize <= 0) {
        return value;
    }
    if (value >= 0) {
        return (value / bucketSize) * bucketSize;
    }
    return -(((-value + bucketSize - 1) / bucketSize) * bucketSize);
}

struct RuntimeTerrainLayerRegion {
    int originX = 0;
    int originY = 0;
    int width = 0;
    int height = 0;
};

RuntimeTerrainLayerRegion runtimeTerrainLayerRegionForViewport(
    const RuntimeMapCamera& camera,
    int viewportWidth,
    int viewportHeight
) {
    const int bucketX =
        std::max(camera.tileWidth * 6, std::max(1, viewportWidth / 3));
    const int bucketY =
        std::max(camera.tileHeight * 9, std::max(1, viewportHeight / 3));
    const int marginX =
        std::max(camera.tileWidth * 6, bucketX);
    const int marginY =
        std::max(camera.tileHeight * 9, bucketY);
    const int bucketBaseX =
        runtimeFloorToBucket(camera.worldOffsetX, bucketX);
    const int bucketBaseY =
        runtimeFloorToBucket(camera.worldOffsetY, bucketY);
    return {
        bucketBaseX - marginX,
        bucketBaseY - marginY,
        viewportWidth + (marginX * 2),
        viewportHeight + (marginY * 2)
    };
}

std::string buildTerrainLayerKey(
    const GameWorld& world,
    const RuntimeMapRenderContext& context,
    const RuntimeMapCamera& camera,
    const RuntimeTerrainLayerRegion& region
) {
    const GameWorldSummary& summary = world.getSummary();
    return summary.theater
        + "|world=" + std::to_string(reinterpret_cast<std::uintptr_t>(&world))
        + "|data=" + std::to_string(reinterpret_cast<std::uintptr_t>(world.getTerrainCells().data()))
        + "|size=" + std::to_string(world.getTerrainCells().size())
        + "|facts=" + std::to_string(context.mapFacts == nullptr ? 0 : context.mapFacts->contentHash)
        + "|facts-source=" + std::to_string(reinterpret_cast<std::uintptr_t>(context.mapFacts))
        + "|facts-data=" + std::to_string(context.mapFacts == nullptr ? 0
            : reinterpret_cast<std::uintptr_t>(context.mapFacts->cells.data()))
        + "|theater=" + std::to_string(reinterpret_cast<std::uintptr_t>(context.theater))
        + "|cells=" + std::to_string(summary.terrainCells)
        + "|bounds="
        + std::to_string(summary.minCellX)
        + ","
        + std::to_string(summary.minCellY)
        + ","
        + std::to_string(summary.maxCellX)
        + ","
        + std::to_string(summary.maxCellY)
        + "|tile="
        + std::to_string(camera.tileWidth)
        + "x"
        + std::to_string(camera.tileHeight)
        + "|region="
        + std::to_string(region.originX)
        + ","
        + std::to_string(region.originY)
        + ","
        + std::to_string(region.width)
        + "x"
        + std::to_string(region.height)
        + "|textures="
        + (context.useTileTextures ? "1" : "0")
        + "|root="
        + context.tileRootPath
        + "|palette="
        + context.palettePath
        + "|asset=" + context.assetRootPath
        + "|structures=" + context.structureRootPath
        + "|structure-palette=" + context.structurePalettePath;
}

const RuntimeShadowReceiverTerrainLookup& ensureRuntimeTerrainCellLookup(
    const GameWorld& world,
    RuntimeMapRenderCache& cache
) {
    const std::vector<TerrainCell>& terrainCells = world.getTerrainCells();
    const TerrainCell* terrainData =
        terrainCells.empty() ? nullptr : terrainCells.data();
    if (cache.terrainLookupWorld == &world
        && cache.terrainLookupData == terrainData
        && cache.terrainLookupCount == terrainCells.size()) {
        return cache.terrainByCell;
    }

    cache.terrainLookupWorld = &world;
    cache.terrainLookupData = terrainData;
    cache.terrainLookupCount = terrainCells.size();
    cache.terrainByCell.clear();
    cache.terrainByCell.reserve(terrainCells.size());
    constexpr std::size_t runtimeTerrainCellIndexCapacity = 512U * 512U;
    cache.terrainByCellIndex.assign(
        runtimeTerrainCellIndexCapacity,
        nullptr
    );
    for (const TerrainCell& cell : terrainCells) {
        cache.terrainByCell.emplace(
            runtimeTerrainCellCoordinateKey(cell.x, cell.y),
            &cell
        );
        const int cellIndex = cell.cellIndex512 >= 0
            ? cell.cellIndex512
            : ((cell.x >= 0 && cell.y >= 0)
                ? (cell.y * 512) + cell.x
                : -1);
        if (cellIndex >= 0
            && cellIndex
                < static_cast<int>(cache.terrainByCellIndex.size())) {
            cache.terrainByCellIndex[static_cast<std::size_t>(cellIndex)] =
                &cell;
        }
    }
    return cache.terrainByCell;
}

void stampRuntimeBridgeSurfaceSpans(
    RuntimeTerrainLayerCache& layer,
    const std::vector<RuntimeSpriteHitSpan>& spans,
    const RECT& bounds,
    const TerrainCell& cell,
    const MapCellFacts* mapFact,
    const RuntimeMapCamera& camera,
    RuntimeMapRenderCache& cache
) {
    const bool high = runtimeOverlayLooksLikeHighBridge(cell);
    const int deckLevel = cell.level + (high ? 4 : 0);
    const auto terrainAt = [&cache](int x, int y) -> const TerrainCell* {
        if (x < 0 || y < 0 || x >= 512 || y >= 512) return nullptr;
        const auto index = static_cast<std::size_t>(y * 512 + x);
        return index < cache.terrainByCellIndex.size()
            ? cache.terrainByCellIndex[index] : nullptr;
    };
    const auto intactDeck = [&](const TerrainCell* candidate) {
        if (candidate == nullptr || candidate->level != cell.level
            || !runtimeOverlayLooksLikeHighBridge(*candidate)) return false;
        const int frame = candidate->overlayFrame;
        return frame != 7 && frame != 8 && frame != 16 && frame != 17;
    };
    const auto sameHeightHead = [&](const TerrainCell* candidate) {
        return candidate != nullptr && candidate->level == deckLevel
            && !runtimeOverlayLooksLikeHighBridge(*candidate);
    };
    // A high-bridge sprite paints deck width and overhangs. Its source map
    // cell is not the cell under every opaque pixel. Resolve the deck plane
    // first, then constrain railing pixels to the connected bridge footprint.
    std::vector<const TerrainCell*> neighboringDeck;
    if (high) {
        const TerrainCell* source = terrainAt(cell.x, cell.y);
        if (!intactDeck(source)) return;
        neighboringDeck.push_back(source);
        const bool alongX = runtimeResourceOverlayFrame(cell, mapFact) % 18 < 9;
        const int searchSteps = std::clamp(
            (bounds.right - bounds.left) / std::max(1, camera.tileWidth)
                + (bounds.bottom - bounds.top) / std::max(1, camera.tileHeight) + 2,
            1L, 16L);
        for (int direction : {-1, 1}) {
            for (int step = 1; step <= searchSteps; ++step) {
                const auto* candidate = terrainAt(
                    cell.x + (alongX ? direction * step : 0),
                    cell.y + (alongX ? 0 : direction * step));
                if (!intactDeck(candidate)) {
                    if (sameHeightHead(candidate)) neighboringDeck.push_back(candidate);
                    break;
                }
                neighboringDeck.push_back(candidate);
            }
        }
    }
    for (const auto& span : spans) {
        if (span.y < 0 || span.y >= layer.height) continue;
        for (int x = std::max(0, static_cast<int>(span.left));
                x < std::min(layer.width, static_cast<int>(span.right)); ++x) {
            const auto index = static_cast<std::size_t>(span.y) * layer.width + x;
            int owner = cell.y * 512 + cell.x;
            if (high) {
                // The compositor paints an opaque deferred deck over the
                // terrain layer. Follow that visible order even when the
                // covered terrain's nominal height is greater than the deck.
                const double worldX = x + layer.originX;
                const double worldY = span.y + layer.originY
                    + deckLevel * camera.tileHeight / 2.0;
                const int cellX = static_cast<int>(std::floor(
                    worldY / camera.tileHeight + worldX / camera.tileWidth + 0.5));
                const int cellY = static_cast<int>(std::floor(
                    worldY / camera.tileHeight - worldX / camera.tileWidth + 0.5));
                const TerrainCell* selected = terrainAt(cellX, cellY);
                if (!intactDeck(selected) && !sameHeightHead(selected)) {
                    selected = nullptr;
                    long long bestDistance = std::numeric_limits<long long>::max();
                    for (const auto* candidate : neighboringDeck) {
                        const long long dx = static_cast<long long>(x + layer.originX)
                            - (candidate->x - candidate->y) * camera.tileWidth / 2;
                        const long long dy = static_cast<long long>(span.y + layer.originY)
                            - (candidate->x + candidate->y - deckLevel) * camera.tileHeight / 2;
                        const long long distance = dx * dx + 4 * dy * dy;
                        if (distance < bestDistance
                            || (distance == bestDistance && selected != nullptr
                                && std::make_tuple(candidate->x + candidate->y, candidate->y, candidate->x)
                                    > std::make_tuple(selected->x + selected->y, selected->y, selected->x))) {
                            selected = candidate;
                            bestDistance = distance;
                        }
                    }
                }
                if (selected == nullptr) continue;
                owner = selected->y * 512 + selected->x;
            }
            layer.surfaceCellIndices[index] = owner;
        }
    }
}

void stampRuntimeHighBridgePatchSurfaceOwnership(
    RuntimeTerrainLayerCache& layer, const POINT& center,
    const RuntimeTmpSubTileImage& image, int sourceCellIndex,
    const RuntimeMapCamera& camera, RuntimeMapRenderCache& cache
) {
    if (sourceCellIndex < 0 || static_cast<std::size_t>(sourceCellIndex)
            >= cache.terrainByCellIndex.size()) return;
    const auto* cell = cache.terrainByCellIndex[static_cast<std::size_t>(sourceCellIndex)];
    if (cell == nullptr) return;
    const int globalWidth = image.globalWidth > 0 ? image.globalWidth : image.width;
    const int globalHeight = image.globalHeight > 0 ? image.globalHeight : image.height;
    const int left = center.x - globalWidth / 2 + image.offsetX;
    const int top = center.y - globalHeight / 2 + image.offsetY;
    std::vector<RuntimeSpriteHitSpan> spans;
    RuntimeSpriteGeometryCapture capture;
    capture.hitSpans = &spans;
    capture.recordPixels(RECT{left, top, left + image.width, top + image.height},
        image.width, image.height, image.pixels);
    stampRuntimeBridgeSurfaceSpans(layer, spans, capture.bounds, *cell,
        nullptr, camera, cache);
}

void stampRuntimeBridgeSurfaceOwnership(
    RuntimeTerrainLayerCache& layer, const POINT& center,
    const TerrainCell& cell, const MapCellFacts* mapFact,
    const RuntimeMapRenderContext& context, const RuntimeMapCamera& camera,
    RuntimeMapRenderCache& cache
) {
    std::vector<RuntimeSpriteHitSpan> spans;
    RuntimeSpriteGeometryCapture capture;
    capture.hitSpans = &spans;
    const RECT viewport{0, 0, layer.width, layer.height};
    {
        RuntimeSpriteGeometryScope scope(&capture);
        if (!drawRuntimeBridgeOverlaySprite(nullptr, viewport, center, cell,
                mapFact, context, camera, cache)) return;
    }
    stampRuntimeBridgeSurfaceSpans(layer, spans, capture.bounds, cell,
        mapFact, camera, cache);
}

bool buildTerrainLayer(
    const GameWorld& world,
    const RuntimeMapRenderContext& context,
    const RuntimeMapCamera& camera,
    int viewportWidth,
    int viewportHeight,
    RuntimeMapRenderCache& cache
) {
    const RuntimeTerrainLayerRegion region =
        runtimeTerrainLayerRegionForViewport(
            camera,
            viewportWidth,
            viewportHeight
        );
    const std::string key =
        buildTerrainLayerKey(world, context, camera, region);
    if (cache.terrainLayer.built && cache.terrainLayer.key == key) {
        ++cache.terrainLayerCacheHits;
        return true;
    }
    ++cache.terrainLayerCacheMisses;

    if (region.width <= 0 || region.height <= 0) {
        return false;
    }

    RuntimeTerrainLayerCache layer;
    layer.key = key;
    layer.originX = region.originX;
    layer.originY = region.originY;
    layer.width = region.width;
    layer.height = region.height;

    if (layer.width <= 0 || layer.height <= 0) {
        return false;
    }
    if (!ensureRuntimePalette(context, cache) || cache.palette.size() < 256) {
        return false;
    }
    std::array<std::uint32_t, 256> packedPalette{};
    for (int paletteIndex = 0; paletteIndex < 256; ++paletteIndex) {
        packedPalette[static_cast<std::size_t>(paletteIndex)] =
            packDibColor(cache.palette[static_cast<std::size_t>(paletteIndex)]);
    }

    const std::size_t pixelCount =
        static_cast<std::size_t>(layer.width)
        * static_cast<std::size_t>(layer.height);
    layer.pixels.assign(pixelCount, packDibColor(RGB(15, 22, 31)));
    layer.terrainCellIndices.assign(pixelCount, -1);
    layer.surfaceCellIndices.assign(pixelCount, -1);
    // Fresh for every cache rebuild; never reuse Z across camera buckets or tiles.
    layer.terrainDepthWords.assign(pixelCount, 0xffffU);
    const RuntimeTmpSubTileImage* clearImage =
        resolveTerrainCellImage(0, 0, context, cache);
    const RECT layerWorldRect{
        layer.originX - camera.tileWidth,
        layer.originY - (camera.tileHeight * 6),
        layer.originX + layer.width + camera.tileWidth,
        layer.originY + layer.height + (camera.tileHeight * 6)
    };
    for (const TerrainCell& cell : world.getTerrainCells()) {
        const int terrainCellIndex = cell.cellIndex512 >= 0
            ? cell.cellIndex512
            : ((cell.x >= 0 && cell.y >= 0 && cell.x < 512 && cell.y < 512)
                ? (cell.y * 512) + cell.x
                : -1);
        const ProjectedPoint projected = projectCell(cell, camera);
        const RECT tileWorldRect{
            projected.x - camera.tileWidth,
            projected.y - (camera.tileHeight * 4),
            projected.x + camera.tileWidth,
            projected.y + (camera.tileHeight * 3)
        };
        if (!rectIntersects(tileWorldRect, layerWorldRect)
            && !runtimeBridgeSpriteIntersectsPaintArea(cell,
                POINT{projected.x, projected.y}, layerWorldRect,
                context, camera, cache)) {
            continue;
        }

        const POINT center{
            projected.x - layer.originX,
            projected.y - layer.originY
        };

        bool authoredEmptySubTile = false;
        const RuntimeTmpSubTileImage* image = resolveTerrainVisualCellImage(
            cell, context, cache, &authoredEmptySubTile);
        bool drewTexture = false;
        if (image != nullptr) {
            drewTexture = drawTmpTileImageZBufferedToLayer(
                layer, layer.terrainDepthWords, center, cell, camera, *image,
                packedPalette, terrainCellIndex) || drewTexture;
        } else if (authoredEmptySubTile) {
            drewTexture = true;
            ++layer.authoredEmptyTerrainSubTiles;
        } else if (clearImage != nullptr) {
            drewTexture = drawTmpTileImageZBufferedToLayer(
                layer, layer.terrainDepthWords, center, cell, camera, *clearImage,
                packedPalette, terrainCellIndex);
        }

        if (drewTexture) {
            ++layer.texturedTerrainCells;
        } else {
            const COLORREF fillColor =
                colorForTerrainCell(cell, world, context, cache);
            drawDiamondToLayer(
                layer,
                center,
                camera.tileWidth,
                camera.tileHeight,
                fillColor,
                terrainCellIndex
            );
            ++layer.fallbackTerrainCells;
        }

        ++layer.terrainCells;
    }

    ensureRuntimeTerrainCellLookup(world, cache);
    const std::vector<const TerrainCell*>& terrainCellsByIndex =
        cache.terrainByCellIndex;
    const auto terrainCellAt =
        [&terrainCellsByIndex](int x, int y) -> const TerrainCell* {
            if (x < 0 || y < 0 || x >= 512 || y >= 512) {
                return nullptr;
            }
            const std::size_t cellIndex =
                static_cast<std::size_t>((y * 512) + x);
            return cellIndex < terrainCellsByIndex.size()
                ? terrainCellsByIndex[cellIndex]
                : nullptr;
    };
    std::unordered_set<int> highBridgeHeadRedrawIndexes;
    struct RuntimeHighBridgePostHeadPatch {
        POINT center{};
        std::string imageId;
        int frameIndex = 0;
        int surfaceCellIndex = -1;
    };
    std::vector<RuntimeHighBridgePostHeadPatch>
        highBridgePostHeadPatches;
    struct RuntimeBridgeSurfaceDraw {
        POINT center{};
        TerrainCell cell;
        const MapCellFacts* mapFact = nullptr;
    };
    std::vector<RuntimeBridgeSurfaceDraw> deferredBridgeSurfaces;

    for (const TerrainCell& cell : world.getTerrainCells()) {
        const ProjectedPoint projected = projectCell(cell, camera);
        const RECT tileWorldRect{
            projected.x - camera.tileWidth,
            projected.y - (camera.tileHeight * 4),
            projected.x + camera.tileWidth,
            projected.y + (camera.tileHeight * 3)
        };
        if (!rectIntersects(tileWorldRect, layerWorldRect)
            && !runtimeBridgeSpriteIntersectsPaintArea(cell,
                POINT{projected.x, projected.y}, layerWorldRect,
                context, camera, cache)) {
            continue;
        }

        const MapCellFacts* mapFact = nullptr;
        if (context.mapFacts != nullptr) {
            int cellIndex = cell.cellIndex512;
            if (cellIndex < 0 && cell.x >= 0 && cell.y >= 0) {
                cellIndex = (cell.y * 512) + cell.x;
            }
            if (cellIndex >= 0) {
                const auto found =
                    context.mapFacts->cellIndexLookup.find(cellIndex);
                if (found != context.mapFacts->cellIndexLookup.end()
                    && found->second < context.mapFacts->cells.size()) {
                    mapFact = &context.mapFacts->cells[found->second];
                }
            }
        }
        TerrainCell mapFactRenderCell;
        const TerrainCell* renderCell = &cell;
        if (mapFact != nullptr
            && mapFact->hasOverlay
            && cell.hasOverlay
            && cell.overlayIndex == mapFact->overlay.overlayIndex) {
            mapFactRenderCell = cell;
            mapFactRenderCell.hasOverlay = true;
            mapFactRenderCell.overlayIndex = mapFact->overlay.overlayIndex;
            mapFactRenderCell.overlayFrame = cell.overlayFrame >= 0
                ? cell.overlayFrame
                : (mapFact->overlay.frameIndex != 0
                    ? mapFact->overlay.frameIndex
                    : (mapFact->overlay.frame != 0
                        ? mapFact->overlay.frame
                        : mapFact->overlay.fallbackFrame));
            mapFactRenderCell.overlayType = mapFact->overlay.type;
            mapFactRenderCell.overlayImage = mapFact->overlay.image;
            mapFactRenderCell.overlayIsOre = mapFact->isOre;
            mapFactRenderCell.overlayIsGem = mapFact->isGem;
            renderCell = &mapFactRenderCell;
        }
        const bool bridgeOverlay =
            renderCell->hasOverlay
            && ((mapFact != nullptr && mapFact->isBridge)
                || runtimeOverlayLooksLikeBridge(*renderCell))
            && runtimeBridgeOverlaySupportedByTerrainContext(
                *renderCell,
                mapFact
            );
        if (!bridgeOverlay) {
            continue;
        }
        if (runtimeOverlayLooksLikeHighBridge(*renderCell)) {
            deferredBridgeSurfaces.push_back({
                {projected.x - layer.originX, projected.y - layer.originY},
                *renderCell, mapFact});
            // Keep the visible deck deferred between below-bridge and
            // on-bridge objects. A terminal frame can have a short
            // transparent wedge before the neighboring elevated bridgehead,
            // so place an axial extension underneath that static terrain.
            // Connected damage frames keep this terminal support. A local
            // gap must not remove the intact bank joints farther away.
            const int bridgeFrame = runtimeResourceOverlayFrame(
                *renderCell,
                mapFact
            );
            const bool alongX = bridgeFrame <= 8;
            const int intactFrame = alongX ? 0 : 9;
            if (bridgeFrame < intactFrame || bridgeFrame > intactFrame + 6) {
                continue;
            }
            const std::array<POINT, 2> axisDirections = alongX
                ? std::array<POINT, 2>{POINT{-1, 0}, POINT{1, 0}}
                : std::array<POINT, 2>{POINT{0, -1}, POINT{0, 1}};
            const std::string overlayImage =
                !renderCell->overlayImage.empty()
                    ? renderCell->overlayImage
                    : renderCell->overlayType;
            const int extensionX = std::max(1, (camera.tileWidth * 2) / 15);
            const int extensionY = std::max(1, (camera.tileHeight * 2) / 15);
            for (const POINT& direction : axisDirections) {
                const TerrainCell* bridgehead = terrainCellAt(
                    cell.x + direction.x,
                    cell.y + direction.y
                );
                if (bridgehead == nullptr
                    || bridgehead->level < renderCell->level + 3) {
                    continue;
                }

                bool hasSupportedTerminal = false;
                int intactDeckCells = 1;
                int scanX = cell.x - direction.x;
                int scanY = cell.y - direction.y;
                for (int step = 0; step < 128; ++step) {
                    const TerrainCell* scanCell = terrainCellAt(scanX, scanY);
                    if (scanCell == nullptr) {
                        break;
                    }
                    if (scanCell->hasOverlay
                        && runtimeOverlayLooksLikeHighBridge(*scanCell)
                        && scanCell->overlayIndex == renderCell->overlayIndex
                        && scanCell->overlayFrame >= intactFrame
                        && scanCell->overlayFrame <= intactFrame + 6) {
                        ++intactDeckCells;
                        scanX -= direction.x;
                        scanY -= direction.y;
                        continue;
                    }
                    // The supported leg can end at the opposite bank or
                    // a local collapsed cap; neither alters this bank joint.
                    hasSupportedTerminal = intactDeckCells >= 2;
                    break;
                }
                if (!hasSupportedTerminal) {
                    continue;
                }

                bool patchAfterHead = false;
                if (context.theater != nullptr) {
                    const TheaterTileReference bridgeheadTile =
                        context.theater->resolveTileIndex(
                            bridgehead->tileIndex
                        );
                    // These exposed bank faces can cover the terminal deck.
                    // Restore its full native phase after the head so the road
                    // and sidewalks meet the bank; Ovrps03 applies on X only.
                    const std::string headImage =
                        toLowerAscii(bridgeheadTile.baseFileName);
                    patchAfterHead = (alongX && headImage == "ovrps03")
                        || headImage == "ovrps04"
                        || headImage == "ovrps05";
                }
                const int axialExtensionX = patchAfterHead
                    ? std::max(1, camera.tileWidth / 2)
                    : extensionX;
                const int axialExtensionY = patchAfterHead
                    ? std::max(1, camera.tileHeight / 2)
                    : extensionY;
                POINT underlayCenter{
                    projected.x - layer.originX - (camera.tileWidth / 2),
                    projected.y - layer.originY
                        - (camera.tileHeight / 2) - 1
                };
                underlayCenter.x +=
                    (direction.x - direction.y) * axialExtensionX;
                underlayCenter.y +=
                    (direction.x + direction.y) * axialExtensionY;
                if (patchAfterHead) {
                    highBridgePostHeadPatches.push_back({
                        underlayCenter,
                        overlayImage,
                        bridgeFrame,
                        cell.y * 512 + cell.x
                    });
                } else if (drawRuntimeHighBridgeTmpSpriteToLayer(
                        layer,
                        underlayCenter,
                        context,
                        camera,
                        cache,
                        packedPalette,
                        overlayImage,
                        bridgeFrame,
                        cell.y * 512 + cell.x
                    )) {
                    ++layer.highBridgeTerminalUnderlays;
                }

                for (int lane = -1; lane <= 1; ++lane) {
                    const int headX = bridgehead->x + (alongX ? 0 : lane);
                    const int headY = bridgehead->y + (alongX ? lane : 0);
                    const TerrainCell* headCell = terrainCellAt(headX, headY);
                    if (headCell == nullptr
                        || headCell->level < bridgehead->level) {
                        continue;
                    }
                    const int headIndex = headCell->cellIndex512 >= 0
                        ? headCell->cellIndex512
                        : (headY * 512) + headX;
                    highBridgeHeadRedrawIndexes.insert(headIndex);
                }
            }
            continue;
        }

        const std::string overlayImage =
            !renderCell->overlayImage.empty()
                ? renderCell->overlayImage
                : renderCell->overlayType;
        const int bridgeFrame = runtimeResourceOverlayFrame(
            *renderCell,
            mapFact
        );
        const std::string lowBridgeSegmentImage =
            runtimeLowBridgeSegmentImageId(*renderCell);
        const POINT center{
            projected.x - layer.originX,
            projected.y - layer.originY
        };
        bool drewBridge = false;
        if (!lowBridgeSegmentImage.empty()) {
            drewBridge = drawRuntimeLowBridgeTmpSpriteToLayer(
                layer,
                center,
                context,
                cache,
                packedPalette,
                lowBridgeSegmentImage,
                bridgeFrame,
                cell.y * 512 + cell.x
            );
        } else if (runtimeOverlayLooksLikeHighBridge(*renderCell)) {
            drewBridge = drawRuntimeHighBridgeTmpSpriteToLayer(
                layer,
                center,
                context,
                camera,
                cache,
                packedPalette,
                overlayImage,
                bridgeFrame,
                cell.y * 512 + cell.x
            );
        } else {
            drewBridge = drawRuntimeAuxiliaryTmpSpriteToLayer(
                layer,
                center,
                context,
                camera,
                cache,
                packedPalette,
                overlayImage,
                bridgeFrame,
                cell.y * 512 + cell.x
            );
        }
        if (drewBridge) {
            const int bridgeCellIndex = cell.cellIndex512 >= 0
                ? cell.cellIndex512
                : ((cell.x >= 0 && cell.y >= 0)
                    ? (cell.y * 512) + cell.x
                    : -1);
            if (bridgeCellIndex >= 0) {
                layer.bridgeOverlayCellIndexes.insert(bridgeCellIndex);
            }
        } else {
            // Low bridges which fall back to SHP are drawn outside the baked
            // layer by the compositor. Capture that exact fallback as well.
            deferredBridgeSurfaces.push_back({center, *renderCell, mapFact});
        }
    }

    for (int cellIndex : highBridgeHeadRedrawIndexes) {
        if (cellIndex < 0
            || cellIndex >= static_cast<int>(terrainCellsByIndex.size())
            || terrainCellsByIndex[static_cast<std::size_t>(cellIndex)]
                == nullptr) {
            continue;
        }
        const TerrainCell& bridgehead =
            *terrainCellsByIndex[static_cast<std::size_t>(cellIndex)];
        const RuntimeTmpSubTileImage* image =
            resolveTerrainCellImage(bridgehead, context, cache);
        if (image == nullptr) {
            continue;
        }
        const ProjectedPoint projected = projectCell(bridgehead, camera);
        const POINT center{
            projected.x - layer.originX,
            projected.y - layer.originY
        };
        drawTmpTileImageToLayer(
            layer,
            center,
            camera,
            *image,
            packedPalette,
            -1,
            cellIndex
        );
    }

    for (const RuntimeHighBridgePostHeadPatch& patch :
            highBridgePostHeadPatches) {
        if (drawRuntimeHighBridgeTmpSpriteToLayer(
                layer,
                patch.center,
                context,
                camera,
                cache,
                packedPalette,
                patch.imageId,
                patch.frameIndex,
                patch.surfaceCellIndex
            )) {
            ++layer.highBridgeTerminalUnderlays;
        }
    }

    // The compositor draws fallback low bridges before deferred high decks.
    // Keep the same order while excluding units, effects, and shroud entirely.
    for (bool high : {false, true}) {
        for (const auto& bridge : deferredBridgeSurfaces) {
            if (runtimeOverlayLooksLikeHighBridge(bridge.cell) == high) {
                stampRuntimeBridgeSurfaceOwnership(layer, bridge.center,
                    bridge.cell, bridge.mapFact, context, camera, cache);
            }
        }
    }

    layer.built = true;
    cache.terrainLayer = std::move(layer);
    return true;
}

bool drawTerrainLayerToViewport(
    HDC dc,
    const RECT& viewport,
    const RuntimeMapRenderContext& context,
    const RuntimeMapCamera& camera,
    const RuntimeTerrainLayerCache& layer
) {
    if (!layer.built
        || layer.pixels.empty()
        || layer.width <= 0
        || layer.height <= 0) {
        return false;
    }

    const int layerScreenX =
        viewport.left + layer.originX - camera.worldOffsetX;
    const int layerScreenY =
        viewport.top + layer.originY - camera.worldOffsetY;
    const int viewportLeft = static_cast<int>(viewport.left);
    const int viewportTop = static_cast<int>(viewport.top);
    const int viewportRight = static_cast<int>(viewport.right);
    const int viewportBottom = static_cast<int>(viewport.bottom);
    const int destX = std::max(viewportLeft, layerScreenX);
    const int destY = std::max(viewportTop, layerScreenY);
    const int destRight =
        std::min(viewportRight, layerScreenX + layer.width);
    const int destBottom =
        std::min(viewportBottom, layerScreenY + layer.height);
    const int copyWidth = destRight - destX;
    const int copyHeight = destBottom - destY;
    if (copyWidth <= 0 || copyHeight <= 0) {
        return true;
    }

    const int sourceX = destX - layerScreenX;
    const int sourceY = destY - layerScreenY;

    if (hasPixelSurface(context)
        && destX >= 0
        && destY >= 0
        && destRight <= context.surfaceWidth
        && destBottom <= context.surfaceHeight) {
        for (int row = 0; row < copyHeight; ++row) {
            const std::uint32_t* source =
                layer.pixels.data()
                + (static_cast<std::size_t>(sourceY + row)
                    * static_cast<std::size_t>(layer.width))
                + static_cast<std::size_t>(sourceX);
            std::uint32_t* target =
                context.surfacePixels
                + (static_cast<std::size_t>(destY + row)
                    * static_cast<std::size_t>(context.surfaceWidth))
                + static_cast<std::size_t>(destX);
            std::memcpy(
                target,
                source,
                static_cast<std::size_t>(copyWidth)
                    * sizeof(std::uint32_t)
            );
        }
        return true;
    }

    static thread_local std::vector<std::uint32_t> visiblePixels;
    const std::size_t visiblePixelCount =
        static_cast<std::size_t>(copyWidth)
        * static_cast<std::size_t>(copyHeight);
    if (visiblePixels.size() < visiblePixelCount) {
        visiblePixels.resize(visiblePixelCount);
    }
    for (int row = 0; row < copyHeight; ++row) {
        const std::uint32_t* source =
            layer.pixels.data()
            + (static_cast<std::size_t>(sourceY + row)
                * static_cast<std::size_t>(layer.width))
            + static_cast<std::size_t>(sourceX);
        std::uint32_t* target =
            visiblePixels.data()
            + (static_cast<std::size_t>(row)
                * static_cast<std::size_t>(copyWidth));
        std::memcpy(
            target,
            source,
            static_cast<std::size_t>(copyWidth) * sizeof(std::uint32_t)
        );
    }

    BITMAPINFO bitmapInfo{};
    bitmapInfo.bmiHeader.biSize = sizeof(BITMAPINFOHEADER);
    bitmapInfo.bmiHeader.biWidth = copyWidth;
    bitmapInfo.bmiHeader.biHeight = -copyHeight;
    bitmapInfo.bmiHeader.biPlanes = 1;
    bitmapInfo.bmiHeader.biBitCount = 32;
    bitmapInfo.bmiHeader.biCompression = BI_RGB;

    const int result = StretchDIBits(
        dc,
        destX,
        destY,
        copyWidth,
        copyHeight,
        0,
        0,
        copyWidth,
        copyHeight,
        visiblePixels.data(),
        &bitmapInfo,
        DIB_RGB_COLORS,
        SRCCOPY
    );

    return result != GDI_ERROR;
}

