std::vector<RuntimePaletteColor> runtimeOwnerRemappedUiPalette(
    const std::vector<RuntimePaletteColor>& palette,
    COLORREF ownerColor
) {
    if (palette.size() < 256) return {};
    auto remapped = palette;
    for (std::size_t index = 16; index <= 31; ++index) {
        remapped[index] = runtimePaletteColorWithOwnerRemap(
            palette, static_cast<unsigned char>(index), true, ownerColor);
    }
    return remapped;
}

