bool runRuntimeVisionRenderContractCheck(std::string& errorMessage) {
    if (!runRuntimeMapLightTerrainCacheContractCheck(errorMessage)) return false;
    if (!runRuntimeLightingLookupRenderContractCheck(errorMessage)) {
        return false;
    }
    if (!runRuntimeIndexedOpaqueSpanContractCheck(errorMessage)) {
        return false;
    }
    if (!runRuntimeVisionIncrementalContractCheck(errorMessage)) {
        return false;
    }
    if (!runRuntimeShroudBlurContractCheck(errorMessage)) {
        return false;
    }
    if (!runRuntimeVisionColdPathContractCheck(errorMessage)) {
        return false;
    }
    if (!runRuntimePaletteCacheHitContractCheck(errorMessage)) {
        return false;
    }
    if (!runRuntimeVisionOverlayMovementContractCheck(errorMessage)) {
        return false;
    }
    GameWorld world;
    for (int y = 0; y <= 20; ++y) {
        for (int x = 0; x <= 20; ++x) {
            TerrainCell cell;
            cell.x = x;
            cell.y = y;
            cell.cellIndex512 = (y * 512) + x;
            world.accessTerrainCells().push_back(cell);
        }
    }

    WorldObjectInstance scout;
    scout.instanceId = 1;
    scout.kind = WorldObjectKind::Infantry;
    scout.owner = "Observer";
    scout.type = "SCOUT";
    scout.x = 5;
    scout.y = 5;
    scout.alive = true;
    world.accessObjects().push_back(scout);

    WorldObjectInstance rememberedBuilding;
    rememberedBuilding.instanceId = 2;
    rememberedBuilding.kind = WorldObjectKind::Structure;
    rememberedBuilding.owner = "Enemy";
    rememberedBuilding.type = "BUILDING";
    rememberedBuilding.x = 8;
    rememberedBuilding.y = 5;
    rememberedBuilding.alive = true;
    world.accessObjects().push_back(rememberedBuilding);

    WorldObjectInstance mobileEnemy = rememberedBuilding;
    mobileEnemy.instanceId = 3;
    mobileEnemy.kind = WorldObjectKind::Unit;
    mobileEnemy.type = "MOBILE";
    world.accessObjects().push_back(mobileEnemy);

    WorldObjectInstance unexploredBuilding = rememberedBuilding;
    unexploredBuilding.instanceId = 4;
    unexploredBuilding.x = 20;
    unexploredBuilding.y = 20;
    world.accessObjects().push_back(unexploredBuilding);

    const std::vector<RuntimeVisionObserverDefinition> observers{
        {"Observer", {"Observer"}},
        {"Enemy", {"Enemy"}}
    };
    RuntimeVisionSystem vision;
    (void)vision.update(world, nullptr, observers, 1);
    world.accessObjects()[0].x = 1;
    world.accessObjects()[0].y = 1;
    (void)vision.update(world, nullptr, observers, 2);

    RuntimeMapRenderContext context;
    context.vision = &vision;
    context.visionObserverOwner = "Observer";
    const std::vector<RuntimeProjectileRenderActor> effectActors(1);
    context.projectileActors = &effectActors;
    const bool terrainOwnershipRetainedForSmallViewport =
        runtimeShouldBuildTerrainLayer(context, 320, 200);
    context.projectileActors = nullptr;
    const bool rememberedCellFogged =
        vision.visibilityFor("Observer", 8, 5)
            == RuntimeCellVisibility::Fogged;
    const bool buildingRemembered = runtimeVisionObjectBodyShouldRender(
        context,
        world.getObjects()[1]
    );
    const bool mobileStillVisible = runtimeVisionObjectBodyShouldRender(
        context,
        world.getObjects()[2]
    );
    const bool unexploredBuildingHidden = !runtimeVisionObjectBodyShouldRender(
        context,
        world.getObjects()[3]
    );
    const bool liveEffectsStillVisible =
        runtimeVisionObjectHasCurrentVisibility(
            context,
            world.getObjects()[1]
        )
        && runtimeVisionActorIsVisible(context, "Enemy", 8, 5)
        && !runtimeVisionActorIsVisible(context, "Enemy", 20, 20);

    constexpr int cacheProbeWidth = 128;
    constexpr int cacheProbeHeight = 128;
    constexpr RECT cacheProbeViewport{
        0,
        0,
        cacheProbeWidth,
        cacheProbeHeight
    };
    std::vector<std::uint32_t> cacheProbeSource(
        static_cast<std::size_t>(cacheProbeWidth * cacheProbeHeight)
    );
    for (std::size_t index = 0; index < cacheProbeSource.size(); ++index) {
        cacheProbeSource[index] = static_cast<std::uint32_t>(
            (index * 2654435761ULL) & 0x00ffffffULL
        );
    }
    // A cliff/ramp overhang can extend outside its cell's projected base
    // diamond. Authored terrain owned by an unexplored cell must still be
    // replaced by opaque shroud instead of leaking through that empty gap.
    constexpr int overhangProbeX = 64;
    constexpr int overhangProbeY = 49;
    constexpr int overhangOwnerCellIndex = (10 * 512) + 10;
    constexpr std::size_t overhangProbeOffset =
        static_cast<std::size_t>(overhangProbeY * cacheProbeWidth)
        + static_cast<std::size_t>(overhangProbeX);
    cacheProbeSource[overhangProbeOffset] = 0x00f0a020U;
    std::vector<std::uint32_t> firstCacheProbe = cacheProbeSource;
    std::vector<std::uint32_t> secondCacheProbe = cacheProbeSource;
    RuntimeMapCamera cacheProbeCamera;
    cacheProbeCamera.initialized = true;
    cacheProbeCamera.worldOffsetX = -64;
    // Keep every synthetic base diamond outside the probe viewport. The lone
    // authored terrain pixel below can then become dark only through the TMP
    // ownership path, so the fast grid lookup cannot be accidentally masked
    // by the ordinary geometric shroud.
    cacheProbeCamera.worldOffsetY = 1000;
    RuntimeMapRenderCache cacheProbe;
    cacheProbe.terrainLayer.built = true;
    cacheProbe.terrainLayer.key = "vision-overhang-fast-grid-probe";
    cacheProbe.terrainLayer.originX = cacheProbeCamera.worldOffsetX;
    cacheProbe.terrainLayer.originY = cacheProbeCamera.worldOffsetY;
    cacheProbe.terrainLayer.width = cacheProbeWidth;
    cacheProbe.terrainLayer.height = cacheProbeHeight;
    cacheProbe.terrainLayer.pixels.assign(cacheProbeSource.size(), 0);
    cacheProbe.terrainLayer.terrainCellIndices.assign(
        cacheProbeSource.size(),
        -1
    );
    cacheProbe.terrainLayer.pixels[overhangProbeOffset] =
        cacheProbeSource[overhangProbeOffset];
    cacheProbe.terrainLayer.terrainCellIndices[overhangProbeOffset] =
        overhangOwnerCellIndex;
    RuntimeMapRenderStats firstCacheProbeStats;
    RuntimeMapRenderStats secondCacheProbeStats;
    context.surfacePixels = firstCacheProbe.data();
    context.surfaceWidth = cacheProbeWidth;
    context.surfaceHeight = cacheProbeHeight;
    applyRuntimeVisionOverlay(
        nullptr,
        cacheProbeViewport,
        world,
        context,
        cacheProbeCamera,
        cacheProbe,
        firstCacheProbeStats
    );
    context.surfacePixels = secondCacheProbe.data();
    applyRuntimeVisionOverlay(
        nullptr,
        cacheProbeViewport,
        world,
        context,
        cacheProbeCamera,
        cacheProbe,
        secondCacheProbeStats
    );
    const bool overlayCacheExact = firstCacheProbe == secondCacheProbe
        && firstCacheProbeStats.visionOverlayPixels > 0
        && firstCacheProbeStats.visionOverlayCacheMisses == 1
        && secondCacheProbeStats.visionOverlayCacheHits == 1
        && secondCacheProbeStats.visionOverlayPixels
            == firstCacheProbeStats.visionOverlayPixels;
    const std::uint32_t overhangProbeColor =
        firstCacheProbe[overhangProbeOffset];
    const bool terrainOverhangFastGridOpaque =
        vision.visibilityFor("Observer", 10, 10)
            == RuntimeCellVisibility::Shrouded
        && static_cast<int>((overhangProbeColor >> 16U) & 0xffU) <= 8
        && static_cast<int>((overhangProbeColor >> 8U) & 0xffU) <= 12
        && static_cast<int>(overhangProbeColor & 0xffU) <= 16;

    if (!rememberedCellFogged
        || !terrainOwnershipRetainedForSmallViewport
        || !buildingRemembered
        || !mobileStillVisible
        || !unexploredBuildingHidden
        || !liveEffectsStillVisible
        || !overlayCacheExact
        || !terrainOverhangFastGridOpaque) {
        errorMessage =
            "explored-area visibility, shrouded terrain ownership, actor filtering, "
            "terrain-overhang opacity, or cached overlay replay failed";
        return false;
    }

    errorMessage.clear();
    return true;
}

bool runRuntimeChargeTurretRenderContractCheck(std::string& errorMessage) {
    errorMessage.clear();
    IniFile ini;
    RulesDatabase rules;
    const bool rulesLoaded = ini.loadFromString(
        "[InfantryTypes]\n[VehicleTypes]\n0=SREF\n1=TTNK\n"
        "[AircraftTypes]\n[BuildingTypes]\n[OverlayTypes]\n"
        "[Tiberiums]\n[TerrainTypes]\n[ParticleSystems]\n"
        "[Particles]\n[Warheads]\n"
        "[SREF]\nImage=SREF\nTurret=yes\nTurretCount=4\n"
        "IsChargeTurret=yes\n"
        "[TTNK]\nImage=TTNK\nTurret=yes\nTurretCount=1\n"
    ) && rules.loadFromIni(ini);

    RuntimeMapRenderContext context;
    context.rules = &rules;
    WorldObjectInstance prism;
    prism.kind = WorldObjectKind::Unit;
    prism.type = "SREF";
    prism.alive = true;
    prism.chargeTurretStartTick = 100;

    const auto firstCandidateAt = [&](int tick) {
        context.animationTick = tick;
        const std::vector<std::string> candidates =
            runtimeUnitTurretImageCandidates(prism, context);
        return candidates.empty() ? std::string() : candidates.front();
    };
    const std::array<std::string, 8> observed{{
        firstCandidateAt(99),
        firstCandidateAt(100),
        firstCandidateAt(104),
        firstCandidateAt(105),
        firstCandidateAt(109),
        firstCandidateAt(110),
        firstCandidateAt(114),
        firstCandidateAt(115)
    }};
    const std::array<std::string, 8> expected{{
        "SREFTUR",
        "SREFTUR3",
        "SREFTUR3",
        "SREFTUR2",
        "SREFTUR2",
        "SREFTUR1",
        "SREFTUR1",
        "SREFTUR"
    }};

    WorldObjectInstance control = prism;
    control.type = "TTNK";
    context.animationTick = 100;
    const std::vector<std::string> controlCandidates =
        runtimeUnitTurretImageCandidates(control, context);
    const bool controlValid = !controlCandidates.empty()
        && controlCandidates.front() == "TTNKTUR";
    const bool valid = rulesLoaded && observed == expected && controlValid;
    if (!valid) {
        errorMessage = "rules=" + std::to_string(rulesLoaded)
            + " control=" + std::to_string(controlValid)
            + " stages=";
        for (const std::string& candidate : observed) {
            errorMessage += candidate + ",";
        }
    }
    return valid;
}

