bool prewarmRuntimeStructureTurretVoxelFacingForRender(
    const std::string& structureType,
    int facingBucket,
    const RuntimeMapRenderContext& context,
    RuntimeMapRenderCache& cache,
    int& warmedSpriteCount,
    std::string& errorMessage
) {
    warmedSpriteCount = 0;
    errorMessage.clear();
    if (context.rules == nullptr) {
        errorMessage = "structure turret prewarm has no rules database";
        return false;
    }
    const BuildingType* buildingType =
        context.rules->findBuildingType(structureType);
    if (buildingType == nullptr
        || buildingType->turretAnim.empty()
        || !buildingType->turretAnimIsVoxel) {
        errorMessage =
            "structure has no voxel turret: " + structureType;
        return false;
    }

    const int bucket = positiveModulo(
        facingBucket,
        runtimeVoxelFacingBucketCount
    );
    const std::string turretCacheOwner =
        structureType + "|turretanim";
    const bool grandCannon =
        toLowerAscii(structureType) == "gtgcan"
        || toLowerAscii(buildingType->turretAnim) == "gtgcantur";
    RuntimeVoxelCacheEntry* sharedScaleTurret = nullptr;
    if (!grandCannon) {
        sharedScaleTurret = loadRuntimeVoxelImageFromCache(
            buildingType->turretAnim,
            turretCacheOwner,
            bucket,
            context,
            cache
        );
    }
    const double sharedPartFitScale =
        runtimeVxlSharedPartScaleEnabled()
            && sharedScaleTurret != nullptr
            && sharedScaleTurret->hasSprite
            ? sharedScaleTurret->rasterFitScale
            : 0.0;
    const double authoredPartFitScale =
        grandCannon
            ? runtimeGrandCannonModelScale()
            : sharedPartFitScale;
    RuntimeVoxelCacheEntry* turret = loadRuntimeVoxelImageFromCache(
        buildingType->turretAnim,
        turretCacheOwner,
        bucket,
        context,
        cache,
        authoredPartFitScale
    );
    if (turret != nullptr && turret->hasSprite) {
        ++warmedSpriteCount;
    }

    const std::string barrelCacheOwner =
        structureType + "|turretanim|barrel";
    const std::string barrelImageCacheKey =
        context.assetRootPath
        + "|structure="
        + toLowerAscii(structureType)
        + "|turret="
        + toLowerAscii(buildingType->turretAnim);
    auto resolvedBarrelIt =
        cache.structureTurretBarrelImageByKey.find(barrelImageCacheKey);
    if (resolvedBarrelIt == cache.structureTurretBarrelImageByKey.end()) {
        std::string resolvedBarrelImage;
        for (const std::string& barrelImageId :
                runtimeStructureTurretBarrelImageCandidates(
                    buildingType->turretAnim,
                    structureType
                )) {
            RuntimeVoxelCacheEntry* barrel =
                loadRuntimeVoxelImageFromCache(
                    barrelImageId,
                    barrelCacheOwner,
                    bucket,
                    context,
                    cache,
                    authoredPartFitScale
                );
            if (barrel != nullptr && barrel->hasSprite) {
                resolvedBarrelImage = barrelImageId;
                break;
            }
        }
        resolvedBarrelIt =
            cache.structureTurretBarrelImageByKey.emplace(
                barrelImageCacheKey,
                std::move(resolvedBarrelImage)
            ).first;
    }
    RuntimeVoxelCacheEntry* barrel = nullptr;
    if (!resolvedBarrelIt->second.empty()) {
        barrel = loadRuntimeVoxelImageFromCache(
            resolvedBarrelIt->second,
            barrelCacheOwner,
            bucket,
            context,
            cache,
            authoredPartFitScale
        );
    }
    if (barrel != nullptr && barrel->hasSprite) {
        ++warmedSpriteCount;
    }
    if (warmedSpriteCount == 2) {
        return true;
    }
    errorMessage =
        "voxel turret prewarm incomplete for "
        + structureType
        + " bucket="
        + std::to_string(bucket)
        + " sprites="
        + std::to_string(warmedSpriteCount);
    return false;
}

