    specialHost.type = "__SPECIAL_HOST__";
    specialHost.alive = true;
    specialHost.x = 4;
    specialHost.y = 4;
    specialHost.level = 1;
    specialWorld.accessObjects().push_back(specialHost);
    WorldObjectInstance magBeamSource = specialHost;
    magBeamSource.instanceId = 405;
    magBeamSource.x = 2;
    magBeamSource.y = 2;
    specialWorld.accessObjects().push_back(magBeamSource);
    SpecialMechanismRenderSnapshot timedBombSnapshot;
    timedBombSnapshot.kind = "timedBomb";
    timedBombSnapshot.objectId = 401;
    timedBombSnapshot.targetObjectId = specialHost.instanceId;
    timedBombSnapshot.progress = 3;
    timedBombSnapshot.requiredProgress = 12;
    timedBombSnapshot.expireTick = 20;
    timedBombSnapshot.phase = "Ivan";
    timedBombSnapshot.resourceId = "__WARHEAD_IS_NOT_ART__";
    SpecialMechanismRenderSnapshot parasiteSnapshot;
    parasiteSnapshot.kind = "parasite";
    parasiteSnapshot.objectId = 403;
    parasiteSnapshot.targetObjectId = specialHost.instanceId;
    parasiteSnapshot.phase = "organic";
