    RuntimeMapRenderStats progressOnlyMagBeamStats;
    drawRuntimeSpecialMechanismOverlays(
        nullptr,
        viewport,
        specialWorld,
        specialContext,
        particleCamera,
        specialCache,
        progressOnlyMagBeamStats
    );
    const bool magBeamProgressIsStatusOnly =
        progressOnlyMagBeamTargetPoint.x == posedMagBeamTargetPoint.x
        && progressOnlyMagBeamTargetPoint.y == posedMagBeamTargetPoint.y;
    GameWorld missingSpecialHostWorld;
    RuntimeMapRenderStats missingSpecialHostStats;
    drawRuntimeSpecialMechanismOverlays(
        nullptr,
        viewport,
        missingSpecialHostWorld,
        specialContext,
        particleCamera,
        specialCache,
        missingSpecialHostStats
    );
    SpecialMechanismRenderSnapshot airstrikeSnapshot;
    airstrikeSnapshot.kind = "airstrikeMarker";
    airstrikeSnapshot.cell = {2, 2};
    airstrikeSnapshot.targetCell = {4, 4};
    airstrikeSnapshot.radius = 2;
    airstrikeSnapshot.phase = "Inbound";
    airstrikeSnapshot.resourceId = "__AIRSTRIKE_WEAPON_IS_NOT_ART__";
    std::vector<SpecialMechanismRenderSnapshot> airstrikeSnapshots{
        airstrikeSnapshot
    };
    RuntimeMapRenderContext airstrikeContext;
    airstrikeContext.animationTick = specialContext.animationTick;
    airstrikeContext.specialMechanismSnapshots = &airstrikeSnapshots;
    RuntimeMapRenderStats airstrikeStats;
    drawRuntimeSpecialMechanismOverlays(
        nullptr,
        viewport,
        specialWorld,
        airstrikeContext,
        particleCamera,
        specialCache,
        airstrikeStats
    );
    const std::uint64_t firstAirstrikeHash =
        airstrikeStats.renderIntentHash;
    airstrikeSnapshots.front().targetCell = {5, 4};
    airstrikeSnapshots.front().radius = 3;
    airstrikeSnapshots.front().phase = "FinalApproach";
    RuntimeMapRenderStats changedAirstrikeStats;
    drawRuntimeSpecialMechanismOverlays(
        nullptr,
        viewport,
        specialWorld,
        airstrikeContext,
        particleCamera,
        specialCache,
        changedAirstrikeStats
    );
    airstrikeSnapshots.front().targetCell = {-1, -1};
    RuntimeMapRenderStats invalidAirstrikeStats;
    drawRuntimeSpecialMechanismOverlays(
        nullptr,
        viewport,
        specialWorld,
        airstrikeContext,
        particleCamera,
        specialCache,
        invalidAirstrikeStats
    );
    const bool specialMechanismValid =
        specialStats.specialMechanismRenderActors == 4
        && firstSpecialHash != 0
        && changedSpecialStats.specialMechanismRenderActors == 4
        && changedSpecialStats.renderIntentHash != firstSpecialHash
        && changedPsychicStats.specialMechanismRenderActors == 4
        && changedPsychicStats.renderIntentHash
            != changedSpecialStats.renderIntentHash
        && changedMagBeamStats.specialMechanismRenderActors == 4
        && changedMagBeamStats.renderIntentHash
            != changedPsychicStats.renderIntentHash
        && staticMagBeamPoseFallbackValid
        && posedMagBeamEndpointsValid
        && posedMagBeamStats.specialMechanismRenderActors == 4
        && posedMagBeamStats.renderIntentHash
            != changedMagBeamStats.renderIntentHash
        && magBeamProgressIsStatusOnly
        && progressOnlyMagBeamStats.specialMechanismRenderActors == 4
        && progressOnlyMagBeamStats.renderIntentHash
            != posedMagBeamStats.renderIntentHash
        && missingSpecialHostStats.specialMechanismRenderActors == 0
        && missingSpecialHostStats.renderIntentHash == 0
        && airstrikeStats.specialMechanismRenderActors == 1
        && firstAirstrikeHash != 0
        && changedAirstrikeStats.specialMechanismRenderActors == 1
        && changedAirstrikeStats.renderIntentHash != firstAirstrikeHash
        && invalidAirstrikeStats.specialMechanismRenderActors == 0
        && invalidAirstrikeStats.renderIntentHash == 0
        && specialCache.auxiliaryEffectKindCacheMisses == 0
        && specialCache.auxiliaryShpFrameCacheMisses == 0;

    RuntimeParticleBeamSnapshot beamSnapshot;
    beamSnapshot.systemInstanceId = 41;
    beamSnapshot.fromWorldX = 0.0;
