    std::vector<RuntimeParticleBeamSnapshot> beamSnapshots{beamSnapshot};
    std::vector<std::uint32_t> beamSurface(81U, basePixel);
    RuntimeMapRenderContext beamContext;
    beamContext.surfacePixels = beamSurface.data();
    beamContext.surfaceWidth = 9;
    beamContext.surfaceHeight = 9;
    beamContext.particleBeamSnapshots = &beamSnapshots;
    RuntimeMapRenderStats beamStats;
    recordRuntimeParticleRenderSnapshots(beamContext, beamStats);
    drawRuntimeParticleBeamSnapshots(
        nullptr,
        viewport,
        beamContext,
        particleCamera,
        beamStats
    );
    const bool beamValid = beamStats.particleBeamSnapshots == 1
        && beamStats.particleBeamsDrawn == 1
        && beamStats.particleSnapshotSignature != 0
        && beamSurface[centerIndex] != basePixel;

    RuntimeLocalLightSnapshot localLight;
    localLight.stableId = 51;
    localLight.worldX = 0.0;
    localLight.worldY = 0.0;
    localLight.radiusPixels = 3;
