void drawRuntimeImpactActors(
    HDC dc,
    const RECT& viewport,
    const GameWorld& world,
    const RuntimeMapRenderContext& context,
    const RuntimeMapCamera& camera,
    RuntimeMapRenderCache& cache,
    RuntimeMapRenderStats& stats,
    bool includeGroundLayerActors
) {
    if (context.impactActors == nullptr || context.impactActors->empty()) {
        return;
    }

    for (const RuntimeImpactRenderActor& actor : *context.impactActors) {
        if (!includeGroundLayerActors
            && runtimeImpactActorUsesGroundLayer(actor)) {
            continue;
        }
        drawRuntimeImpactActor(
            dc,
            viewport,
            world,
            context,
            camera,
            cache,
            actor,
            stats
        );
    }
}

bool runtimeRenderContextHasEffectActors(
    const RuntimeMapRenderContext& context
) {
    return (context.projectileActors != nullptr
            && !context.projectileActors->empty())
        || (context.impactActors != nullptr && !context.impactActors->empty())
        || (context.particleSnapshots != nullptr
            && !context.particleSnapshots->empty());
}

bool runtimeShouldBuildTerrainLayer(
    const RuntimeMapRenderContext& context,
    int viewportWidth,
    int viewportHeight
) {
    if (!context.useTileTextures) {
        return false;
    }
    if (runtimeVisionEnabled(context)) {
        // Shroud correctness depends on the cached layer's per-pixel terrain
        // ownership. Never switch to the ownership-free fallback renderer
        // merely because an effect is active in a small gameplay viewport.
        return true;
    }
    if (!runtimeRenderContextHasEffectActors(context)) {
        return true;
    }

    constexpr int kSmallActorProbePixels = 640 * 480;
    return viewportWidth * viewportHeight >= kSmallActorProbePixels;
}

void populateRuntimeUiResourceStats(
    const RuntimeMapRenderContext& context,
    RuntimeMapRenderStats& stats
) {
    if (context.uiResources == nullptr) {
        stats.uiResourceUnsupported = 1;
        stats.uiPaletteUnsupported = 1;
        stats.uiFormat0Unsupported = 1;
        return;
    }

    stats.uiResourceCandidates = context.uiResources->resourceCandidates;
    stats.uiResourceDecoded = context.uiResources->resourcesDecoded;
    stats.uiResourceMissing = context.uiResources->resourcesMissing;
    stats.uiPaletteCandidates = context.uiResources->paletteCandidates;
    stats.uiPaletteDecoded = context.uiResources->palettesDecoded;
    stats.uiPaletteUnsupported = context.uiResources->palettesUnsupported;
    stats.uiSidebarResourceCandidates =
        context.uiResources->sidebarCandidates;
    stats.uiRadarResourceCandidates = context.uiResources->radarCandidates;
    stats.uiCameoResourceCandidates = context.uiResources->cameoCandidates;
    stats.uiPipResourceCandidates = context.uiResources->pipCandidates;
    stats.uiPowerResourceCandidates = context.uiResources->powerCandidates;
    stats.uiResourceUnsupported =
        stats.uiResourceDecoded > 0 || stats.uiResourceCandidates > 0 ? 0 : 1;
    if (stats.uiPaletteDecoded <= 0 && stats.uiPaletteCandidates <= 0) {
        stats.uiPaletteUnsupported = 1;
    }
    stats.uiFormat0Unsupported =
        stats.uiResourceDecoded > 0 ? 0 : 1;
}

bool resolveRuntimeSpawnedMissileSpriteBounds(
    const WorldObjectInstance& object, const POINT& center,
    const RuntimeMapRenderContext& context, const RuntimeMapCamera& camera,
    RuntimeMapRenderCache& cache, RECT& bounds
) {
    if (context.specialMechanismSnapshots == nullptr) return false;
    for (const auto& snapshot : *context.specialMechanismSnapshots) {
        if (snapshot.kind != "spawnedMissile" || snapshot.objectId != object.instanceId) continue;
        const auto* voxel = loadRuntimeVoxelImageFromCache(snapshot.resourceId,
            snapshot.resourceId + "|missile",
            facingBucketForFacingValue(snapshot.missileFacing, runtimeVoxelFacingBucketCount),
            context, cache, 0.0, 0, 0,
            static_cast<int>(std::lround(snapshot.missilePitch * 90.0 / 3.141592653589793)));
        if (voxel == nullptr || !voxel->hasSprite) return false;
        const auto& image = voxel->image;
        int left = image.width, top = image.height, right = -1, bottom = -1;
        for (int y = 0; y < image.height; ++y) for (int x = 0; x < image.width; ++x) {
            const auto index = static_cast<std::size_t>(y) * image.width + x;
            if (index < image.pixels.size() && image.pixels[index] != 0) {
                left = std::min(left, x); top = std::min(top, y);
                right = std::max(right, x); bottom = std::max(bottom, y);
            }
        }
        if (right < left || bottom < top) return false;
        const auto imageBounds = runtimeShpFrameScreenRect(center, camera, image);
        bounds = {imageBounds.left + left, imageBounds.top + top,
            imageBounds.left + right + 1, imageBounds.top + bottom + 1};
        return true;
    }
    return false;
}
#include "render/geometry/RuntimeMobileSpriteGeometry.inl"

bool resolveRuntimeObjectShpSpriteBounds(
    const WorldObjectInstance& object,
    const POINT& center,
    const RuntimeMapRenderContext& context,
    const RuntimeMapCamera& camera,
    RuntimeMapRenderCache& cache,
    RECT& spriteRect,
    bool stableGlobalCanvas
) {
    spriteRect = RECT{0, 0, 0, 0};
    if (const auto* disguise = runtimeCamouflageSnapshot(context, object, nullptr, true)) {
        if (const auto* image = loadRuntimeAuxiliaryTmpImage(context, cache, disguise->resourceId, 0)) {
            spriteRect = runtimeTmpImageScreenRect(center, camera, *image);
            return spriteRect.right > spriteRect.left && spriteRect.bottom > spriteRect.top;
        }
        const auto* sprite = loadRuntimeAuxiliaryShpSpriteFromCache(disguise->resourceId, 0, context, cache, true);
        if (sprite != nullptr && sprite->loaded) {
            spriteRect = runtimeShpFrameScreenRect(runtimeAuxiliaryShpAdjustedCenter(center, camera, sprite->image, 0, 0, true), camera, sprite->image);
            return spriteRect.right > spriteRect.left && spriteRect.bottom > spriteRect.top;
        }
        return false;
    }
    RuntimeObjectShpSpriteCacheEntry* sprite =
        loadRuntimeObjectShpSpriteFromCache(object, context, cache);
    if (sprite == nullptr || !sprite->loaded) {
        return false;
    }

    POINT spriteCenter = runtimeAuxiliaryShpAdjustedCenter(
        center,
        camera,
        sprite->image,
        0,
        0,
        object.kind == WorldObjectKind::Structure
    );
    spriteCenter.y += runtimeUnderwaterShpAlignmentOffsetY(
        object,
        context,
        camera,
        sprite->image
    );
    if (stableGlobalCanvas) {
        // Underwater SHP units such as SQD and DLPH have strongly varying
        // per-facing frame rectangles. Their selection box is an object
        // envelope, not a frame crop, so anchor the authored global canvas
        // at the same authored origin when hidden or revealed.
        spriteRect = runtimeShpFrameGlobalScreenRect(
            spriteCenter,
            camera,
            sprite->image
        );
    } else {
        spriteRect = runtimeShpFrameScreenRect(
            spriteCenter,
            camera,
            sprite->image
        );
    }
    return spriteRect.right > spriteRect.left
        && spriteRect.bottom > spriteRect.top;
}
bool resolveRuntimeInfantryDeathCanvasPivotOffsets(
    const WorldObjectInstance& object,
    const RuntimeMapRenderContext& context,
    RuntimeMapRenderCache& cache,
    int& screenX, int& screenY, int& fixedX, int& fixedY
) {
    if (object.kind != WorldObjectKind::Infantry || context.rules == nullptr
        || context.art == nullptr
        || context.rules->findUnitType("InfantryType", object.type) == nullptr) {
        return false;
    }
    RuntimeRendererEnvironmentScope environment;
    auto canonical = context;
    canonical.specialMechanismSnapshots = nullptr;
    canonical.selectedObjectIds = nullptr;
    canonical.playerCheerUntilTick = nullptr;
    canonical.vision = nullptr;
    canonical.visionObserverOwner.clear();
    canonical.surfacePixels = nullptr;
    canonical.surfaceWidth = canonical.surfaceHeight = 0;
    canonical.surfaceTopDownOwned = false;
    WorldObjectInstance source = object;
    source.alive = true;
    source.health = std::max(1, source.health);
    const ArtType* art = findArtTypeForObject(source, canonical);
    if (art == nullptr || art->voxel) return false;

    RuntimeMapCamera camera;
    camera.initialized = true;
    const POINT origin{0, 0};
    RECT reference{}, doubled{};
    if (!resolveRuntimeObjectShpSpriteBounds(source, origin, canonical, camera,
            cache, reference, true)) return false;
    camera.tileWidth = 120;
    camera.tileHeight = 60;
    if (!resolveRuntimeObjectShpSpriteBounds(source, origin, canonical, camera,
            cache, doubled, true)) return false;
    const auto midpoint = [](LONG first, LONG last) {
        // Match the original integer half-canvas pivot for odd dimensions,
        // including a negative top/left in this origin-relative query.
        return static_cast<long long>(first)
            + (static_cast<long long>(last) - first) / 2;
    };
    const long long referenceX = midpoint(reference.left, reference.right);
    const long long referenceY = midpoint(reference.top, reference.bottom);
    const long long fixedOffsetX = 2 * referenceX - midpoint(doubled.left, doubled.right);
    const long long fixedOffsetY = 2 * referenceY - midpoint(doubled.top, doubled.bottom);
    // These values share the existing persisted impact presentation bounds.
    for (long long value : {referenceX, referenceY, fixedOffsetX, fixedOffsetY}) {
        if (value < -4096 || value > 4096) return false;
    }
    screenX = static_cast<int>(referenceX);
    screenY = static_cast<int>(referenceY);
    fixedX = static_cast<int>(fixedOffsetX);
    fixedY = static_cast<int>(fixedOffsetY);
    return true;
}
