bool drawRuntimeObjectPreviewSprite(
    HDC dc,
    const RECT& viewport,
    const WorldObjectInstance& object,
    const RuntimeMapRenderContext& context,
    const RuntimeMapCamera& camera,
    RuntimeMapRenderCache& cache,
    RECT* spriteRect
) {
    const RuntimeFootprintDimensions footprint =
        runtimeObjectFoundationDimensions(object, context);
    const ProjectedPoint drawPoint =
        runtimeObjectDrawPoint(object, footprint, camera);
    const POINT center = screenPoint(drawPoint, viewport, camera);
    if (object.kind != WorldObjectKind::Structure) {
        return tryDrawObjectShpSprite(
            dc,
            viewport,
            object,
            center,
            context,
            camera,
            cache,
            nullptr,
            spriteRect
        );
    }

    return drawRuntimeStructureGeometryBody(dc, viewport, object, center,
        context, camera, cache, spriteRect);
}

void applyRuntimeVisionOverlay(
    HDC dc,
    const RECT& viewport,
    const GameWorld& world,
    const RuntimeMapRenderContext& context,
    const RuntimeMapCamera& camera,
    RuntimeMapRenderCache& cache,
    RuntimeMapRenderStats& stats
) {
    if (!runtimeVisionEnabled(context)) {
        return;
    }

    const bool directPixels = hasPixelSurface(context);
    if (directPixels) {
        // GDI and direct DIB writes share this surface. Flush the queued map
        // draw before the final shroud compositor reads and shades its pixels.
        GdiFlush();
    }

    RuntimeVisionGridView visionGrid;
    const bool gridAvailable = context.vision->gridViewFor(
        context.visionObserverOwner,
        visionGrid
    );
    RuntimeVisionOverlayCache& overlayCache = cache.visionOverlay;
    const std::vector<TerrainCell>& terrainCells = world.getTerrainCells();
    const TerrainCell* terrainData = terrainCells.empty()
        ? nullptr
        : terrainCells.data();
    const RuntimeTerrainLayerCache& terrainLayer = cache.terrainLayer;
    const std::int32_t* terrainLayerCellData =
        terrainLayer.terrainCellIndices.empty()
            ? nullptr
            : terrainLayer.terrainCellIndices.data();
    const std::size_t surfacePixelCount = directPixels
        ? static_cast<std::size_t>(context.surfaceWidth)
            * static_cast<std::size_t>(context.surfaceHeight)
        : 0U;
    const bool buildOverlayCache = directPixels
        && gridAvailable
        && surfacePixelCount
            <= static_cast<std::size_t>(
                std::numeric_limits<std::uint32_t>::max()
            );
    const bool useNativeShroud = buildOverlayCache && runtimeLoadNativeShroud(context, cache);
    const std::uint64_t shroudFingerprint = useNativeShroud ? cache.nativeShroudAtlas.fingerprint : 0;
    const bool useIncrementalOverlay = buildOverlayCache
        && !runtimeMovementReferenceForRender()
        && !runtimeFrameScalingReferenceForRender();
    const bool shroudPerformanceReference = runtimeShroudPerformanceReference();
    const bool cacheIdentityMatches = buildOverlayCache
        && overlayCache.valid
        && overlayCache.performanceReference == shroudPerformanceReference
        && overlayCache.nativeShroudFingerprint == shroudFingerprint
        && (useIncrementalOverlay || !overlayCache.incremental.valid)
        && overlayCache.vision == context.vision
        && overlayCache.visionLayoutEpoch == visionGrid.layoutEpoch
        && overlayCache.visibleCells == visionGrid.visibleCells
        && overlayCache.exploredCells == visionGrid.exploredCells
        && overlayCache.gapShroudedCells == visionGrid.gapShroudedCells
        && overlayCache.observerOwner == context.visionObserverOwner
        && overlayCache.terrainData == terrainData
        && overlayCache.terrainCount == terrainCells.size()
        && overlayCache.terrainLayerBuilt == terrainLayer.built
        && overlayCache.terrainLayerKey == terrainLayer.key
        && overlayCache.terrainLayerCellData == terrainLayerCellData
        && overlayCache.terrainLayerCellCount
            == terrainLayer.terrainCellIndices.size()
        && overlayCache.terrainLayerWidth == terrainLayer.width
        && overlayCache.terrainLayerHeight == terrainLayer.height
        && overlayCache.terrainLayerOriginX == terrainLayer.originX
        && overlayCache.terrainLayerOriginY == terrainLayer.originY
        && overlayCache.viewportLeft == viewport.left
        && overlayCache.viewportTop == viewport.top
        && overlayCache.viewportRight == viewport.right
        && overlayCache.viewportBottom == viewport.bottom
        && overlayCache.surfaceWidth == context.surfaceWidth
        && overlayCache.surfaceHeight == context.surfaceHeight
        && overlayCache.worldOffsetX == camera.worldOffsetX
        && overlayCache.worldOffsetY == camera.worldOffsetY
        && overlayCache.tileWidth == camera.tileWidth
        && overlayCache.tileHeight == camera.tileHeight;

    const bool sameVisionRevision = overlayCache.visionRevision == visionGrid.revision;
    if (cacheIdentityMatches && useIncrementalOverlay && overlayCache.incremental.valid
        && overlayCache.shroudedCellMask.size() == visionGrid.cellCount) {
        bool changed = false;
        if (!sameVisionRevision) {
            changed = useNativeShroud
                ? runtimeUpdateNativeShroudOverlay(overlayCache, visionGrid, terrainLayer,
                    cache.nativeShroudAtlas, viewport, camera, context.surfaceWidth)
                : runtimeUpdateIncrementalVisionOverlay(overlayCache, visionGrid,
                    terrainLayer, viewport, camera, context.surfaceWidth);
            refreshRuntimeVisionOverlayCounts(overlayCache, visionGrid);
            overlayCache.visionRevision = visionGrid.revision;
        }
        if (changed) {
            ++overlayCache.misses;
            ++stats.visionOverlayCacheMisses;
        } else {
            ++overlayCache.hits;
            ++stats.visionOverlayCacheHits;
        }
        stats.visionVisibleCells += overlayCache.visibleCellCount;
        stats.visionFoggedCells += overlayCache.foggedCellCount;
        stats.visionShroudedCells += overlayCache.shroudedCellCount;
        stats.visionOverlayPixels += static_cast<int>(overlayCache.incremental.encodedPixelCount);
        for (const auto& tile : overlayCache.incremental.tiles)
            runtimeApplyVisionTilePixels(tile, context.surfacePixels, stats, shroudPerformanceReference);
        return;
    }
    const bool cacheMatches = cacheIdentityMatches
        && (sameVisionRevision || (!runtimeMovementReferenceForRender()
            && runtimeVisionOverlayShroudMatches(overlayCache, visionGrid)));

    const auto applyEncodedOverlay = [&]() {
        for (const std::uint64_t encoded : overlayCache.encodedPixels) {
            const std::uint32_t offset = static_cast<std::uint32_t>(
                encoded >> 32U
            );
            const std::uint32_t effect = static_cast<std::uint32_t>(encoded);
            const int alpha = static_cast<int>(effect >> 24U);
            const std::uint32_t tint = effect & 0x00ffffffU;
            std::uint32_t& target = context.surfacePixels[offset];
            if (alpha >= 255) {
                target = tint;
                continue;
            }

            const int keep = 255 - alpha;
            const auto blendChannel = [keep, alpha](
                std::uint32_t source,
                std::uint32_t overlay
            ) {
                return ((source * static_cast<std::uint32_t>(keep))
                    + (overlay * static_cast<std::uint32_t>(alpha))
                    + 127U) / 255U;
            };
            target =
                (blendChannel(
                    (target >> 16U) & 0xffU,
                    (tint >> 16U) & 0xffU
                ) << 16U)
                | (blendChannel(
                    (target >> 8U) & 0xffU,
                    (tint >> 8U) & 0xffU
                ) << 8U)
                | blendChannel(target & 0xffU, tint & 0xffU);
        }
    };

    if (cacheMatches) {
        if (!sameVisionRevision) {
            // Current sight moved inside explored terrain. It changes the
            // diagnostic counts, but every compositor pixel remains identical.
            refreshRuntimeVisionOverlayCounts(overlayCache, visionGrid);
            overlayCache.visionRevision = visionGrid.revision;
        }
        ++overlayCache.hits;
        ++stats.visionOverlayCacheHits;
        stats.visionVisibleCells += overlayCache.visibleCellCount;
        stats.visionFoggedCells += overlayCache.foggedCellCount;
        stats.visionShroudedCells += overlayCache.shroudedCellCount;
        stats.visionOverlayPixels += static_cast<int>(
            overlayCache.encodedPixels.size()
        );
        applyEncodedOverlay();
        return;
    }

    overlayCache.valid = false;
    overlayCache.performanceReference = shroudPerformanceReference;
    overlayCache.nativeShroudFingerprint = shroudFingerprint;
    overlayCache.incremental = {};
    overlayCache.encodedPixels.clear();
    overlayCache.shroudedCellMask.clear();
    overlayCache.viewportTerrainCellIndices.clear();
    if (buildOverlayCache) {
        ++overlayCache.misses;
        ++stats.visionOverlayCacheMisses;
        overlayCache.vision = context.vision;
        overlayCache.visionRevision = visionGrid.revision;
        overlayCache.visionLayoutEpoch = visionGrid.layoutEpoch;
        overlayCache.visibleCells = visionGrid.visibleCells;
        overlayCache.exploredCells = visionGrid.exploredCells;
        overlayCache.gapShroudedCells = visionGrid.gapShroudedCells;
        overlayCache.observerOwner = context.visionObserverOwner;
        overlayCache.terrainData = terrainData;
        overlayCache.terrainCount = terrainCells.size();
        overlayCache.terrainLayerBuilt = terrainLayer.built;
        overlayCache.terrainLayerKey = terrainLayer.key;
        overlayCache.terrainLayerCellData = terrainLayerCellData;
        overlayCache.terrainLayerCellCount =
            terrainLayer.terrainCellIndices.size();
        overlayCache.terrainLayerWidth = terrainLayer.width;
        overlayCache.terrainLayerHeight = terrainLayer.height;
        overlayCache.terrainLayerOriginX = terrainLayer.originX;
        overlayCache.terrainLayerOriginY = terrainLayer.originY;
        overlayCache.viewportLeft = viewport.left;
        overlayCache.viewportTop = viewport.top;
        overlayCache.viewportRight = viewport.right;
        overlayCache.viewportBottom = viewport.bottom;
        overlayCache.surfaceWidth = context.surfaceWidth;
        overlayCache.surfaceHeight = context.surfaceHeight;
        overlayCache.worldOffsetX = camera.worldOffsetX;
        overlayCache.worldOffsetY = camera.worldOffsetY;
        overlayCache.tileWidth = camera.tileWidth;
        overlayCache.tileHeight = camera.tileHeight;
        if (!runtimeMovementReferenceForRender()
            && (!useNativeShroud || shroudPerformanceReference
                || runtimeFrameScalingReferenceForRender()
                || std::max(0, static_cast<int>(viewport.left))
                    >= std::min(context.surfaceWidth, static_cast<int>(viewport.right))
                || std::max(0, static_cast<int>(viewport.top))
                    >= std::min(context.surfaceHeight, static_cast<int>(viewport.bottom))))
            captureRuntimeVisionOverlayShroud(overlayCache, visionGrid);
    }

    const auto finishOverlayCache = [&]() {
        if (!buildOverlayCache) {
            return;
        }
        overlayCache.visibleCellCount = stats.visionVisibleCells;
        overlayCache.foggedCellCount = stats.visionFoggedCells;
        overlayCache.shroudedCellCount = stats.visionShroudedCells;
        overlayCache.valid = true;
    };

    if (useNativeShroud) {
        runtimeBuildNativeShroudOverlay(overlayCache, visionGrid, terrainLayer,
            cache.nativeShroudAtlas, world, viewport, camera,
            context.surfaceWidth, context.surfaceHeight, stats);
        stats.visionOverlayPixels += static_cast<int>(overlayCache.incremental.encodedPixelCount);
        for (const auto& tile : overlayCache.incremental.tiles) {
            runtimeApplyVisionTilePixels(tile, context.surfacePixels, stats, shroudPerformanceReference);
            if (!useIncrementalOverlay) overlayCache.encodedPixels.insert(
                overlayCache.encodedPixels.end(), tile.encodedPixels.begin(), tile.encodedPixels.end());
        }
        if (!useIncrementalOverlay) overlayCache.incremental = {};
        finishOverlayCache();
        return;
    }

    const int halfWidth = std::max(1, camera.tileWidth / 2);
    const int halfHeight = std::max(1, camera.tileHeight / 2);
    constexpr unsigned char geometricShroudMarker = 254;
    constexpr unsigned char terrainOwnedShroudMarker = 255;
    static thread_local std::vector<unsigned char> shroudMask;
    static thread_local std::vector<unsigned char> horizontalBlur;
    static thread_local std::vector<unsigned char> softenedShroud;
    static thread_local std::vector<unsigned char> cellVisionStates;
    if (directPixels) {
        shroudMask.assign(surfacePixelCount, 0);
    }
    constexpr std::size_t visionCellCount = 512U * 512U;
    if (!gridAvailable) {
        cellVisionStates.assign(visionCellCount, 0);
    }
    bool hasShroudedPixels = false;

    for (const TerrainCell& cell : terrainCells) {
        const ProjectedPoint projected = projectCell(cell, camera);
        const POINT center = screenPoint(projected, viewport, camera);
        const RECT diamondBounds{
            center.x - halfWidth,
            center.y - halfHeight,
            center.x + halfWidth + 1,
            center.y + halfHeight + 1
        };
        if (!rectIntersects(diamondBounds, viewport)) {
            continue;
        }

        const int terrainCellIndex = cell.cellIndex512 >= 0
            ? cell.cellIndex512
            : ((cell.x >= 0 && cell.y >= 0 && cell.x < 512 && cell.y < 512)
                ? (cell.y * 512) + cell.x
                : -1);
        if (buildOverlayCache && !runtimeMovementReferenceForRender())
            overlayCache.viewportTerrainCellIndices.push_back(terrainCellIndex);
        const RuntimeCellVisibility visibility = gridAvailable
            ? visionGrid.visibilityAtIndex(terrainCellIndex)
            : context.vision->visibilityFor(
                context.visionObserverOwner,
                cell.x,
                cell.y
            );
        if (!gridAvailable
            && terrainCellIndex >= 0
            && static_cast<std::size_t>(terrainCellIndex)
                < cellVisionStates.size()) {
            cellVisionStates[static_cast<std::size_t>(terrainCellIndex)] =
                visibility == RuntimeCellVisibility::Shrouded ? 2 : 1;
        }

        if (visibility == RuntimeCellVisibility::Visible) {
            ++stats.visionVisibleCells;
            continue;
        }
        if (visibility == RuntimeCellVisibility::Fogged) {
            ++stats.visionFoggedCells;
            // Exploration is one-shot: terrain that has been seen once keeps
            // its authored brightness and continues showing live enemy
            // objects, projectiles, and effects after nearby scouts leave.
            continue;
        }
        ++stats.visionShroudedCells;

        if (!directPixels) {
            // Legacy DCs cannot use the feathered alpha mask below. Keep a
            // cool near-black instead of the former featureless pure fill.
            const int variation = ((cell.x * 13) ^ (cell.y * 7)) & 3;
            const COLORREF fill = RGB(
                6 + variation,
                10 + variation,
                16 + variation
            );
            drawDiamond(
                dc,
                center,
                camera.tileWidth,
                camera.tileHeight,
                fill,
                fill
            );
            continue;
        }

        for (int dy = -halfHeight; dy <= halfHeight; ++dy) {
            const int y = center.y + dy;
            if (y < viewport.top || y >= viewport.bottom
                || y < 0 || y >= context.surfaceHeight) {
                continue;
            }
            const int remaining = halfHeight - std::abs(dy);
            const int xExtent = (halfWidth * remaining + halfHeight - 1)
                / halfHeight;
            const int left = std::max(
                {static_cast<int>(center.x) - xExtent,
                    static_cast<int>(viewport.left), 0}
            );
            const int right = std::min(
                {static_cast<int>(center.x) + xExtent,
                    static_cast<int>(viewport.right) - 1,
                    context.surfaceWidth - 1}
            );
            if (!runtimeMovementReferenceForRender() && left <= right) {
                auto first = shroudMask.begin() + static_cast<std::size_t>(y)
                    * static_cast<std::size_t>(context.surfaceWidth) + left;
                std::fill(first, first + (right - left + 1), geometricShroudMarker);
                hasShroudedPixels = true;
                continue;
            }
            for (int x = left; x <= right; ++x) {
                const std::size_t offset =
                    (static_cast<std::size_t>(y)
                        * static_cast<std::size_t>(context.surfaceWidth))
                    + static_cast<std::size_t>(x);
                shroudMask[offset] = std::max(
                    shroudMask[offset],
                    geometricShroudMarker
                );
                hasShroudedPixels = true;
            }
        }
    }

    // The base-diamond mask above defines the soft strategic fog boundary.
    // Add every opaque TMP pixel owned by a shrouded cell so cliff lips,
    // ramps, and other authored extensions cannot leak through as bright,
    // disconnected strips inside an otherwise unexplored region.
    // The fallback cache is intentionally empty on the normal fast-grid
    // path. Validate terrain ownership against the grid that will actually
    // answer the lookup, otherwise every TMP extension is skipped.
    const std::size_t visibilityCellCount = gridAvailable
        ? visionGrid.cellCount
        : cellVisionStates.size();
    if (directPixels
        && terrainLayer.built
        && terrainLayer.width > 0
        && terrainLayer.height > 0
        && terrainLayer.terrainCellIndices.size()
            == terrainLayer.pixels.size()) {
        const int layerScreenX =
            static_cast<int>(viewport.left)
            + terrainLayer.originX
            - camera.worldOffsetX;
        const int layerScreenY =
            static_cast<int>(viewport.top)
            + terrainLayer.originY
            - camera.worldOffsetY;
        const int left = std::max(
            {0, static_cast<int>(viewport.left), layerScreenX}
        );
        const int top = std::max(
            {0, static_cast<int>(viewport.top), layerScreenY}
        );
        const int right = std::min(
            {context.surfaceWidth,
                static_cast<int>(viewport.right),
                layerScreenX + terrainLayer.width}
        );
        const int bottom = std::min(
            {context.surfaceHeight,
                static_cast<int>(viewport.bottom),
                layerScreenY + terrainLayer.height}
        );
        for (int y = top; y < bottom; ++y) {
            const int layerY = y - layerScreenY;
            for (int x = left; x < right; ++x) {
                const int layerX = x - layerScreenX;
                const std::size_t layerOffset =
                    (static_cast<std::size_t>(layerY)
                        * static_cast<std::size_t>(terrainLayer.width))
                    + static_cast<std::size_t>(layerX);
                const std::size_t surfaceOffset =
                    (static_cast<std::size_t>(y)
                        * static_cast<std::size_t>(context.surfaceWidth))
                    + static_cast<std::size_t>(x);
                // A TMP overhang can overlap the feathered tip of a geometric
                // diamond.  Keep inspecting those pixels so shrouded terrain
                // upgrades the translucent marker to an opaque one.
                if (shroudMask[surfaceOffset]
                    == terrainOwnedShroudMarker) {
                    continue;
                }
                const int sourceCellIndex =
                    terrainLayer.terrainCellIndices[layerOffset];
                if (sourceCellIndex < 0
                    || static_cast<std::size_t>(sourceCellIndex)
                        >= visibilityCellCount) {
                    continue;
                }
                bool sourceShrouded = false;
                if (buildOverlayCache && !runtimeMovementReferenceForRender()) {
                    sourceShrouded = overlayCache.shroudedCellMask[static_cast<std::size_t>(sourceCellIndex)] != 0;
                } else if (gridAvailable) {
                    sourceShrouded = visionGrid.visibilityAtIndex(
                        sourceCellIndex
                    ) == RuntimeCellVisibility::Shrouded;
                } else {
                    unsigned char& sourceVisionState = cellVisionStates[
                        static_cast<std::size_t>(sourceCellIndex)
                    ];
                    if (sourceVisionState == 0) {
                        const RuntimeCellVisibility sourceVisibility =
                            context.vision->visibilityFor(
                                context.visionObserverOwner,
                                sourceCellIndex % 512,
                                sourceCellIndex / 512
                            );
                        sourceVisionState =
                            sourceVisibility == RuntimeCellVisibility::Shrouded
                                ? 2
                                : 1;
                    }
                    sourceShrouded = sourceVisionState == 2;
                }
                if (!sourceShrouded) {
                    continue;
                }
                shroudMask[surfaceOffset] = terrainOwnedShroudMarker;
                hasShroudedPixels = true;
            }
        }
    }

    if (useIncrementalOverlay && runtimeBuildIncrementalVisionOverlay(overlayCache,
            visionGrid, terrainLayer, world, viewport, camera,
            context.surfaceWidth, context.surfaceHeight, shroudMask)) {
        stats.visionOverlayPixels += static_cast<int>(overlayCache.incremental.encodedPixelCount);
        for (const auto& tile : overlayCache.incremental.tiles)
            runtimeApplyVisionTilePixels(tile, context.surfacePixels, stats, shroudPerformanceReference);
        finishOverlayCache();
        return;
    }

    if (!directPixels || !hasShroudedPixels) {
        finishOverlayCache();
        return;
    }

    const int clipLeft = std::max(0, static_cast<int>(viewport.left));
    const int clipTop = std::max(0, static_cast<int>(viewport.top));
    const int clipRight = std::min(
        context.surfaceWidth,
        static_cast<int>(viewport.right)
    );
    const int clipBottom = std::min(
        context.surfaceHeight,
        static_cast<int>(viewport.bottom)
    );
    if (clipLeft >= clipRight || clipTop >= clipBottom) {
        finishOverlayCache();
        return;
    }

    if (buildOverlayCache) {
        const std::size_t clippedPixelCount =
            static_cast<std::size_t>(clipRight - clipLeft)
            * static_cast<std::size_t>(clipBottom - clipTop);
        if (overlayCache.encodedPixels.capacity() < clippedPixelCount) {
            overlayCache.encodedPixels.reserve(clippedPixelCount);
        }
    }

    if (runtimeMovementReferenceForRender()) {
        horizontalBlur.resize(surfacePixelCount);
        softenedShroud.resize(surfacePixelCount);
    // A separable box blur softens only the inside of the unexplored region.
    // The original mask remains available below so no shade spills back onto
    // terrain that the player has already explored.
    runtimeSoftenShroudHorizontally(
        shroudMask,
        horizontalBlur,
        context.surfaceWidth,
        clipLeft,
        clipTop,
        clipRight,
        clipBottom
    );
    runtimeSoftenShroudVertically(
        horizontalBlur,
        softenedShroud,
        context.surfaceWidth,
        clipLeft,
        clipTop,
        clipRight,
        clipBottom
    );
    } else {
        runtimeSoftenGeometricShroud(shroudMask, horizontalBlur, softenedShroud,
            context.surfaceWidth, clipLeft, clipTop, clipRight, clipBottom);
        const auto& colors = runtimeVisionShroudColors();
        for (int y = clipTop; y < clipBottom; ++y) {
            const std::size_t row = static_cast<std::size_t>(y) * context.surfaceWidth;
            const int worldY = (y - static_cast<int>(viewport.top) + camera.worldOffsetY) & 127;
            const auto* colorRow = colors.data() + static_cast<std::size_t>(worldY) * 64;
            for (int x = clipLeft; x < clipRight; ++x) {
                const std::size_t offset = row + x;
                const unsigned char marker = shroudMask[offset];
                if (marker == 0) continue;
                const bool solid = marker == terrainOwnedShroudMarker || softenedShroud[offset] >= 220;
                const int worldX = (x - static_cast<int>(viewport.left) + camera.worldOffsetX) & 63;
                const auto& color = colorRow[worldX];
                const int opacity = solid ? 255 : std::clamp(static_cast<int>(softenedShroud[offset]) + color.mottle, 0, 250);
                auto& pixel = context.surfacePixels[offset];
                pixel = solid ? color.color : runtimeBlendVisionShroud(pixel, color.color, opacity);
                ++stats.visionOverlayPixels;
                if (buildOverlayCache) {
                    const std::uint32_t effect = (static_cast<std::uint32_t>(opacity) << 24U) | color.color;
                    overlayCache.encodedPixels.push_back((static_cast<std::uint64_t>(offset) << 32U) | effect);
                }
            }
        }
        finishOverlayCache();
        return;
    }

    for (int y = clipTop; y < clipBottom; ++y) {
        for (int x = clipLeft; x < clipRight; ++x) {
            const std::size_t offset =
                (static_cast<std::size_t>(y)
                    * static_cast<std::size_t>(context.surfaceWidth))
                + static_cast<std::size_t>(x);
            if (shroudMask[offset] == 0) {
                continue;
            }

            // Two broad triangular waves give the dark layer a restrained,
            // camera-stable mottle without making the fog visibly noisy.
            const int worldPixelX =
                x - static_cast<int>(viewport.left) + camera.worldOffsetX;
            const int worldPixelY =
                y - static_cast<int>(viewport.top) + camera.worldOffsetY;
            const int waveA = 16 - std::abs(
                ((worldPixelX + (worldPixelY * 2)) & 63) - 32
            );
            const int waveB = 32 - std::abs(
                (((worldPixelX * 2) - worldPixelY) & 127) - 64
            );
            const int mottle = (waveA / 4) + (waveB / 8);
            const int opacity = std::clamp(
                static_cast<int>(softenedShroud[offset]) + mottle,
                0,
                250
            );
            const int coolLift = std::clamp((mottle + 8) / 6, 0, 2);
            const COLORREF fogColor = RGB(
                3 + coolLift,
                6 + coolLift,
                10 + coolLift
            );
            const bool solidFog =
                shroudMask[offset] == terrainOwnedShroudMarker
                || (shroudMask[offset] == geometricShroudMarker
                    && softenedShroud[offset] >= 220);
            const std::uint32_t packedFogColor =
                packRuntimeDibColor(fogColor);
            const bool written =
                solidFog
                    // Unexplored terrain must not leak map information. The
                    // subtle variation now belongs to the fog colour itself,
                    // rather than coming from the terrain underneath it.
                    ? putSurfacePixel(
                        context,
                        x,
                        y,
                        packedFogColor
                    )
                    : blendSurfacePixelWithTint(
                        context,
                        x,
                        y,
                        fogColor,
                        opacity
                    );
            if (written) {
                ++stats.visionOverlayPixels;
                if (buildOverlayCache) {
                    const std::uint32_t encodedEffect =
                        (static_cast<std::uint32_t>(
                            solidFog ? 255 : opacity
                        ) << 24U)
                        | packedFogColor;
                    overlayCache.encodedPixels.push_back(
                        (static_cast<std::uint64_t>(
                            static_cast<std::uint32_t>(offset)
                        ) << 32U)
                        | static_cast<std::uint64_t>(encodedEffect)
                    );
                }
            }
        }
    }
    finishOverlayCache();
}

RuntimeMapRenderStats drawRuntimeMap(
    HDC dc,
    const RECT& viewport,
    const GameWorld& world,
    const RuntimeMapRenderContext& context,
    RuntimeMapCamera& camera,
    RuntimeMapRenderCache& cache
) {
    RuntimeRendererEnvironmentScope environmentScope;
    const bool groundShadowEligibilityReference = runtimeGroundShadowEligibilityReferenceForRender();
    const bool terrainViewportFillReference = runtimeTerrainViewportFillReferenceForRender();
    const bool stageTrace = runtimeRendererEnvironmentValue("CONCORD_RENDER_STAGE_TRACE")
        != nullptr;
    const auto traceStage = [stageTrace](const char* stage) {
        if (stageTrace) {
            std::cerr << "Renderer stage: " << stage << std::endl;
        }
    };
    traceStage("enter");
    RuntimeMapRenderStats stats;
    const bool detailedTiming = runtimeRenderDetailDiagnosticsEnabled(context);
    const bool stageTiming = context.coarseStageTimingEnabled || detailedTiming;
    stats.detailStatsEnabled = context.detailStatsEnabled || detailedTiming;
    stats.coarseStageTimingEnabled = stageTiming;
    populateRuntimeUiResourceStats(context, stats);
    stats.mapFactsAvailable = context.mapFacts == nullptr ? 0 : 1;
    cache.projectileEffectMs = 0.0;
    cache.auxiliaryShpBytesCacheMissMs = 0.0;
    cache.auxiliaryShpFrameCacheMissMs = 0.0;
    cache.lastBuildingDepthTimingEnabled = false;
    cache.lastBuildingDepthTemplateMs = cache.lastBuildingDepthInitializeMs = 0.0;
    cache.lastBuildingDepthGatherMs = cache.lastBuildingDepthBodyCollectMs = 0.0;
    cache.lastBuildingDepthMobileCollectMs = cache.lastBuildingDepthSortMs = 0.0;
    cache.lastBuildingDepthRasterMs = cache.lastBuildingDepthBlendMs = cache.lastBuildingDepthTotalMs = 0.0;
    cache.lastBuildingDepthRequestedPixels = cache.lastBuildingDepthBufferPixels = 0;
    cache.lastBuildingDepthBufferCapacityBytes = 0;
    const int viewportWidth = viewport.right - viewport.left;
    const int viewportHeight = viewport.bottom - viewport.top;
    if (viewportWidth <= 0 || viewportHeight <= 0 || !world.getSummary().loaded) {
        return stats;
    }
    const std::string resourceOverlayPlanSignature =
        runtimeResourceOverlayPlanCacheSignature(context);
    if (cache.resourceOverlayPlanCacheSignature
        != resourceOverlayPlanSignature) {
        cache.resourceOverlayPlanCacheSignature =
            resourceOverlayPlanSignature;
        cache.resourceOverlayTmpImageByIdentity.clear();
    }

    if (!camera.initialized) {
        initializeRuntimeMapCamera(camera, world, viewportWidth, viewportHeight);
    }
    RuntimeGeometryQueryScope geometryBatch(world, viewport, context, camera, cache);
    recordRuntimeParticleRenderSnapshots(context, stats);

    const HGDIOBJ oldBrush = SelectObject(dc, GetStockObject(DC_BRUSH));
    const HGDIOBJ oldPen = SelectObject(dc, GetStockObject(DC_PEN));

    SetDCBrushColor(dc, RGB(15, 22, 31));
    const bool immediateViewportFill = context.effectOnlyProbe || terrainViewportFillReference;
    if (immediateViewportFill) {
        RuntimePerfTraceScope fillTrace("map.terrainViewportFill", context.animationTick);
        FillRect(dc, &viewport, static_cast<HBRUSH>(GetStockObject(DC_BRUSH)));
        runtimeCountTerrainViewportFill(cache.terrainViewportFillCalls);
        if (runtimeTerrainViewportFillObservation) ++runtimeTerrainViewportFillObservation->fills;
    }
    if (context.effectOnlyProbe) {
        drawRuntimeProjectileActors(
            dc,
            viewport,
            context,
            camera,
            cache,
            stats,
            &world
        );
        drawRuntimeImpactActors(
            dc,
            viewport,
            world,
            context,
            camera,
            cache,
            stats,
            true
        );
        drawRuntimeParticleBeamSnapshots(
            dc,
            viewport,
            context,
            camera,
            stats
        );
        drawRuntimeParticleSnapshots(
            dc,
            viewport,
            context,
            camera,
            cache,
            stats
        );
        const auto lightingStart = runtimeMaybeTimingStart(stageTiming);
        stats.lightingTintedPixels = applyRuntimeLightingTintToViewport(
            dc,
            viewport,
            context
        );
        stats.lightingTintApplied = stats.lightingTintedPixels > 0;
        stats.lightingMs = runtimeMaybeElapsedMs(stageTiming, lightingStart);
        const auto localLightStart = runtimeMaybeTimingStart(stageTiming);
        (void)applyRuntimeLocalLightsToViewport(
            dc,
            viewport,
            context,
            camera,
            stats
        );
        stats.localLightMs = runtimeMaybeElapsedMs(stageTiming, localLightStart);
        stats.projectileShpAttempts = cache.projectileShpAttempts;
        stats.projectileShpDrawn = cache.projectileShpDrawn;
        stats.projectileShpSkippedInvisible =
            cache.projectileShpSkippedInvisible;
        stats.projectileShpMissing = cache.projectileShpMissing;
        stats.projectilePaletteHits = cache.projectilePaletteHits;
        stats.projectilePaletteFallbacks = cache.projectilePaletteFallbacks;
        stats.projectilePaletteStructureFallbacks =
            cache.projectilePaletteStructureFallbacks;
        stats.projectileTravelDrawn = cache.projectileTravelDrawn;
        stats.trailerAnimAttempts = cache.trailerAnimAttempts;
        stats.trailerAnimDrawn = cache.trailerAnimDrawn;
        stats.trailerAnimMissing = cache.trailerAnimMissing;
        stats.impactAnimAttempts = cache.impactAnimAttempts;
        stats.impactAnimDrawn = cache.impactAnimDrawn;
        stats.impactAnimMissing = cache.impactAnimMissing;
        stats.weaponAnimAttempts = cache.weaponAnimAttempts;
        stats.weaponAnimDrawn = cache.weaponAnimDrawn;
        stats.weaponAnimMissing = cache.weaponAnimMissing;
        stats.paletteAnimPaletteHits = cache.paletteAnimPaletteHits;
        stats.paletteFirersPaletteHits = cache.paletteFirersPaletteHits;
        stats.paletteExplicitHits = cache.paletteExplicitHits;
        stats.paletteArtHits = cache.paletteArtHits;
        stats.paletteColorHits = cache.paletteColorHits;
        stats.paletteUnitFallbacks = cache.paletteUnitFallbacks;
        stats.paletteIsoFallbacks = cache.paletteIsoFallbacks;
        stats.paletteUnknownHits = cache.paletteUnknownHits;
        stats.rendered = stats.projectileActorSnapshots > 0
            || stats.impactActorSnapshots > 0
            || stats.particleActorSnapshots > 0
            || stats.particleBeamSnapshots > 0
            || stats.localLightSnapshots > 0;
        SelectObject(dc, oldPen);
        SelectObject(dc, oldBrush);
        return stats;
    }
    const auto terrainLayerStart = runtimeMaybeTimingStart(stageTiming);
    const bool terrainLayerBuilt =
        runtimeShouldBuildTerrainLayer(context, viewportWidth, viewportHeight)
        &&
        buildTerrainLayer(
            world,
            context,
            camera,
            viewportWidth,
            viewportHeight,
            cache
        );
    stats.terrainMs += runtimeMaybeElapsedMs(stageTiming, terrainLayerStart);
    if (!immediateViewportFill) {
        const bool omitFill = terrainLayerBuilt && runtimeTryOmitTerrainViewportFill(
            dc, viewport, context, camera, cache.terrainLayer);
        if (!omitFill) {
            RuntimePerfTraceScope fillTrace("map.terrainViewportFill", context.animationTick);
            FillRect(dc, &viewport, static_cast<HBRUSH>(GetStockObject(DC_BRUSH)));
            runtimeCountTerrainViewportFill(cache.terrainViewportFillCalls);
        } else runtimeCountTerrainViewportFill(cache.terrainViewportFillElisions);
        if (runtimeTerrainViewportFillObservation) {
            if (omitFill) ++runtimeTerrainViewportFillObservation->omitted;
            else ++runtimeTerrainViewportFillObservation->fills;
        }
    }
    const auto terrainBlitStart = runtimeMaybeTimingStart(stageTiming);
    const bool terrainLayerDrawn =
        terrainLayerBuilt
        && drawTerrainLayerToViewport(
            dc,
            viewport,
            context,
            camera,
            cache.terrainLayer
        );
    if (terrainLayerDrawn) {
        stats.bridgeOverlayHighTerminalUnderlays =
            cache.terrainLayer.highBridgeTerminalUnderlays;
        stats.authoredEmptyTerrainSubTiles =
            cache.terrainLayer.authoredEmptyTerrainSubTiles;
    }
    stats.terrainBlitMs += runtimeMaybeElapsedMs(stageTiming, terrainBlitStart);
    traceStage("terrain-layer-ready");

    ensureRuntimeMapFactLookupCache(context, cache);
    const auto visibleTerrainStart = runtimeMaybeTimingStart(stageTiming);
    const bool fastOverlayOnlyTerrainPass =
        terrainLayerDrawn && !stats.detailStatsEnabled;
    struct RuntimeDeferredHighBridgeDraw {
        POINT center{0, 0};
        TerrainCell cell;
        const MapCellFacts* mapFact = nullptr;
    };
    std::vector<RuntimeDeferredHighBridgeDraw> deferredHighBridges;
    deferredHighBridges.reserve(16);
    const auto drawVisibleSmudge = [&](const WorldSmudge& smudge) {
        if (runtimeVisionAt(context, smudge.x, smudge.y)
                == RuntimeCellVisibility::Shrouded) {
            return;
        }
        const ProjectedPoint projected = projectCellXY(
            smudge.x,
            smudge.y,
            smudge.level,
            camera
        );
        const POINT center = screenPoint(projected, viewport, camera);
        const RECT smudgeRect{
            center.x - camera.tileWidth,
            center.y - camera.tileHeight * 2,
            center.x + camera.tileWidth,
            center.y + camera.tileHeight * 2
        };
        if (!rectIntersects(smudgeRect, viewport)) {
            return;
        }

        ++stats.visibleSmudges;
        if (drawRuntimeSmudgeSprite(
                dc,
                viewport,
                center,
                context,
                camera,
                cache,
                smudge.type
            )) {
            ++stats.smudgeSprites;
        } else {
            ++stats.smudgeMissing;
        }
    };

    std::unordered_map<int, std::vector<const WorldSmudge*>>
        fallbackSmudgesByCell;
    if (terrainLayerDrawn) {
        // The cached terrain surface contains only the tile layer here.
        // Paint every smudge before the overlay pass below.
        for (const WorldSmudge& smudge : world.getSmudges()) {
            drawVisibleSmudge(smudge);
        }
    } else {
        // Without the cached terrain layer each tile is painted in the loop
        // below. Index smudges so they can be inserted immediately after
        // their tile and before that cell's overlay.
        for (const WorldSmudge& smudge : world.getSmudges()) {
            // Authored object cells use y*1000+x, while TerrainCell's
            // cellIndex512 uses the renderer's 512-wide lookup grid.
            const int cellIndex = smudge.y * 512 + smudge.x;
            fallbackSmudgesByCell[cellIndex].push_back(&smudge);
        }
    }
    if (fastOverlayOnlyTerrainPass) {
        stats.visibleTerrainCells = cache.terrainLayer.terrainCells;
        if (cache.terrainLayer.fallbackTerrainCells == 0) {
            stats.texturedTerrainCells = cache.terrainLayer.terrainCells;
        } else {
            stats.texturedTerrainCells =
                cache.terrainLayer.texturedTerrainCells;
            stats.fallbackTerrainCells =
                cache.terrainLayer.fallbackTerrainCells;
        }
    }
    for (const TerrainCell& cell : world.getTerrainCells()) {
        if (fastOverlayOnlyTerrainPass && !cell.hasOverlay) {
            continue;
        }

        const ProjectedPoint projected = projectCell(cell, camera);
        const POINT center = screenPoint(projected, viewport, camera);
        const RECT tileRect{
            center.x - camera.tileWidth,
            center.y - camera.tileHeight * 4,
            center.x + camera.tileWidth,
            center.y + camera.tileHeight * 3
        };

        if (!rectIntersects(tileRect, viewport)
            && !runtimeBridgeSpriteIntersectsPaintArea(cell, center,
                viewport, context, camera, cache)) {
            continue;
        }

        const MapCellFacts* mapFact = context.mapFacts == nullptr
            ? nullptr
            : runtimeMapFactForTerrainCell(context, cache, cell);
        TerrainCell mapFactRenderCell;
        const TerrainCell* renderCell = &cell;
        const bool mapFactResourceOverlay =
            mapFact != nullptr
            && mapFact->hasOverlay
            && (mapFact->isResourceCell || mapFact->isOre || mapFact->isGem);
        const bool runtimeResourceOverlay =
            cell.hasOverlay && (cell.overlayIsOre || cell.overlayIsGem);
        if (mapFact != nullptr && mapFact->hasOverlay) {
            mapFactRenderCell =
                runtimeTerrainCellWithMapFactOverlay(cell, mapFact);
            renderCell = &mapFactRenderCell;
        }
        if (context.mapFacts != nullptr) {
            if (mapFact != nullptr) {
                ++stats.mapFactHits;
            } else {
                ++stats.mapFactMisses;
            }
            if (mapFact != nullptr && mapFact->hasOverlay) {
                ++stats.mapFactOverlayCells;
                if (mapFact->isResourceCell) {
                    ++stats.mapFactResourceCells;
                }
                if (mapFact->isBridge) {
                    ++stats.mapFactBridgeCells;
                }
            } else if (cell.hasOverlay) {
                ++stats.mapFactFallbackCells;
            }
        }
        if (mapFactResourceOverlay && runtimeResourceOverlay) {
            ++stats.resourceOverlayRuntimeOverridesMapFact;
        } else if (mapFactResourceOverlay) {
            ++stats.resourceOverlayRuntimeClearsMapFact;
        }

        if (!fastOverlayOnlyTerrainPass) {
            if (terrainLayerDrawn) {
                ++stats.visibleTerrainCells;
                if (cache.terrainLayer.fallbackTerrainCells == 0) {
                    ++stats.texturedTerrainCells;
                } else {
                    ++stats.fallbackTerrainCells;
                }
            } else {
                bool authoredEmptySubTile = false;
                const bool drewTexture = drawTerrainCellTexture(
                    dc,
                    viewport,
                    cell,
                    center,
                    camera,
                    context,
                    cache,
                    &authoredEmptySubTile
                );
                if (drewTexture) {
                    ++stats.texturedTerrainCells;
                    if (authoredEmptySubTile) {
                        ++stats.authoredEmptyTerrainSubTiles;
                    }
                } else {
                    const COLORREF fillColor =
                        colorForTerrainCell(cell, world, context, cache);
                    const COLORREF strokeColor = shadeColor(fillColor, -28);
                    drawDiamond(
                        dc,
                        center,
                        camera.tileWidth,
                        camera.tileHeight,
                        fillColor,
                        strokeColor
                    );
                    ++stats.fallbackTerrainCells;
                }
                ++stats.visibleTerrainCells;
            }
        }

        if (!terrainLayerDrawn) {
            const int cellIndex = cell.cellIndex512 >= 0
                ? cell.cellIndex512
                : cell.y * 512 + cell.x;
            const auto smudges = fallbackSmudgesByCell.find(cellIndex);
            if (smudges != fallbackSmudgesByCell.end()) {
                for (const WorldSmudge* smudge : smudges->second) {
                    if (smudge != nullptr) {
                        drawVisibleSmudge(*smudge);
                    }
                }
            }
        }

        if (renderCell->hasOverlay) {
            const auto overlayStart =
                runtimeMaybeTimingStart(detailedTiming);
            COLORREF overlayColor = RGB(168, 174, 186);
            if (renderCell->overlayIsOre) {
                overlayColor = RGB(224, 194, 77);
            } else if (renderCell->overlayIsGem) {
                overlayColor = RGB(221, 85, 220);
            }
            const std::string overlayImage =
                !renderCell->overlayImage.empty()
                    ? renderCell->overlayImage
                    : renderCell->overlayType;
            const bool bridgeOverlay =
                ((mapFact != nullptr && mapFact->isBridge)
                    || runtimeOverlayLooksLikeBridge(*renderCell))
                && runtimeBridgeOverlaySupportedByTerrainContext(
                    *renderCell,
                    mapFact
                );
            const int bridgeOverlayCellIndex =
                bridgeOverlay ? runtimeMapFactCellIndex(cell) : -1;
            const bool bridgeOverlayBakedCell =
                bridgeOverlayCellIndex >= 0
                && cache.terrainLayer.bridgeOverlayCellIndexes.find(
                    bridgeOverlayCellIndex
                ) != cache.terrainLayer.bridgeOverlayCellIndexes.end();
            const bool bridgeOverlayBakedIntoTerrain =
                terrainLayerDrawn
                && bridgeOverlay
                && bridgeOverlayBakedCell;
            const bool deferredHighBridge =
                bridgeOverlay
                && runtimeOverlayLooksLikeHighBridge(*renderCell);
            if (deferredHighBridge) {
                deferredHighBridges.push_back({
                    center,
                    *renderCell,
                    mapFact
                });
            }
            const bool drewBridgeSprite =
                deferredHighBridge
                || bridgeOverlayBakedIntoTerrain
                || (bridgeOverlay
                    && drawRuntimeBridgeOverlaySprite(
                        dc,
                        viewport,
                        center,
                        *renderCell,
                        mapFact,
                        context,
                        camera,
                        cache
                    ));
            if (bridgeOverlay) {
                ++stats.bridgeOverlayCells;
                if ((mapFact != nullptr && mapFact->isHighBridge)
                    || runtimeOverlayLooksLikeHighBridge(*renderCell)) {
                    ++stats.bridgeOverlayHighCells;
                }
                if ((mapFact != nullptr && mapFact->isLowBridge)
                    || runtimeOverlayLooksLikeLowBridge(*renderCell)) {
                    ++stats.bridgeOverlayLowCells;
                }
                if (runtimeOverlayLooksLikeHighBridge(*renderCell)) {
                    ++stats.bridgeOverlayHighAnchorAdjusted;
                }
                if (mapFact != nullptr
                    && mapFact->overlayResource.present
                    && renderCell->overlayFrame >= 0) {
                    int staticFrame = mapFact->overlayResource.resourceFrame;
                    if (staticFrame < 0) {
                        staticFrame = mapFact->overlayResource.requestedFrame;
                    }
                    if (staticFrame < 0) {
                        staticFrame = mapFact->overlayResource.fallbackFrame;
                    }
                    if (staticFrame >= 0
                        && staticFrame != renderCell->overlayFrame) {
                        const int resolvedFrame = runtimeResourceOverlayFrame(
                            *renderCell,
                            mapFact
                        );
                        if (resolvedFrame == renderCell->overlayFrame) {
                            ++stats.bridgeOverlayRuntimeFrameOverridesMapFact;
                        } else {
                            ++stats.bridgeOverlayRuntimeFrameMismatches;
                        }
                    }
                }
                if (mapFact != nullptr
                    && mapFact->heightLevel != renderCell->level) {
                    ++stats.bridgeOverlayLevelMismatch;
                }
                if (mapFact != nullptr
                    && mapFact->overlayResource.present
                    && mapFact->overlayResource.fallbackFrame >= 0
                    && mapFact->overlayResource.resourceFrame < 0
                    && mapFact->overlayResource.requestedFrame < 0) {
                    ++stats.bridgeOverlayFallbackFrameUsed;
                }
                if (deferredHighBridge) {
                    ++stats.bridgeOverlayDeferred;
                } else if (bridgeOverlayBakedIntoTerrain) {
                    ++stats.bridgeOverlayTerrainBaked;
                } else if (drewBridgeSprite) {
                    ++stats.bridgeOverlaySprites;
                } else {
                    ++stats.bridgeOverlayMissing;
                }
            }
            const bool drawStandaloneSprite =
                !bridgeOverlay
                && runtimeOverlayShouldDrawStandaloneSprite(*renderCell);
            const bool centerStandaloneRock =
                drawStandaloneSprite
                && runtimeOverlayIsRockForRender(*renderCell, context);
            const bool centerStandaloneWall = drawStandaloneSprite
                && runtimeTerrainDepthWallRule(*renderCell, context) != nullptr;
            const bool drewStandaloneTmpSprite =
                drawStandaloneSprite
                && !centerStandaloneRock && !centerStandaloneWall
                && drawRuntimeAuxiliaryTmpSprite(
                    dc,
                    viewport,
                    center,
                    context,
                    camera,
                    cache,
                    overlayImage,
                    renderCell->overlayFrame
                );
            const bool drewStandaloneShpSprite =
                drawStandaloneSprite
                && !drewStandaloneTmpSprite
                && drawRuntimeStandaloneOverlayShpSprite(
                    dc,
                    viewport,
                    center,
                    context,
                    camera,
                    cache,
                    overlayImage,
                    renderCell->overlayFrame,
                    0,
                    0,
                    false,
                    false,
                    centerStandaloneRock || centerStandaloneWall
                );
            if (drewStandaloneShpSprite && centerStandaloneRock) {
                ++stats.rockOverlaySpritesCentered;
            }
            const bool drewOverlaySprite =
                drewBridgeSprite
                || drewStandaloneTmpSprite
                || drewStandaloneShpSprite;
            const RuntimeResourceOverlayKind resourceKind =
                runtimeResourceOverlayKindForRender(*renderCell, mapFact);
            if ((renderCell->overlayIsOre || renderCell->overlayIsGem)
                && resourceKind == RuntimeResourceOverlayKind::None) {
                ++stats.resourceOverlayBridgeRejected;
            }
            if (resourceKind != RuntimeResourceOverlayKind::None) {
                ++stats.resourceOverlayCells;
                if (resourceKind == RuntimeResourceOverlayKind::Gem) {
                    ++stats.resourceOverlayGemCells;
                } else {
                    ++stats.resourceOverlayOreCells;
                }
                const bool drewResourceSprite = drawRuntimeResourceOverlaySprite(
                    dc,
                    viewport,
                    center,
                    *renderCell,
                    mapFact,
                    context,
                    camera,
                    cache,
                    resourceKind,
                    &stats
                );
                if (!drewResourceSprite) {
                    ++stats.resourceOverlayMissing;
                    if (resourceKind == RuntimeResourceOverlayKind::Gem) {
                        ++stats.resourceOverlayGemMissing;
                    } else {
                        ++stats.resourceOverlayOreMissing;
                    }
                } else {
                    ++stats.resourceOverlaySprites;
                }
            } else if (!drewOverlaySprite && drawStandaloneSprite) {
                drawSmallCross(dc, center.x, center.y, overlayColor);
            }
            ++stats.visibleOverlayCells;
            stats.overlayMs += runtimeMaybeElapsedMs(
                detailedTiming,
                overlayStart
            );
        }
    }
    // Coarse stages are disjoint: this includes smudges, resource overlays and
    // fallback tile drawing. Detailed legacy counters retain their old scope.
    const double visibleTerrainMs = runtimeMaybeElapsedMs(stageTiming, visibleTerrainStart);
    if (context.coarseStageTimingEnabled) stats.overlayMs = visibleTerrainMs;
    else stats.terrainMs += visibleTerrainMs;
    traceStage("visible-terrain-ready");
    ensureRuntimeTerrainCellLookup(world, cache);
    RuntimeMapLightFrame mapLightFrame(viewport, world, context, camera, cache);
    RuntimeMapLightFrameScope mapLightScope(mapLightFrame);
    stats.mapLightSources = static_cast<int>(mapLightFrame.sources.size());
    if (context.specialMechanismSnapshots != nullptr) {
        for (const auto& site : *context.specialMechanismSnapshots) {
            if (site.kind != "radiation" && site.kind != "superWeaponRadiation") continue;
            const int phase = drawRuntimeRadiationCellTint(dc, viewport, world, context, camera, cache, stats, site);
            if (phase > 0) recordRuntimeSpecialMechanismRenderIntent(stats, site, phase);
        }
    }

    const auto terrainObjectsStart = runtimeMaybeTimingStart(stageTiming);
    struct TerrainObjectFrameInfo {
        int tmpFrames = 0;
        int rawFrames = 0;
    };
    // This memo exists for one draw only: roots, theater and art/rules all
    // belong to the same immutable context. Preserve the exact requested
    // image ID, including explicit extensions. Failures are not retained by
    // this memo across frames; the underlying asset caches keep their policy.
    std::unordered_map<std::string, TerrainObjectFrameInfo> terrainFramesByImage;
    const auto terrainFrameInfo = [&](const std::string& imageId)
        -> const TerrainObjectFrameInfo& {
        const auto found = terrainFramesByImage.find(imageId);
        if (found != terrainFramesByImage.end()) return found->second;
        TerrainObjectFrameInfo info;
        info.tmpFrames = runtimeAuxiliaryTmpFrameCount(context, cache, imageId);
        info.rawFrames = runtimeTerrainObjectFrameCount(
            context, cache, imageId, info.tmpFrames);
        return terrainFramesByImage.emplace(imageId, info).first->second;
    };
    const auto drawTerrainShadow = [&](const WorldTerrainObject& object, const POINT& center) {
        if (!context.shadowsEnabled) return;
            const ArtType* terrainArt = context.art == nullptr
                ? nullptr
                : context.art->findArtType(object.type);
            ++stats.shadowCandidates;
            if (!runtimeArtShadowEnabled(terrainArt, true)) {
                ++stats.shadowsSuppressed;
                return;
            }
            const TerrainObjectFrameInfo& frameInfo = terrainFrameInfo(object.type);
            if (frameInfo.tmpFrames > 0) {
                const int terrainFrameCount = std::max(1, frameInfo.rawFrames);
                const int terrainFrame =
                    selectRuntimeTerrainObjectAnimationFrame(
                        context,
                        object,
                        terrainArt,
                        terrainFrameCount
                    );
                const RuntimeTmpSubTileImage* image =
                    loadRuntimeAuxiliaryTmpImage(
                        context,
                        cache,
                        object.type,
                        terrainFrame
                    );
                if (image == nullptr) {
                    ++stats.shadowsMissing;
                    return;
                }
                const int darkenedPixels = drawRuntimeSoftShadowEllipse(
                    dc,
                    center,
                    context,
                    std::clamp(image->width / 3, 5, 36),
                    std::clamp(image->height / 12, 2, 10),
                    72,
                    &viewport
                );
                ++stats.generatedShadowFallbacks;
                if (darkenedPixels > 0) {
                    ++stats.shadowsDrawn;
                    stats.shadowPixelsDarkened += darkenedPixels;
                }
                return;
            }
            const int rawFrameCount = frameInfo.rawFrames;
            if (rawFrameCount <= 0) {
                ++stats.shadowsMissing;
                return;
            }
            const int visibleFrameCount =
                runtimeVisibleMainFrameCount(rawFrameCount, true);
            const int terrainFrame = selectRuntimeTerrainObjectAnimationFrame(
                context,
                object,
                terrainArt,
                visibleFrameCount
            );
            RuntimeObjectShpSpriteCacheEntry* frame =
                loadRuntimeAuxiliaryShpSpriteFromCache(
                    object.type,
                    terrainFrame,
                    context,
                    cache,
                    true
                );
            if (frame == nullptr) {
                ++stats.shadowsMissing;
                return;
            }
            int darkenedPixels = 0;
            const bool validMask = frame->hasShadowFrame
                && drawRuntimeShpShadowFrame(
                    dc,
                    viewport,
                    runtimeAuxiliaryShpAdjustedCenter(center, camera, frame->shadowImage, 0, 0, true),
                    context,
                    camera,
                    frame->shadowImage,
                    &darkenedPixels
                );
            if (validMask) {
                ++stats.shpShadowMasksResolved;
            } else {
                darkenedPixels = drawRuntimeSoftShadowEllipse(
                    dc,
                    center,
                    context,
                    std::clamp(frame->image.width / 3, 5, 36),
                    std::clamp(frame->image.height / 12, 2, 10),
                    72,
                    &viewport
                );
                ++stats.generatedShadowFallbacks;
            }
            if (darkenedPixels > 0) {
                ++stats.shadowsDrawn;
                stats.shadowPixelsDarkened += darkenedPixels;
                if (validMask) {
                    ++stats.shpShadowsDrawn;
                }
            }
    };
    if (context.shadowsEnabled) {
        for (const WorldTerrainObject& object : world.getTerrainObjects()) {
            if (!runtimeTerrainObjectShouldRender(object)) {
                continue;
            }
            if (runtimeVisionAt(context, object.x, object.y)
                    == RuntimeCellVisibility::Shrouded) {
                continue;
            }
            const ProjectedPoint projected = projectCellXY(
                object.x,
                object.y,
                object.level,
                camera
            );
            const POINT center = screenPoint(projected, viewport, camera);
            if (center.x < viewport.left
                || center.x >= viewport.right
                || center.y < viewport.top
                || center.y >= viewport.bottom) {
                continue;
            }
            drawTerrainShadow(object, center);
        }
    }
    drawRuntimeProjectileActorShadows(
        dc,
        viewport,
        context,
        camera,
        cache,
        stats
    );
    const std::string typeCacheSignature =
        runtimeObjectTypeRenderCacheSignature(context);
    if (cache.objectTypeRenderCacheSignature != typeCacheSignature) {
        cache.objectTypeRenderCacheSignature = typeCacheSignature;
        cache.structureFootprintsByType.clear();
        cache.objectVoxelArtByType.clear();
        cache.objectAircraftByType.clear();
        cache.projectileTypeIndexByImage.clear();
        cache.auxiliaryEffectKindByImage.clear();
    }
    const RuntimeShadowReceiverTerrainLookup& shadowReceiverTerrainByCell =
        ensureRuntimeTerrainCellLookup(world, cache);
    const RuntimeSpecialObjectRenderLookup& specialObjectLookup =
        *runtimeGeometrySpecialObjectLookup(context);
    const auto footprintForObject =
        [&](const WorldObjectInstance& object) -> RuntimeFootprintDimensions {
        if (object.kind != WorldObjectKind::Structure) {
            return {};
        }
        const std::string key = toLowerAscii(object.type);
        const auto found = cache.structureFootprintsByType.find(key);
        if (found != cache.structureFootprintsByType.end()) {
            return {found->second.width, found->second.height};
        }
        const RuntimeFootprintDimensions footprint =
            runtimeObjectFoundationDimensions(object, context);
        cache.structureFootprintsByType.emplace(key,
            RuntimeRenderFootprintCacheEntry{footprint.width, footprint.height});
        return footprint;
    };
    std::vector<WorldObjectInstance> wreckObjects;
    if (context.wrecks) {
        wreckObjects.reserve(context.wrecks->size());
        for (const auto& wreck : *context.wrecks)
            wreckObjects.push_back(runtimeWreckObjectPose(wreck, context.animationTick, context.fixedTickHz));
    }
    std::vector<RuntimeWorldObjectShadowDrawRecord> sortedGroundShadows;
    // Historical objects usually contribute no record. This is only an initial
    // allocation hint: every eligible shadow is still appended in world order.
    sortedGroundShadows.reserve(std::min(world.getObjects().size(), std::size_t{256}));
    for (std::size_t index = 0; index < world.getObjects().size() + wreckObjects.size(); ++index) {
        const bool retainedWreck = index >= world.getObjects().size();
        const WorldObjectInstance& object = retainedWreck ? wreckObjects[index - world.getObjects().size()] : world.getObjects()[index];
        const auto queryVisibility = [&]() {
            if (runtimeGroundShadowEligibilityObservation) {
                ++runtimeGroundShadowEligibilityObservation->visibilityQueries;
                if (retainedWreck) ++runtimeGroundShadowEligibilityObservation->retainedWreckQueries;
            }
            return retainedWreck
                ? (!runtimeVisionEnabled(context) || runtimeVisionOwnerIsShared(context, object.owner)
                    || context.vision->isCellVisibleTo(context.visionObserverOwner, object.x, object.y))
                : runtimeVisionObjectBodyShouldRender(context, object);
        };
        // The original reference queries vision before inspecting dead state.
        // Vision and the collapse/selling predicates are value-only reads; an
        // object failing this unchanged eligibility predicate cannot draw.
        bool visible = false;
        if (groundShadowEligibilityReference) visible = queryVisibility();
        const auto* collapse = runtimeBuildingCollapseForObject(context.buildingCollapses,
            object.instanceId, context.animationTick, context.fixedTickHz);
        if (!object.alive && object.mission != "CrashingWreck" && !runtimeStructureIsSelling(object) && !collapse) {
            if (runtimeGroundShadowEligibilityObservation) ++runtimeGroundShadowEligibilityObservation->deadRejected;
            continue;
        }
        if (!groundShadowEligibilityReference) visible = queryVisibility();
        if (runtimeGroundShadowEligibilityObservation) {
            auto& observation = *runtimeGroundShadowEligibilityObservation;
            ++observation.eligible;
            if (object.mission == "CrashingWreck") ++observation.crashingEligible;
            if (object.kind == WorldObjectKind::Structure && !object.alive && object.mission == "Sold"
                && object.buildAnimTicksTotal > 0 && object.buildAnimTicksRemaining > 0) ++observation.sellingEligible;
            if (collapse) ++observation.collapseEligible;
        }
        if (objectOnBridgeForRender(object)
            || !visible
            || runtimeSpecialObjectIsHidden(
                context, object, &specialObjectLookup
            )) {
            continue;
        }
        const SpecialMechanismRenderSnapshot* spyDisguise =
            runtimeSpyDisguiseSnapshot(
                context, object.instanceId, &specialObjectLookup
            );
        // A terrain disguise has no trustworthy unit shadow frame.  Omitting
        // it is preferable to leaking the real chassis/infantry silhouette.
        if (const auto* disguise = runtimeCamouflageSnapshot(context, object, &specialObjectLookup)) {
            WorldTerrainObject tree; tree.type=disguise->resourceId;
            tree.x=object.x; tree.y=object.y; tree.level=object.level;
            drawTerrainShadow(tree, screenPoint(runtimeObjectDrawPoint(object, {}, camera), viewport, camera));
            continue;
        }
        if (runtimeCamouflageSnapshot(context, object, &specialObjectLookup)
            || (spyDisguise != nullptr && spyDisguise->phase == "Terrain")) {
            continue;
        }
        std::optional<WorldObjectInstance> observerProjection;
        const WorldObjectInstance& observerObject =
            runtimeSpyObserverObjectForRender(
                context, object, observerProjection, &specialObjectLookup
            );
        const RuntimeFootprintDimensions footprint = footprintForObject(observerObject);
        const bool usesVoxelArt =
            observerObject.kind == WorldObjectKind::Unit
            && cachedRuntimeObjectUsesVoxelArt(
                cache,
                observerObject,
                context
            );
        const bool aircraft =
            (observerObject.kind == WorldObjectKind::Unit
                || observerObject.kind == WorldObjectKind::Infantry)
            && cachedRuntimeObjectRenderBool(
                cache.objectAircraftByType,
                observerObject,
                context,
                runtimeObjectLooksAircraftForRender
            );
        if (runtimeShadowReceiverUsesBridgeLayer(
                observerObject,
                aircraft,
                shadowReceiverTerrainByCell
            )) {
            continue;
        }
        const POINT bodyCenter = screenPoint(
            runtimeObjectDrawPoint(observerObject, footprint, camera),
            viewport,
            camera
        );
        const double shadowReceiverLevel =
            runtimeShadowReceiverLevelForObject(
                observerObject,
                aircraft,
                shadowReceiverTerrainByCell
            );
        const ProjectedPoint shadowDrawPoint = runtimeObjectShadowDrawPoint(
            observerObject,
            footprint,
            camera,
            aircraft,
            shadowReceiverLevel
        );
        const POINT shadowCenter = screenPoint(
            shadowDrawPoint,
            viewport,
            camera
        );
        const int objectMargin = runtimeObjectCullMargin(
            observerObject,
            footprint
        );
        const bool bodyCulled =
            bodyCenter.x < viewport.left - objectMargin
            || bodyCenter.x >= viewport.right + objectMargin
            || bodyCenter.y < viewport.top - objectMargin
            || bodyCenter.y >= viewport.bottom + objectMargin;
        const bool shadowCulled =
            shadowCenter.x < viewport.left - objectMargin
            || shadowCenter.x >= viewport.right + objectMargin
            || shadowCenter.y < viewport.top - objectMargin
            || shadowCenter.y >= viewport.bottom + objectMargin;
        if (bodyCulled && shadowCulled) {
            continue;
        }
        RuntimeWorldObjectShadowDrawRecord record;
        record.object = &object;
        record.center = shadowCenter;
        record.sortPoint = shadowDrawPoint;
        record.drawLevel = shadowReceiverLevel;
        record.cellSum = objectRenderX(observerObject)
            + objectRenderY(observerObject);
        record.kindBias = objectKindSortBias(observerObject.kind);
        record.instanceId = object.instanceId;
        record.usesVoxelArt = usesVoxelArt;
        record.aircraft = aircraft;
        sortedGroundShadows.push_back(record);
    }
    sortRuntimeWorldObjectShadowDrawRecords(sortedGroundShadows);
    for (const RuntimeWorldObjectShadowDrawRecord& record : sortedGroundShadows) {
        if (record.object == nullptr) {
            continue;
        }
        std::optional<WorldObjectInstance> observerProjection;
        const WorldObjectInstance& object =
            runtimeSpyObserverObjectForRender(
                context, *record.object, observerProjection,
                &specialObjectLookup
            );
        if (const auto* collapse = runtimeBuildingCollapseForObject(context.buildingCollapses,
                object.instanceId, context.animationTick, context.fixedTickHz)) {
            drawRuntimeBuildingCollapse(dc, viewport, record.center, object, *collapse, context, camera, cache, stats, true);
            continue;
        }
        const RuntimeWorldObjectShadowResult result =
            drawRuntimeWorldObjectShadow(
                dc,
                viewport,
                object,
                record.center,
                context,
                camera,
                cache,
                record.usesVoxelArt
            );
        recordRuntimeWorldObjectShadowResult(
            stats,
            object,
            record.aircraft,
            result
        );
    }

    for (const WorldTerrainObject& object : world.getTerrainObjects()) {
        if (!runtimeTerrainObjectShouldRender(object)) {
            continue;
        }
        if (runtimeVisionAt(context, object.x, object.y)
                == RuntimeCellVisibility::Shrouded) {
            ++stats.visionHiddenTerrainObjects;
            continue;
        }
        const ProjectedPoint projected = projectCellXY(
            object.x,
            object.y,
            object.level,
            camera
        );
        const POINT center = screenPoint(projected, viewport, camera);
        if (center.x < viewport.left
            || center.x >= viewport.right
            || center.y < viewport.top
            || center.y >= viewport.bottom) {
            continue;
        }

        const ArtType* terrainArt =
            context.art == nullptr
                ? nullptr
                : context.art->findArtType(object.type);
        const TerrainObjectFrameInfo& frameInfo = terrainFrameInfo(object.type);
        const int tmpFrameCount = frameInfo.tmpFrames;
        const bool terrainShpHasShadow =
            tmpFrameCount <= 0
            && runtimeArtShadowEnabled(terrainArt, true);
        const int rawTerrainFrameCount = std::max(1, frameInfo.rawFrames);
        const int terrainFrameCount = tmpFrameCount > 0
            ? rawTerrainFrameCount
            : runtimeVisibleMainFrameCount(
                rawTerrainFrameCount,
                terrainShpHasShadow
            );
        const int terrainFrame = selectRuntimeTerrainObjectAnimationFrame(
            context,
            object,
            terrainArt,
            terrainFrameCount
        );
        RuntimeMapLightObjectScope terrainLightScope(object.x, object.y);
        const bool drewTerrainSprite =
            (tmpFrameCount > 0 && drawRuntimeAuxiliaryTmpSprite(
                dc,
                viewport,
                center,
                context,
                camera,
                cache,
                object.type,
                terrainFrame
            ))
            || drawRuntimeAuxiliaryShpSprite(
                dc,
                viewport,
                center,
                context,
                camera,
                cache,
                object.type,
                terrainFrame,
                0,
                0,
                terrainShpHasShadow,
                false, false, RGB(255,255,255), nullptr, true
            );
        if (drewTerrainSprite) {
            ++stats.terrainObjectSprites;
            stats.terrainObjectAnimationFrames =
                std::max(
                    stats.terrainObjectAnimationFrames,
                    terrainFrameCount
                );
            if (terrainFrameCount > 1 && terrainFrame > 0) {
                ++stats.terrainObjectAnimatedSprites;
            }
        }
        if (!drewTerrainSprite) {
            SetDCBrushColor(dc, RGB(30, 111, 72));
            SetDCPenColor(dc, RGB(8, 48, 34));
            Ellipse(dc, center.x - 4, center.y - 8, center.x + 5, center.y + 1);
        }
        ++stats.visibleTerrainObjects;
    }
    stats.terrainObjectsMs = runtimeMaybeElapsedMs(stageTiming, terrainObjectsStart);
    traceStage("terrain-objects-ready");

    const auto worldObjectSortStart = runtimeMaybeTimingStart(stageTiming);
    std::vector<RuntimeWorldObjectDrawRecord> sortedObjects;
    // Growth remains unlimited; avoid sizing fresh storage for dead history.
    sortedObjects.reserve(std::min(world.getObjects().size() + wreckObjects.size(), std::size_t{256}));
    for (std::size_t objectIndex = 0; objectIndex < world.getObjects().size() + wreckObjects.size(); ++objectIndex) {
        const bool retainedWreck = objectIndex >= world.getObjects().size();
        const WorldObjectInstance& object = retainedWreck
            ? wreckObjects[objectIndex - world.getObjects().size()] : world.getObjects()[objectIndex];
        if (!retainedWreck && !runtimeWorldObjectBodyShouldRender(object)
            && !runtimeBuildingCollapseForObject(context.buildingCollapses, object.instanceId, context.animationTick, context.fixedTickHz)) {
            continue;
        }
        if (runtimeSpecialObjectIsHidden(
                context, object, &specialObjectLookup
            )) {
            continue;
        }
        const bool visible = retainedWreck
            ? (!runtimeVisionEnabled(context) || runtimeVisionOwnerIsShared(context, object.owner)
                || context.vision->isCellVisibleTo(context.visionObserverOwner, object.x, object.y))
            : runtimeVisionObjectBodyShouldRender(context, object);
        if (!visible) {
            ++stats.visionHiddenWorldObjects;
            continue;
        }
        ++stats.preCullWorldObjects;
        std::optional<WorldObjectInstance> observerProjection;
        const WorldObjectInstance& observerObject =
            runtimeSpyObserverObjectForRender(
                context, object, observerProjection, &specialObjectLookup
            );
        const RuntimeFootprintDimensions footprint =
            footprintForObject(observerObject);
        const ProjectedPoint drawPoint =
            runtimeObjectDrawPoint(observerObject, footprint, camera);
        POINT center = screenPoint(drawPoint, viewport, camera);
        const bool aircraft =
            (observerObject.kind == WorldObjectKind::Unit
                || observerObject.kind == WorldObjectKind::Infantry)
            && cachedRuntimeObjectRenderBool(
                cache.objectAircraftByType,
                observerObject,
                context,
                runtimeObjectLooksAircraftForRender
            );
        center.y -= runtimeAircraftSpriteLiftPixels(
            observerObject,
            aircraft
        );
        const POINT shadowCenter = screenPoint(
            runtimeObjectShadowDrawPoint(
                observerObject,
                footprint,
                camera,
                aircraft,
                runtimeShadowReceiverLevelForObject(
                    observerObject,
                    aircraft,
                    shadowReceiverTerrainByCell
                )
            ),
            viewport,
            camera
        );
        const int objectMargin = runtimeObjectCullMargin(
            observerObject,
            footprint
        );
        const bool bodyCulled =
            center.x < viewport.left - objectMargin
            || center.x >= viewport.right + objectMargin
            || center.y < viewport.top - objectMargin
            || center.y >= viewport.bottom + objectMargin;
        const bool shadowCulled =
            shadowCenter.x < viewport.left - objectMargin
            || shadowCenter.x >= viewport.right + objectMargin
            || shadowCenter.y < viewport.top - objectMargin
            || shadowCenter.y >= viewport.bottom + objectMargin;
        if (bodyCulled && shadowCulled) {
            ++stats.culledWorldObjects;
            continue;
        }
        if (!bodyCulled
            && observerObject.kind == WorldObjectKind::Structure) {
            ++stats.structureRearAnchorObjects;
            if (footprint.width > 1 || footprint.height > 1) {
                ++stats.structureMultiCellAnchorObjects;
            }
        }

        RuntimeWorldObjectDrawRecord record;
        record.object = &object;
        record.drawLevel = drawLevelForObject(observerObject);
        record.sortPoint = runtimeObjectSortPoint(
            observerObject,
            footprint,
            camera
        );
        record.center = center;
        record.shadowCenter = shadowCenter;
        record.cellSum = objectRenderX(observerObject)
            + objectRenderY(observerObject);
        record.kindBias = objectKindSortBias(observerObject.kind);
        record.instanceId = object.instanceId;
        record.cullMargin = objectMargin;
        record.footprintWidth = footprint.width;
        record.footprintHeight = footprint.height;
        record.aircraft = aircraft;
        record.airborneForeground = aircraft && observerObject.airborne;
        record.bodyVisible = !bodyCulled;
        if (observerObject.kind == WorldObjectKind::Unit) {
            record.usesVoxelArt = cachedRuntimeObjectUsesVoxelArt(
                cache,
                observerObject,
                context
            );
        }
        record.shadowOnBridge = objectOnBridgeForRender(observerObject)
            || runtimeShadowReceiverUsesBridgeLayer(
                observerObject,
                record.aircraft,
                shadowReceiverTerrainByCell
            );
        sortedObjects.push_back(record);
    }
    stats.repairDepotForegroundObjects = applyRuntimeRepairDepotForegroundOrder(sortedObjects, context);
    stats.unloadingClassForegroundObjects =
        applyRuntimeUnloadingClassForegroundOrder(
            sortedObjects,
            context
        );
    stats.dockedAircraftForegroundObjects =
        applyRuntimeDockedAircraftForegroundOrder(sortedObjects);
    for (auto& record : sortedObjects) {
        if (record.object == nullptr || record.object->tankBunkerHostId < 0) continue;
        const auto host = std::find_if(sortedObjects.begin(), sortedObjects.end(), [&](const auto& item) {
            return item.instanceId == record.object->tankBunkerHostId;
        });
        if (host == sortedObjects.end()) continue;
        record.drawLevel = host->drawLevel;
        record.sortPoint = host->sortPoint;
        record.cellSum = host->cellSum;
        record.kindBias = host->kindBias + 1;
        record.ySortOverrideLeptons = runtimeWorldObjectYSortLeptons(*host);
        record.hasYSortOverride = true;
    }
    stats.sortedWorldObjects = static_cast<int>(sortedObjects.size());
    std::sort(
        sortedObjects.begin(),
        sortedObjects.end(),
        [](const RuntimeWorldObjectDrawRecord& left,
            const RuntimeWorldObjectDrawRecord& right) {
            return runtimeWorldObjectRenderOrderLess(
                left.sortPoint,
                left.drawLevel,
                left.cellSum,
                left.kindBias,
                left.instanceId,
                right.sortPoint,
                right.drawLevel,
                right.cellSum,
                right.kindBias,
                right.instanceId
            );
        }
    );
    stats.worldObjectSortMs = runtimeMaybeElapsedMs(stageTiming, worldObjectSortStart);
    traceStage("world-sort-ready");

    // The platform stays below every entering/leaving vehicle. Its animated
    // crane is a separate foreground layer, painted once after the last
    // visible vehicle using that platform's shared depth.
    std::unordered_map<int, int> repairDepotForegroundVehicles;
    for (const auto& record : sortedObjects) {
        if (!record.bodyVisible || record.repairDepotHostId < 0) continue;
        repairDepotForegroundVehicles[record.repairDepotHostId] = record.instanceId;
    }

    const auto worldObjectsStart = runtimeMaybeTimingStart(stageTiming);
    const auto drawWorldObjectShadowRecord =
        [&](const RuntimeWorldObjectDrawRecord& drawRecord) {
        if (drawRecord.object == nullptr) {
            return;
        }
        if (drawRecord.object->factoryExitHostId >= 0) {
            for (const auto& host : sortedObjects)
                if (host.object && host.instanceId == drawRecord.object->factoryExitHostId
                    && runtimeAircraftOverStructureFoundation(drawRecord, host)) return;
        }
        const SpecialMechanismRenderSnapshot* spyDisguise =
            runtimeSpyDisguiseSnapshot(
                context,
                drawRecord.object->instanceId,
                &specialObjectLookup
            );
        if (const auto* disguise = runtimeCamouflageSnapshot(context, *drawRecord.object, &specialObjectLookup)) {
            WorldTerrainObject tree; tree.type=disguise->resourceId;
            tree.x=drawRecord.object->x; tree.y=drawRecord.object->y; tree.level=drawRecord.object->level;
            drawTerrainShadow(tree, drawRecord.shadowCenter);
            return;
        }
        if (runtimeCamouflageSnapshot(context, *drawRecord.object, &specialObjectLookup)
            || (spyDisguise != nullptr && spyDisguise->phase == "Terrain")) {
            return;
        }
        std::optional<WorldObjectInstance> observerProjection;
        const WorldObjectInstance& object =
            runtimeSpyObserverObjectForRender(
                context,
                *drawRecord.object,
                observerProjection,
                &specialObjectLookup
            );
        const RuntimeWorldObjectShadowResult result =
            drawRuntimeWorldObjectShadow(
                dc,
                viewport,
                object,
                drawRecord.shadowCenter,
                context,
                camera,
                cache,
                drawRecord.usesVoxelArt
            );
        recordRuntimeWorldObjectShadowResult(
            stats,
            object,
            drawRecord.aircraft,
            result
        );
    };
    RuntimeBehindMarkerFrameState behindMarkers;
    RuntimeBehindMarkerFrameScope behindMarkerFrameScope(behindMarkers, context, sortedObjects);
    auto* buildingHitMemo = context.captureBuildingDepthHitSpans
        ? runtimePaintBuildingDepthMemo(world, viewport, context, camera, cache) : nullptr;
    // Only an explicitly shared paint batch has a later interaction consumer.
    if (buildingHitMemo == RuntimeGeometryQueryFrame::active) buildingHitMemo = nullptr;
    if (buildingHitMemo) {
        buildingHitMemo->buildingVisibleHitSpansReady = false;
        buildingHitMemo->buildingVisibleHitSpans.clear();
    }
    std::optional<RuntimeBuildingDepthFrameScope> buildingDepthFrameScope;
    // Without a structure or terrain wall, the ground-depth collector has no cover
    // for any vehicle to participate in. Avoid the whole-viewport scene-Z array.
    // A nested external compositor retains its established scope isolation.
    if (!runtimeSkipEmptyBuildingDepthScene(world) || runtimeWorldHasTerrainDepthWalls(world, context)
        || runtimeBuildingDepthFrame != nullptr)
        buildingDepthFrameScope.emplace(viewport, context, cache);
    if (buildingDepthFrameScope && buildingDepthFrameScope->ready) {
        replayRuntimeBuildingDepthGeometry(world, viewport, context, camera, cache, buildingDepthFrameScope->state);
        drawRuntimeTerrainWallDepthSprites(world, viewport, context, camera, cache, buildingDepthFrameScope->state, dc);
        if (buildingHitMemo) publishRuntimePaintBuildingVisibleHitSpans(*buildingHitMemo,
            buildingDepthFrameScope->state, context.animationTick, cache);
    }
    const RECT& worldObjectViewport = viewport;
    const auto& untintedObjectContext = context;
    const auto drawWorldObjectRecord =
        [&](const RuntimeWorldObjectDrawRecord& drawRecord, const RECT* bodyViewport = nullptr) {
        const RECT& viewport = bodyViewport ? *bodyViewport : worldObjectViewport;
        const WorldObjectInstance& object = *drawRecord.object;
        RuntimeMapRenderContext context = untintedObjectContext;
        if (runtimeObjectHasAirstrikeTint(object, context)) {
            context.airstrikeBodyColorAdd = runtimeAirstrikeColorAdd(context);
            if (context.airstrikeBodyColorAdd != 0) {
                ++stats.specialMechanismRenderActors;
                runtimeMixRenderIntentHash(stats.renderIntentHash, "airstrikeBodyTint:" + std::to_string(object.instanceId));
            }
        }
        if (const auto* wreck = runtimeWreckForObject(context.wrecks, object)) {
            ++stats.wreckBodySprites;
            if (wreck->sinking) ++stats.sinkingBodySprites;
        }
        RuntimeBehindMarkerObjectScope behindMarkerObjectScope(object);
        const auto lightFoundation = footprintForObject(object);
        RuntimeMapLightObjectScope objectLightScope(object.x + (lightFoundation.width - 1) * 0.5,
            object.y + (lightFoundation.height - 1) * 0.5);
        const POINT center = drawRecord.center;
        const auto temporal = specialObjectLookup.find(object.instanceId);
        if((object.kind==WorldObjectKind::Structure||runtimeNavalUnitUsesBuildingDepth(object,context)
                ||(runtimeBuildingDepthFrame&&runtimeBuildingDepthFrame->groundVehicleIds.contains(object.instanceId)))
            &&temporal!=specialObjectLookup.end()&&temporal->second.temporalFrozen)
            restoreRuntimeFrozenBuildingUnderlay(dc,context,object.instanceId);
        std::optional<RuntimeTemporalBodyOpacityScope> temporalOpacity;
        temporalOpacity.emplace(dc, viewport, context, stats, center, drawRecord.cullMargin,
            temporal != specialObjectLookup.end() && temporal->second.temporalFrozen);

        if (const auto* disguise = runtimeCamouflageSnapshot(context, object, &specialObjectLookup)) {
            RuntimeMapLightObjectScope terrainLightScope(object.x, object.y);
            const bool drawn = drawRuntimeCamouflageBody(dc, viewport, center,
                context, camera, cache, *disguise);
            if (drawn) {
                ++stats.specialMechanismRenderActors; ++stats.visibleWorldObjects;
                runtimeMixRenderIntentHash(stats.renderIntentHash, "camouflage:" + disguise->resourceId);
            }
            return; // Never expose the real chassis if an enemy's tree asset is missing.
        }

        if (const SpecialMechanismRenderSnapshot* disguise =
                runtimeSpyDisguiseSnapshot(
                    context, object.instanceId, &specialObjectLookup
                )) {
            const WorldObjectInstance projected = runtimeSpyBodyProjection(object, *disguise);
            const bool drewDisguise = drawRuntimeSpyDisguiseBody(dc, viewport,
                projected, center, context, camera, cache, *disguise);
            if (drewDisguise) {
                ++stats.specialMechanismRenderActors;
                ++stats.visibleWorldObjects;
                if (projected.kind != WorldObjectKind::Unit) {
                    ++stats.visibleObjectShpSprites;
                }
                recordRuntimeOwnerRemapStats(
                    stats,
                    context,
                    projected.owner
                );
                runtimeMixRenderIntentHash(
                    stats.renderIntentHash,
                    "spyDisguise:" + disguise->resourceId
                        + ":" + disguise->owner
                );
                return;
            }
        }

        RuntimeSpriteGeometryObservation observedBody;
        const bool observeMobile = object.kind != WorldObjectKind::Structure
            && runtimeGeometryPaintRecordingEnabled(object, context, camera, cache);
        RuntimeSpriteGeometryObservationScope bodyObservationScope(observeMobile ? &observedBody : nullptr);
        bool mobileBodyResolved = false;
        const auto prepareFallbackDrawing = [&] {
            SetDCBrushColor(
                dc,
                runtimeObjectFallbackColor(context, object.owner)
            );
            SetDCPenColor(dc, RGB(7, 10, 14));
        };

        const auto protection = specialObjectLookup.find(object.instanceId);
        std::optional<RuntimeForceShieldTintScope> protectionTint;
        protectionTint.emplace(dc, viewport, context, stats, center, drawRecord.cullMargin,
            protection != specialObjectLookup.end() && protection->second.forceShield,
            protection != specialObjectLookup.end() ? protection->second.ironCurtainExpireTick : -1);
        std::optional<RuntimeBuildingDepthObjectScope> sceneDepthObject;
        sceneDepthObject.emplace(object, center, context);
        if (object.kind == WorldObjectKind::Structure) {
            if (const auto* collapse = runtimeBuildingCollapseForObject(context.buildingCollapses,
                    object.instanceId, context.animationTick, context.fixedTickHz)) {
                drawRuntimeBuildingCollapse(dc, viewport, center, object, *collapse, context, camera, cache, stats, false);
                return;
            }
            RuntimeBuildingDepthObjectScope buildingDepthObject(object, center, context);
            const auto structureStart =
                runtimeMaybeTimingStart(detailedTiming);
            RECT structureBaseLocalRect{0, 0, 0, 0};
            RECT structureBaseGlobalRect{0, 0, 0, 0};
            bool structureBaseLocalRectValid = false;
            bool structureBaseGlobalRectValid = false;
            tryDrawRuntimeStructureBib(
                dc,
                viewport,
                object,
                center,
                context,
                camera,
                cache
            );

            const bool drewBuildup =
                tryDrawRuntimeStructureBuildup(
                    dc,
                    viewport,
                    object,
                    center,
                    context,
                    camera,
                    cache
                );
            const bool drewOverlaySprite =
                !drewBuildup
                && tryDrawRuntimeStructureOverlaySprite(
                    dc,
                    viewport,
                    object,
                    center,
                    context,
                    camera,
                    cache,
                    stats
                );
            const bool drewBase =
                drewBuildup
                || drewOverlaySprite;
            const bool drewObjectBase =
                !drewBase
                && tryDrawObjectShpSprite(
                    dc,
                    viewport,
                    object,
                    center,
                    context,
                    camera,
                    cache,
                    nullptr,
                    &structureBaseLocalRect,
                    nullptr,
                    &structureBaseGlobalRect
                );
            if (drewObjectBase) {
                structureBaseLocalRectValid =
                    runtimeRectIsValid(structureBaseLocalRect);
                structureBaseGlobalRectValid =
                    runtimeRectIsValid(structureBaseGlobalRect);
                if (structureBaseGlobalRectValid) {
                    ++stats.structureBaseGlobalRectObjects;
                }
            }
            if (drewBase || drewObjectBase) {
                ++stats.visibleStructureSprites;
                if (!runtimeObjectIsRenderableRubble(object)) {
                    recordRuntimeOwnerRemapStats(stats, context, object.owner);
                }
            } else {
                prepareFallbackDrawing();
                if (runtimeObjectIsRenderableRubble(object)) {
                    SetDCBrushColor(dc, RGB(82, 78, 70));
                    SetDCPenColor(dc, RGB(34, 31, 28));
                    POINT debris[6] = {
                        {center.x - 11, center.y - 2},
                        {center.x - 5, center.y - 8},
                        {center.x + 1, center.y - 5},
                        {center.x + 7, center.y - 10},
                        {center.x + 12, center.y - 1},
                        {center.x, center.y + 2}
                    };
                    Polygon(dc, debris, 6);
                } else {
                    Rectangle(
                        dc,
                        center.x - 9,
                        center.y - 18,
                        center.x + 10,
                        center.y + 1
                    );
                }
                ++stats.missingStructureSprites;
            }
            if (!drewBuildup) {
                const auto overlayStart =
                    runtimeMaybeTimingStart(detailedTiming);
                drawRuntimeBuildProgressOverlay(
                    dc,
                    center,
                    object,
                    structureBaseGlobalRectValid
                        ? &structureBaseGlobalRect
                        : (structureBaseLocalRectValid
                            ? &structureBaseLocalRect
                            : nullptr)
                );
                stats.objectOverlayMs += runtimeMaybeElapsedMs(
                    detailedTiming,
                    overlayStart
                );
            }
            stats.structureSpriteMs += runtimeMaybeElapsedMs(
                detailedTiming,
                structureStart
            );
            const auto animationStart =
                runtimeMaybeTimingStart(detailedTiming);
            RuntimeStructureAnimationStats buildingAnimationStats;
            const int drawnBuildingAnimations =
                drawRuntimeStructureActiveAnimations(
                dc,
                viewport,
                object,
                center,
                context,
                camera,
                cache,
                &buildingAnimationStats,
                false, nullptr, nullptr, -1, false,
                repairDepotForegroundVehicles.contains(object.instanceId)
            );
            stats.animatedShpSprites += drawnBuildingAnimations;
            stats.buildingArtAnimationLayers += drawnBuildingAnimations;
            stats.buildingSpecialAnimationLayers +=
                buildingAnimationStats.specialLayers;
            stats.repairDepotAnimationLayers += buildingAnimationStats.repairDepotLayers;
            if (buildingAnimationStats.repairDepotLayers > 0) {
                stats.repairDepotAnimationFrame = buildingAnimationStats.repairDepotFrame;
                stats.repairDepotAnimationPhase = buildingAnimationStats.repairDepotPhase;
                stats.repairDepotAnimationImage = buildingAnimationStats.repairDepotImage;
            }
            stats.buildingArtAnimationMissing +=
                buildingAnimationStats.missingLayers;
            stats.buildingPoweredAnimationLayers +=
                buildingAnimationStats.poweredLayers;
            stats.buildingLowPowerAnimationLayers +=
                buildingAnimationStats.lowPowerLayers;
            stats.buildingNeutralAnimationSuppressed +=
                buildingAnimationStats.neutralSuppressedLayers;
            stats.buildingOfflineHiddenAnimationLayers +=
                buildingAnimationStats.offlineHiddenLayers;
            stats.buildingOfflinePausedVisibleAnimationLayers +=
                buildingAnimationStats.offlinePausedVisibleLayers;
            stats.buildingFactoryVehicleDoorAnimationLayers +=
                buildingAnimationStats.factoryVehicleDoorLayers;
            stats.buildingFactoryAirRoofAnimationLayers +=
                buildingAnimationStats.factoryAirRoofLayers;
            stats.buildingShipyardProductionAnimationLayers += buildingAnimationStats.shipyardProductionLayers;
            stats.buildingShipyardIdleAnimationLayers += buildingAnimationStats.shipyardIdleLayers;
            if (buildingAnimationStats.shipyardProductionLayers > 0) {
                stats.shipyardProductionAnimationFrame = buildingAnimationStats.shipyardProductionFrame;
                stats.shipyardProductionAnimationImage = buildingAnimationStats.shipyardProductionImage;
            }
            stats.buildingOfflineContinuingAnimationLayers +=
                buildingAnimationStats.offlineContinuingLayers;
            stats.buildingWorkAnimationLayers +=
                buildingAnimationStats.workLayers;
            if (stats.firstBuildingArtAnimationFrame < 0
                && buildingAnimationStats.firstDrawnFrame >= 0) {
                stats.firstBuildingArtAnimationFrame =
                    buildingAnimationStats.firstDrawnFrame;
                stats.firstBuildingArtAnimationImage =
                    buildingAnimationStats.firstDrawnImage;
            }
            if (stats.firstBuildingOfflinePausedVisibleFrame < 0
                && buildingAnimationStats.firstOfflinePausedVisibleFrame >= 0) {
                stats.firstBuildingOfflinePausedVisibleFrame =
                    buildingAnimationStats.firstOfflinePausedVisibleFrame;
                stats.firstBuildingOfflinePausedVisibleImage =
                    buildingAnimationStats.firstOfflinePausedVisibleImage;
            }
            if (stats.firstBuildingOfflineContinuingFrame < 0
                && buildingAnimationStats.firstOfflineContinuingFrame >= 0) {
                stats.firstBuildingOfflineContinuingFrame =
                    buildingAnimationStats.firstOfflineContinuingFrame;
                stats.firstBuildingOfflineContinuingImage =
                    buildingAnimationStats.firstOfflineContinuingImage;
            }
            if (stats.firstBuildingWorkAnimationFrame < 0
                && buildingAnimationStats.firstWorkFrame >= 0) {
                stats.firstBuildingWorkAnimationFrame =
                    buildingAnimationStats.firstWorkFrame;
                stats.firstBuildingWorkAnimationImage =
                    buildingAnimationStats.firstWorkImage;
            }
            stats.buildingDamageFireOffsets +=
                buildingAnimationStats.damageFireOffsets;
            stats.buildingDamageFireDrawn +=
                buildingAnimationStats.damageFireDrawn;
            stats.buildingDamageFireCulled +=
                buildingAnimationStats.damageFireCulled;
            stats.buildingDamageFireMissing +=
                buildingAnimationStats.damageFireMissing;
            if (stats.firstBuildingDamageFireFrame < 0
                && buildingAnimationStats.firstDamageFireFrame >= 0) {
                stats.firstBuildingDamageFireFrame =
                    buildingAnimationStats.firstDamageFireFrame;
                stats.firstBuildingDamageFireImage =
                    buildingAnimationStats.firstDamageFireImage;
            }
            if (buildingAnimationStats.firstDrawnRectValid) {
                ++stats.structureActiveGlobalRectObjects;
            }
            if (stats.buildingSpecialAnimationImage.empty()
                && !buildingAnimationStats.firstSpecialImage.empty()) {
                stats.buildingSpecialAnimationImage =
                    buildingAnimationStats.firstSpecialImage;
                stats.buildingSpecialAnimationResolved =
                    buildingAnimationStats.firstSpecialResolvedImage;
                stats.buildingSpecialAnimationSource =
                    buildingAnimationStats.firstSpecialSourcePath;
            }
            if (stats.detailStatsEnabled
                && stats.structureRectDiagnostic.empty()
                && (structureBaseGlobalRectValid
                    || buildingAnimationStats.firstDrawnRectValid
                    || buildingAnimationStats.missingLayers > 0)) {
                const RECT cullingRect{
                    center.x - drawRecord.cullMargin,
                    center.y - drawRecord.cullMargin,
                    center.x + drawRecord.cullMargin + 1,
                    center.y + drawRecord.cullMargin + 1
                };
                ++stats.structureCullingRectDiagnostics;
                stats.structureRectDiagnostic =
                    "type="
                    + object.type
                    + " footprint="
                    + std::to_string(drawRecord.footprintWidth)
                    + "x"
                    + std::to_string(drawRecord.footprintHeight)
                    + " baseLocal=["
                    + runtimeRectToString(structureBaseLocalRect)
                    + "] baseGlobal=["
                    + runtimeRectToString(structureBaseGlobalRect)
                    + "] activeImage="
                    + (buildingAnimationStats.firstDrawnImage.empty()
                        ? "none"
                        : buildingAnimationStats.firstDrawnImage)
                    + " activeResolved="
                    + (buildingAnimationStats.firstDrawnResolvedImage.empty()
                        ? "none"
                        : buildingAnimationStats.firstDrawnResolvedImage)
                    + " activeSource="
                    + (buildingAnimationStats.firstDrawnSourcePath.empty()
                        ? "none"
                        : buildingAnimationStats.firstDrawnSourcePath)
                    + " activeLocal=["
                    + runtimeRectToString(
                        buildingAnimationStats.firstDrawnLocalRect
                    )
                    + "] activeGlobal=["
                    + runtimeRectToString(
                        buildingAnimationStats.firstDrawnGlobalRect
                    )
                    + "] cull=["
                    + runtimeRectToString(cullingRect)
                    + "] drawnLayers="
                    + std::to_string(drawnBuildingAnimations)
                    + " missingLayers="
                    + std::to_string(buildingAnimationStats.missingLayers)
                    + " neutralSuppressed="
                    + std::to_string(
                        buildingAnimationStats.neutralSuppressedLayers
                    )
                    + " missingImage="
                    + (buildingAnimationStats.firstMissingImage.empty()
                        ? "none"
                        : buildingAnimationStats.firstMissingImage)
                    + " missingReason="
                    + (buildingAnimationStats.firstMissingReason.empty()
                        ? "none"
                        : buildingAnimationStats.firstMissingReason);
            }
            stats.animationMs += runtimeMaybeElapsedMs(
                detailedTiming,
                animationStart
            );
            bool structureTurretAttempted = false;
            bool structureTurretVoxel = false;
            RuntimeVoxelSpriteDrawInfo structureTurretInfo;
            const bool structureTurretDrawn =
                tryDrawRuntimeStructureTurretAnim(
                dc,
                viewport,
                object,
                center,
                drawRecord.footprintWidth,
                drawRecord.footprintHeight,
                context,
                camera,
                cache,
                &structureTurretAttempted,
                &structureTurretVoxel,
                &structureTurretInfo
            );
            if (structureTurretAttempted) {
                ++stats.structureTurretAnimAttempts;
                if (structureTurretVoxel) {
                    ++stats.structureTurretAnimVoxel;
                } else {
                    ++stats.structureTurretAnimShp;
                }
                if (structureTurretDrawn) {
                    ++stats.structureTurretAnimDrawn;
                    if (containsText(
                            structureTurretInfo.rasterFunctionActuallyCalled,
                            "cuboid"
                        )) {
                        ++stats.structureTurretCuboidRasters;
                    }
                    if (containsText(
                            structureTurretInfo.rasterFunctionActuallyCalled,
                            "point"
                        )) {
                        ++stats.structureTurretPointRasters;
                    }
                    stats.structureTurretMaxWidth = std::max(
                        stats.structureTurretMaxWidth,
                        structureTurretInfo.width
                    );
                    stats.structureTurretMaxHeight = std::max(
                        stats.structureTurretMaxHeight,
                        structureTurretInfo.height
                    );
                    const BuildingType* renderedBuilding =
                        context.rules == nullptr
                            ? nullptr
                            : context.rules->findBuildingType(object.type);
                    POINT renderedTurretScreenOffset{0, 0};
                    if (renderedBuilding != nullptr) {
                        renderedTurretScreenOffset =
                            runtimeStructureTurretAnimScreenOffset(
                                *renderedBuilding,
                                object.type,
                                drawRecord.footprintWidth,
                                drawRecord.footprintHeight,
                                camera
                            );
                    }
                    if (stats.firstStructureTurretType.empty()) {
                        if (renderedBuilding != nullptr) {
                            stats.firstStructureTurretFacing =
                                object.turretFacing >= 0
                                    ? object.turretFacing
                                    : (object.facing >= 0 ? object.facing : 0);
                            stats.firstStructureTurretScreenOffsetX =
                                renderedTurretScreenOffset.x;
                            stats.firstStructureTurretScreenOffsetY =
                                renderedTurretScreenOffset.y;
                            stats.firstStructureTurretFitScale =
                                structureTurretInfo.fitScale;
                            stats.firstStructureTurretType = object.type;
                            stats.firstStructureTurretImage =
                                structureTurretInfo.imageId;
                        }
                    }
                    const std::string turretDiagKey =
                        "image=" + structureTurretInfo.imageId;
                    if (!structureTurretInfo.imageId.empty()
                        && !containsText(
                            stats.structureTurretDiagnostic,
                            turretDiagKey
                        )
                        && stats.structureTurretDiagnostic.size() < 1200U) {
                        if (!stats.structureTurretDiagnostic.empty()) {
                            stats.structureTurretDiagnostic += ";";
                        }
                        stats.structureTurretDiagnostic +=
                            turretDiagKey
                            + " size="
                            + std::to_string(structureTurretInfo.width)
                            + "x"
                            + std::to_string(structureTurretInfo.height)
                            + " fit="
                            + std::to_string(structureTurretInfo.fitScale)
                            + " facing="
                            + std::to_string(
                                object.turretFacing >= 0
                                    ? object.turretFacing
                                    : (object.facing >= 0 ? object.facing : 0)
                            )
                            + " screenOffset="
                            + std::to_string(
                                renderedTurretScreenOffset.x
                            )
                            + ","
                            + std::to_string(
                                renderedTurretScreenOffset.y
                            )
                            + " range="
                            + std::to_string(structureTurretInfo.rangeX)
                            + "x"
                            + std::to_string(structureTurretInfo.rangeY)
                            + " sections="
                            + (structureTurretInfo.sectionSample.empty()
                                    ? "-"
                                    : structureTurretInfo.sectionSample)
                            + " raster="
                            + (structureTurretInfo.rasterFunctionActuallyCalled.empty()
                                ? "-"
                                : structureTurretInfo.rasterFunctionActuallyCalled)
                            + " source="
                            + (structureTurretInfo.sourcePath.empty()
                                ? "-"
                                : structureTurretInfo.sourcePath);
                    }
                } else {
                    ++stats.structureTurretAnimMissing;
                }
            }
        } else if (object.kind == WorldObjectKind::Unit) {
            if (drawRecord.usesVoxelArt) {
                const auto voxelStart =
                    runtimeMaybeTimingStart(detailedTiming);
                RuntimeVoxelDrawResult voxelDrawResult;
                if (tryDrawVoxelSprite(
                        dc,
                        viewport,
                        object,
                        center,
                        context,
                        camera,
                        cache,
                        &voxelDrawResult
                    )) {
                    mobileBodyResolved = true;
                    ++stats.visibleVoxelProxies;
                    if (voxelDrawResult.bodyDrawn) {
                        ++stats.visibleVoxelBodies;
                        stats.voxelBodyMaxWidth = std::max(
                            stats.voxelBodyMaxWidth,
                            voxelDrawResult.bodyInfo.width
                        );
                        stats.voxelBodyMaxHeight = std::max(
                            stats.voxelBodyMaxHeight,
                            voxelDrawResult.bodyInfo.height
                        );
                    }
                    if (voxelDrawResult.turretDrawn) {
                        ++stats.visibleVoxelTurrets;
                        stats.voxelTurretMaxWidth = std::max(
                            stats.voxelTurretMaxWidth,
                            voxelDrawResult.turretInfo.width
                        );
                        stats.voxelTurretMaxHeight = std::max(
                            stats.voxelTurretMaxHeight,
                            voxelDrawResult.turretInfo.height
                        );
                    } else if (runtimeObjectHasTurretForRender(object, context)) {
                        ++stats.missingVoxelTurrets;
                    }
                    if (voxelDrawResult.barrelDrawn) {
                        ++stats.visibleVoxelBarrels;
                        stats.voxelBarrelMaxWidth = std::max(
                            stats.voxelBarrelMaxWidth,
                            voxelDrawResult.barrelInfo.width
                        );
                        stats.voxelBarrelMaxHeight = std::max(
                            stats.voxelBarrelMaxHeight,
                            voxelDrawResult.barrelInfo.height
                        );
                    } else if (runtimeRequireSeparateVoxelBarrelsForStats()
                        && runtimeObjectHasTurretForRender(object, context)
                        && !voxelDrawResult.barrelCueDrawn) {
                        ++stats.missingVoxelBarrels;
                        if (stats.missingVoxelBarrelDiagnostic.size()
                            < 2400U) {
                            if (!stats.missingVoxelBarrelDiagnostic.empty()) {
                                stats.missingVoxelBarrelDiagnostic += ";";
                            }
                            stats.missingVoxelBarrelDiagnostic += object.type;
                            stats.missingVoxelBarrelDiagnostic += "(";
                            bool firstCandidate = true;
                            for (const std::string& candidate :
                                runtimeUnitBarrelImageCandidates(
                                    object,
                                    context
                                )) {
                                if (!firstCandidate) {
                                    stats.missingVoxelBarrelDiagnostic += ",";
                                }
                                stats.missingVoxelBarrelDiagnostic += candidate;
                                firstCandidate = false;
                            }
                            stats.missingVoxelBarrelDiagnostic += ")";
                        }
                    }
                    if (voxelDrawResult.barrelCueDrawn) {
                        ++stats.visibleVoxelBarrelCues;
                    }
                    if (voxelDrawResult.turretFacingFromTurret) {
                        ++stats.voxelTurretFacingFromTurret;
                    }
                    if (voxelDrawResult.turretFacingFromBody) {
                        ++stats.voxelTurretFacingFromBody;
                    }
                    const auto appendVoxelDiagnostic =
                        [&](const char* partName,
                            const RuntimeVoxelSpriteDrawInfo& info) {
                            if (info.imageId.empty()
                                || stats.voxelSpriteDiagnostic.size() > 4200U) {
                                return;
                            }

                            const std::string key =
                                object.type + "." + partName + "=" + info.imageId;
                            if (containsText(stats.voxelSpriteDiagnostic, key)) {
                                return;
                            }

                            if (!stats.voxelSpriteDiagnostic.empty()) {
                                stats.voxelSpriteDiagnostic += ";";
                            }
                            stats.voxelSpriteDiagnostic +=
                                key
                                + " size="
                                + std::to_string(info.width)
                                + "x"
                                + std::to_string(info.height)
                                + " fit="
                                + std::to_string(info.fitScale)
                                + " range="
                                + std::to_string(info.rangeX)
                                + "x"
                                + std::to_string(info.rangeY)
                                + " sections="
                                + (info.sectionSample.empty()
                                    ? "-"
                                    : info.sectionSample);
                        };
                    if (voxelDrawResult.bodyDrawn) {
                        appendVoxelDiagnostic(
                            "body",
                            voxelDrawResult.bodyInfo
                        );
                    }
                    if (voxelDrawResult.turretDrawn) {
                        appendVoxelDiagnostic(
                            "turret",
                            voxelDrawResult.turretInfo
                        );
                    }
                    if (voxelDrawResult.barrelDrawn) {
                        appendVoxelDiagnostic(
                            "barrel",
                            voxelDrawResult.barrelInfo
                        );
                    }
                    if (runtimeObjectUnloadingClassForRender(
                            object,
                            context
                        ) != nullptr) {
                        if (voxelDrawResult.turretDrawn) {
                            ++stats.unloadingClassTurretSprites;
                        } else if (!runtimeObjectHasTurretForRender(
                                object,
                                context
                            )) {
                            ++stats.unloadingClassTurretSuppressedObjects;
                        }
                    }
                    recordRuntimeOwnerRemapStats(stats, context, object.owner);
                    recordRuntimeUnloadingClassStats(
                        stats,
                        object,
                        context,
                        voxelDrawResult.bodyInfo.imageId
                    );
                } else {
                    prepareFallbackDrawing();
                    Ellipse(dc, center.x - 7, center.y - 12, center.x + 8, center.y + 3);
                    ++stats.missingVoxelProxies;
                }
                stats.voxelSpriteMs += runtimeMaybeElapsedMs(
                    detailedTiming,
                    voxelStart
                );
            } else {
                const auto shpStart =
                    runtimeMaybeTimingStart(detailedTiming);
                bool animatedSprite = false;
                bool sequenceFrameUsed = false;
                std::string sequenceName;
                if (tryDrawObjectShpSprite(
                        dc,
                        viewport,
                        object,
                        center,
                        context,
                        camera,
                        cache,
                        &animatedSprite,
                        nullptr,
                        &sequenceFrameUsed,
                        nullptr,
                        &sequenceName
                    )) {
                    mobileBodyResolved = true;
                    if (animatedSprite) {
                        ++stats.animatedShpSprites;
                    }
                    if (sequenceFrameUsed) {
                        ++stats.sequenceFrameHits;
                    } else {
                        ++stats.sequenceFrameFallbacks;
                    }
                    recordRuntimeSequenceStats(
                        stats,
                        sequenceName,
                        object
                    );
                    ++stats.visibleObjectShpSprites;
                    recordRuntimeOwnerRemapStats(stats, context, object.owner);
                    recordRuntimeUnloadingClassStats(
                        stats,
                        object,
                        context,
                        resolveObjectSpriteImageId(object, context)
                    );
                } else {
                    prepareFallbackDrawing();
                    Ellipse(dc, center.x - 7, center.y - 12, center.x + 8, center.y + 3);
                    ++stats.missingObjectShpSprites;
                }
                stats.unitShpMs += runtimeMaybeElapsedMs(
                    detailedTiming,
                    shpStart
                );
            }
        } else {
            const auto shpStart =
                runtimeMaybeTimingStart(detailedTiming);
            bool animatedSprite = false;
            bool sequenceFrameUsed = false;
            std::string sequenceName;
            if (tryDrawObjectShpSprite(
                    dc,
                    viewport,
                    object,
                    center,
                    context,
                    camera,
                    cache,
                    &animatedSprite,
                    nullptr,
                    &sequenceFrameUsed,
                    nullptr,
                    &sequenceName
                )) {
                mobileBodyResolved = true;
                if (animatedSprite) {
                    ++stats.animatedShpSprites;
                }
                if (sequenceFrameUsed) {
                    ++stats.sequenceFrameHits;
                } else {
                    ++stats.sequenceFrameFallbacks;
                }
                recordRuntimeSequenceStats(
                    stats,
                    sequenceName,
                    object
                );
                ++stats.visibleObjectShpSprites;
                recordRuntimeOwnerRemapStats(stats, context, object.owner);
                recordRuntimeUnloadingClassStats(
                    stats,
                    object,
                    context,
                    resolveObjectSpriteImageId(object, context)
                );
            } else {
                POINT triangle[3] = {
                    {center.x, center.y - 12},
                    {center.x + 7, center.y + 3},
                    {center.x - 7, center.y + 3}
                };
                Polygon(dc, triangle, 3);
                ++stats.missingObjectShpSprites;
            }
            stats.unitShpMs += runtimeMaybeElapsedMs(
                detailedTiming,
                shpStart
            );
        }

        sceneDepthObject.reset();
        protectionTint.reset(); // Finish the body before host foreground layers and UI.
        temporalOpacity.reset();
        if (object.kind == WorldObjectKind::Infantry && object.airborne
            && object.mission == "ParadropDrop" && context.rules != nullptr) {
            if (drawRuntimeMobileParachute(dc, viewport, object, center,
                    context, camera, cache)) ++stats.parachuteSprites;
            else ++stats.parachuteMissing;
        }

        bodyObservationScope.finish(); // Foreign host foregrounds and UI are not this mobile's body.
        if (observeMobile && observedBody.supported)
            rememberRuntimeGeometryMobileBounds(object, center, context, camera, cache,
                observedBody.geometry.bounds, mobileBodyResolved && observedBody.geometry.valid, true);

        if (drawRecord.repairDepotHostId >= 0) {
            const auto lastVehicle = repairDepotForegroundVehicles.find(drawRecord.repairDepotHostId);
            if (lastVehicle != repairDepotForegroundVehicles.end() && lastVehicle->second == object.instanceId) {
                const auto host = std::find_if(sortedObjects.begin(), sortedObjects.end(), [&](const auto& item) {
                    return item.instanceId == drawRecord.repairDepotHostId;
                });
                if (host != sortedObjects.end() && host->object) {
                    auto craneContext = untintedObjectContext;
                    if (runtimeObjectHasAirstrikeTint(*host->object, craneContext))
                        craneContext.airstrikeBodyColorAdd = runtimeAirstrikeColorAdd(craneContext);
                    const auto protection = specialObjectLookup.find(host->instanceId);
                    RuntimeTemporalBodyOpacityScope temporalOpacity(dc, viewport, craneContext, stats,
                        host->center, host->cullMargin, protection != specialObjectLookup.end()
                            && protection->second.temporalFrozen);
                    RuntimeForceShieldTintScope shieldTint(dc, viewport, craneContext, stats,
                        host->center, host->cullMargin, protection != specialObjectLookup.end()
                            && protection->second.forceShield,
                        protection != specialObjectLookup.end() ? protection->second.ironCurtainExpireTick : -1);
                    RuntimeStructureAnimationStats craneStats;
                    const int layers = drawRuntimeStructureActiveAnimations(dc, viewport,
                        *host->object, host->center, craneContext, camera, cache, &craneStats,
                        false, nullptr, nullptr, 1);
                    stats.animatedShpSprites += layers;
                    stats.buildingArtAnimationLayers += layers;
                    stats.buildingSpecialAnimationLayers += craneStats.specialLayers;
                    stats.buildingArtAnimationMissing += craneStats.missingLayers;
                    stats.repairDepotAnimationLayers += craneStats.repairDepotLayers;
                    stats.repairDepotAnimationForegroundLayers += craneStats.repairDepotLayers;
                    if (craneStats.repairDepotLayers > 0) {
                        stats.repairDepotAnimationFrame = craneStats.repairDepotFrame;
                        stats.repairDepotAnimationPhase = craneStats.repairDepotPhase;
                        stats.repairDepotAnimationImage = craneStats.repairDepotImage;
                    }
                }
            }
        }

        // The original artwork explicitly separates walls behind/in front
        // of the vehicle. Paint the front only after its real VXL body/turret.
        if (object.tankBunkerHostId >= 0) {
            const auto host = std::find_if(sortedObjects.begin(), sortedObjects.end(), [&](const auto& item) {
                return item.instanceId == object.tankBunkerHostId;
            });
            if (host != sortedObjects.end() && host->object != nullptr) {
                const auto protection = specialObjectLookup.find(host->instanceId);
                RuntimeTemporalBodyOpacityScope temporalOpacity(dc, viewport, context, stats,
                    host->center, host->cullMargin, protection != specialObjectLookup.end()
                        && protection->second.temporalFrozen);
                RuntimeForceShieldTintScope shieldTint(dc, viewport, context, stats,
                    host->center, host->cullMargin, protection != specialObjectLookup.end()
                        && protection->second.forceShield,
                    protection != specialObjectLookup.end() ? protection->second.ironCurtainExpireTick : -1);
                auto frontContext = untintedObjectContext;
                if (runtimeObjectHasAirstrikeTint(*host->object, frontContext))
                    frontContext.airstrikeBodyColorAdd = runtimeAirstrikeColorAdd(frontContext);
                RuntimeStructureAnimationStats frontStats;
                const int layers = drawRuntimeStructureActiveAnimations(dc, viewport,
                    *host->object, host->center, frontContext, camera, cache, &frontStats,
                    false, nullptr, nullptr, 1, true);
                stats.buildingArtAnimationLayers += layers;
                stats.buildingSpecialAnimationLayers += frontStats.specialLayers;
                stats.buildingArtAnimationMissing += frontStats.missingLayers;
                stats.tankBunkerFrontLayers += layers;
                stats.tankBunkerFrontFrame = frontStats.firstDrawnFrame;
            }
        }
        ++stats.visibleWorldObjects;
    };

    const std::string waterWakeSignature =
        runtimeWaterWakeConfigurationSignature(world, context);
    if (cache.waterWakeConfigurationSignature != waterWakeSignature
        || (cache.waterWakeLastAnimationTick >= 0
            && context.animationTick < cache.waterWakeLastAnimationTick)) {
        resetRuntimeWaterWakeStateInternal(cache);
        cache.waterWakeConfigurationSignature = waterWakeSignature;
    }
    cache.waterWakeLastAnimationTick = context.animationTick;

    stats.waterWakeEligibleObjects =
        cache.waterWakeLastUpdateEligibleObjects;
    stats.waterWakeEmissions = cache.waterWakeLastUpdateEmissions;
    stats.waterWakeSuppressedNotMoving =
        cache.waterWakeLastUpdateSuppressedNotMoving;
    stats.waterWakeSuppressedNotWater =
        cache.waterWakeLastUpdateSuppressedNotWater;
    stats.waterWakeSuppressedSubmerged =
        cache.waterWakeLastUpdateSuppressedSubmerged;

    RuntimeWaterWakeResource waterWakeResource;
    const bool waterWakeResourceResolved =
        resolveRuntimeWaterWakeResource(
            context,
            cache,
            waterWakeResource
        );
    if (waterWakeResourceResolved) {
        stats.waterWakeFrameCount = waterWakeResource.frameCount;
        stats.waterWakeFrameDelayTicks = waterWakeResource.frameDelayTicks;
        expireRuntimeWaterWakeActors(
            cache,
            waterWakeResource,
            context.animationTick
        );
    } else {
        if (stats.waterWakeEligibleObjects > 0
            || !cache.waterWakeActors.empty()) {
            ++stats.waterWakeSpritesMissing;
        }
        cache.waterWakeActors.clear();
    }

    const std::vector<RuntimeGroundBodyDrawRecord> groundBodies =
        buildRuntimeGroundBodyDrawRecords(
            sortedObjects,
            cache.waterWakeActors,
            waterWakeResourceResolved
                ? waterWakeResource.artType->ySortAdjust : 0,
            camera,
            context.impactActors,
            &context,
            context.particleSnapshots
        );
    stats.waterWakeActiveActors = static_cast<int>(
        cache.waterWakeActors.size()
    );
    std::unordered_map<int, const WorldObjectInstance*> wakeOwners;
    if(buildingDepthFrameScope && buildingDepthFrameScope->ready && !buildingDepthFrameScope->state.frozenUnderlays.empty()) {
        auto& depth=buildingDepthFrameScope->state;
        for(std::size_t index=0;index<groundBodies.size();++index)
            if(groundBodies[index].objectRecord)
                depth.ownerPaintOrdinals[groundBodies[index].objectRecord->instanceId]=index+1;
    }
    if (!cache.waterWakeActors.empty() && runtimeVisionEnabled(context)) {
        wakeOwners.reserve(world.getObjects().size());
        for (const WorldObjectInstance& object : world.getObjects()) {
            wakeOwners.emplace(object.instanceId, &object);
        }
    }
    for (const RuntimeGroundBodyDrawRecord& groundRecord : groundBodies) {
        if(buildingDepthFrameScope && buildingDepthFrameScope->ready)++buildingDepthFrameScope->state.paintOrdinal;
        if (groundRecord.missileSnapshot != nullptr) {
            drawRuntimeSpawnedMissileBody(dc, viewport, world, context, camera,
                cache, stats, *groundRecord.missileSnapshot);
        } else if (groundRecord.wakeActor != nullptr) {
            const auto wakeOwner = wakeOwners.find(
                groundRecord.wakeActor->objectInstanceId
            );
            if (wakeOwner != wakeOwners.end()
                && !runtimeVisionObjectHasCurrentVisibility(
                    context,
                    *wakeOwner->second
                )) {
                continue;
            }
            const auto wakeStart =
                runtimeMaybeTimingStart(detailedTiming);
            drawRuntimeWaterWakeActor(
                dc,
                viewport,
                context,
                camera,
                cache,
                waterWakeResource,
                *groundRecord.wakeActor,
                groundRecord.wakeProjected,
                stats
            );
            stats.objectOverlayMs += runtimeMaybeElapsedMs(
                detailedTiming,
                wakeStart
            );
        } else if (groundRecord.impactActor != nullptr) {
            const auto impactStart =
                runtimeMaybeTimingStart(detailedTiming);
            drawRuntimeImpactActor(
                dc,
                viewport,
                world,
                context,
                camera,
                cache,
                *groundRecord.impactActor,
                stats
            );
            stats.objectOverlayMs += runtimeMaybeElapsedMs(
                detailedTiming,
                impactStart
            );
        } else if (groundRecord.particleSnapshot != nullptr) {
            if (groundRecord.particleSnapshot->airborneDamageSmoke) {
                continue;
            }
            const auto particleStart =
                runtimeMaybeTimingStart(detailedTiming);
            drawRuntimeParticleSnapshot(
                dc,
                viewport,
                context,
                camera,
                cache,
                *groundRecord.particleSnapshot,
                groundRecord.particleProjected,
                stats
            );
            stats.objectOverlayMs += runtimeMaybeElapsedMs(
                detailedTiming,
                particleStart
            );
        } else if (groundRecord.gateOverlayObjectRecord != nullptr) {
            RuntimeBuildingDepthObjectScope gateDepthObject(*groundRecord.gateOverlayObjectRecord->object,
                groundRecord.gateOverlayObjectRecord->center, context);
            const auto gateOverlayStart =
                runtimeMaybeTimingStart(detailedTiming);
            if (drawRuntimeGateSpecialZOverlay(
                    dc,
                    viewport,
                    *groundRecord.gateOverlayObjectRecord,
                    context,
                    camera,
                    cache
                )) {
                ++stats.gateSpecialZOverlaySprites;
            } else {
                ++stats.gateSpecialZOverlayMissing;
            }
            stats.objectOverlayMs += runtimeMaybeElapsedMs(
                detailedTiming,
                gateOverlayStart
            );
        } else if (groundRecord.objectRecord != nullptr) {
            drawWorldObjectRecord(*groundRecord.objectRecord);
        }
    }

    for (const RuntimeDeferredHighBridgeDraw& bridge :
            deferredHighBridges) {
        if (drawRuntimeBridgeOverlaySprite(
                dc,
                viewport,
                bridge.center,
                bridge.cell,
                bridge.mapFact,
                context,
                camera,
                cache
            )) {
            ++stats.bridgeOverlayDeferredDrawn;
            ++stats.bridgeOverlaySprites;
        } else {
            ++stats.bridgeOverlayMissing;
        }
    }

    for (const RuntimeWorldObjectDrawRecord& drawRecord : sortedObjects) {
        if (drawRecord.object != nullptr && drawRecord.shadowOnBridge) {
            drawWorldObjectShadowRecord(drawRecord);
        }
    }

    for (const RuntimeWorldObjectDrawRecord& drawRecord : sortedObjects) {
        if (drawRecord.object != nullptr
            && drawRecord.bodyVisible
            && drawRecord.shadowOnBridge
            && !drawRecord.airborneForeground) {
            drawWorldObjectRecord(drawRecord);
        }
    }

    // Airborne bodies and their emitted damage smoke share the final layer. Their
    // shadows remain on the terrain/bridge receiver, but no structure body
    // can be painted over a flying unit after this point.
    std::vector<RuntimeWorldObjectDrawRecord> clearanceStructures;
    RuntimeRenderSpatialIndex clearanceSpatialIndex;
    std::vector<std::size_t> clearanceCandidates;
    bool useClearanceSpatialIndex = false;
    bool clearanceStructuresBuilt = false;
    const auto airborneBodies = buildRuntimeAirborneBodyDrawRecords(
        sortedObjects, groundBodies, context, camera);
    for (const RuntimeGroundBodyDrawRecord& airRecord : airborneBodies) {
        if (airRecord.missileSnapshot != nullptr) {
            drawRuntimeSpawnedMissileBody(dc, viewport, world, context, camera,
                cache, stats, *airRecord.missileSnapshot);
            continue;
        }
        if (airRecord.particleSnapshot != nullptr) {
            const auto particleStart = runtimeMaybeTimingStart(detailedTiming);
            drawRuntimeParticleSnapshot(dc, viewport, context, camera, cache,
                *airRecord.particleSnapshot, airRecord.particleProjected, stats);
            stats.objectOverlayMs += runtimeMaybeElapsedMs(
                detailedTiming, particleStart);
            continue;
        }
        const RuntimeWorldObjectDrawRecord& drawRecord = *airRecord.objectRecord;

        RuntimeWorldObjectDrawRecord liftedRecord = drawRecord;
        if (!clearanceStructuresBuilt) {
            // Other mobile actors cannot obstruct an aircraft's building
            // clearance. Avoid an all-units scan for every airborne body.
            clearanceStructures = runtimeAircraftClearanceStructures(
                world, context, camera, viewport);
            useClearanceSpatialIndex = clearanceStructures.size() > 16;
            if (useClearanceSpatialIndex) {
                clearanceSpatialIndex = buildRuntimeStructureRenderSpatialIndex(
                    clearanceStructures);
            }
            clearanceStructuresBuilt = true;
        }
        if (useClearanceSpatialIndex) {
            const auto subCell = worldObjectSubCellOffset(*drawRecord.object);
            clearanceSpatialIndex.query(objectRenderX(*drawRecord.object) + subCell.x,
                objectRenderY(*drawRecord.object) + subCell.y, clearanceCandidates);
        }
        const int clearanceLiftPixels =
            runtimeAircraftBuildingClearanceLiftPixels(
                drawRecord,
                clearanceStructures,
                context,
                camera,
                cache,
                useClearanceSpatialIndex ? &clearanceCandidates : nullptr
            );
        liftedRecord.center.y -= clearanceLiftPixels;
        const bool liftedBodyCulled =
            liftedRecord.center.x < viewport.left - liftedRecord.cullMargin
            || liftedRecord.center.x >= viewport.right + liftedRecord.cullMargin
            || liftedRecord.center.y < viewport.top - liftedRecord.cullMargin
            || liftedRecord.center.y >= viewport.bottom + liftedRecord.cullMargin;
        if (liftedBodyCulled) {
            continue;
        }

        if (clearanceLiftPixels > 0) {
            ++stats.aircraftBuildingClearanceAdjustments;
            stats.aircraftMaxBuildingClearanceLiftPixels = std::max(
                stats.aircraftMaxBuildingClearanceLiftPixels,
                clearanceLiftPixels
            );
        }
        const RECT bodyViewport = runtimeFactoryAirExitBodyViewport(drawRecord,
            clearanceStructures, context, camera, cache, viewport);
        if (bodyViewport.bottom <= bodyViewport.top) continue;
        ++stats.airborneForegroundBodiesDrawn;
        RuntimeFactoryAirExitOcclusionPixels foregroundPixels;
        const RuntimeWorldObjectDrawRecord* foregroundHost = nullptr;
        RECT foregroundClip{};
        if (drawRecord.object->factoryExitHostId >= 0) {
            for (const auto& host : clearanceStructures) {
                if (!host.object || host.instanceId != drawRecord.object->factoryExitHostId
                    || !runtimeAircraftOverStructureFoundation(drawRecord, host)) continue;
                RECT bodyBounds{};
                if (resolveRuntimeMobileObjectSpriteBounds(*drawRecord.object, liftedRecord.center,
                        context, camera, cache, bodyBounds)
                    && IntersectRect(&foregroundClip, &bodyBounds, &bodyViewport)) {
                    foregroundHost = &host;
                    foregroundPixels = captureRuntimeFactoryAirExitForegroundPixels(foregroundClip,
                        *host.object, host.center, context, camera, cache);
                }
                break;
            }
        }
        drawWorldObjectRecord(liftedRecord, &bodyViewport);
        if (foregroundHost) {
            if (hasPixelSurface(context)) {
                for (const auto& [index, pixel] : foregroundPixels) context.surfacePixels[index] = pixel;
            } else {
                drawRuntimeFactoryAirExitForeground(dc, foregroundClip, *foregroundHost->object,
                    foregroundHost->center, context, camera, cache);
            }
        }
    }
    stats.worldObjectsMs = runtimeMaybeElapsedMs(stageTiming, worldObjectsStart);
    traceStage("world-objects-ready");

    drawRuntimeProjectileActors(
        dc,
        viewport,
        context,
        camera,
        cache,
        stats,
        &world
    );
    drawRuntimeImpactActors(
        dc,
        viewport,
        world,
        context,
        camera,
        cache,
        stats,
        false
    );

    drawRuntimeParticleBeamSnapshots(
        dc,
        viewport,
        context,
        camera,
        stats
    );

    drawRuntimeSpecialMechanismOverlays(
        dc,
        viewport,
        world,
        context,
        camera,
        cache,
        stats,
        false
    );
    traceStage("effects-ready");

    // Apply one explicit world-lighting transform after terrain, SHP and VXL
    // composition, but before fog/shroud.  This keeps all three asset paths in
    // the same colour space while leaving the visibility overlay legible.
    const auto lightingStart = runtimeMaybeTimingStart(stageTiming);
    stats.mapLightReceivers = static_cast<int>(mapLightFrame.lookups.size());
    stats.lightingTintedPixels = applyRuntimeMapLights(dc, viewport, context, mapLightFrame);
    stats.lightingTintApplied = stats.lightingTintedPixels > 0;
    stats.lightingMs = runtimeMaybeElapsedMs(stageTiming, lightingStart);
    const auto localLightStart = runtimeMaybeTimingStart(stageTiming);
    RuntimeMapRenderContext objectLightContext = context;
    // Radiation illumination already followed the visible TMP ground surface.
    objectLightContext.specialMechanismSnapshots = nullptr;
    (void)applyRuntimeLocalLightsToViewport(
        dc,
        viewport,
        objectLightContext,
        camera,
        stats
    );
    stats.localLightMs = runtimeMaybeElapsedMs(stageTiming, localLightStart);
    traceStage("lighting-ready");

    // BEHIND is authored on the top layer with normal light. Keep its silver
    // palette above buildings/world lighting while respecting the shroud.
    drawRuntimeBehindMarkers(dc, viewport, context, camera, cache, stats, behindMarkers);
    const auto visionStart = runtimeMaybeTimingStart(stageTiming);
    applyRuntimeVisionOverlay(
        dc,
        viewport,
        world,
        context,
        camera,
        cache,
        stats
    );
    stats.visionMs = runtimeMaybeElapsedMs(stageTiming, visionStart);
    traceStage("vision-ready");

    SelectObject(dc, oldBrush);
    SelectObject(dc, oldPen);
    stats.rendered = true;
    stats.sequenceFrameCacheHits = cache.sequenceFrameCacheHits;
    stats.sequenceFrameCacheMisses = cache.sequenceFrameCacheMisses;
    stats.terrainLayerCacheHits = cache.terrainLayerCacheHits;
    stats.terrainLayerCacheMisses = cache.terrainLayerCacheMisses;
    stats.mapFactLookupCacheRebuilds = cache.mapFactLookupCacheRebuilds;
    stats.projectilePaletteCacheHits = cache.projectilePaletteCacheHits;
    stats.projectilePaletteCacheMisses = cache.projectilePaletteCacheMisses;
    stats.auxiliaryPaletteCacheHits = cache.auxiliaryPaletteCacheHits;
    stats.auxiliaryPaletteCacheMisses = cache.auxiliaryPaletteCacheMisses;
    stats.auxiliaryShpBytesCacheHits = cache.auxiliaryShpBytesCacheHits;
    stats.auxiliaryShpBytesCacheMisses = cache.auxiliaryShpBytesCacheMisses;
    stats.auxiliaryShpFrameCacheHits = cache.auxiliaryShpFrameCacheHits;
    stats.auxiliaryShpFrameCacheMisses = cache.auxiliaryShpFrameCacheMisses;
    stats.voxelCacheHits = cache.voxelCacheHits;
    stats.voxelCacheMisses = cache.voxelCacheMisses;
    stats.buildingAnimationLayerCacheHits =
        cache.buildingAnimationLayerCacheHits;
    stats.buildingAnimationLayerCacheMisses =
        cache.buildingAnimationLayerCacheMisses;
    stats.projectileTypeCacheHits = cache.projectileTypeCacheHits;
    stats.projectileTypeCacheMisses = cache.projectileTypeCacheMisses;
    stats.auxiliaryEffectKindCacheHits =
        cache.auxiliaryEffectKindCacheHits;
    stats.auxiliaryEffectKindCacheMisses =
        cache.auxiliaryEffectKindCacheMisses;
    stats.projectileShpAttempts = cache.projectileShpAttempts;
    stats.projectileShpDrawn = cache.projectileShpDrawn;
    stats.projectileShpSkippedInvisible =
        cache.projectileShpSkippedInvisible;
    stats.projectileShpMissing = cache.projectileShpMissing;
    stats.projectilePaletteHits = cache.projectilePaletteHits;
    stats.projectilePaletteFallbacks = cache.projectilePaletteFallbacks;
    stats.projectilePaletteStructureFallbacks =
        cache.projectilePaletteStructureFallbacks;
    stats.projectileTravelDrawn = cache.projectileTravelDrawn;
    stats.trailerAnimAttempts = cache.trailerAnimAttempts;
    stats.trailerAnimDrawn = cache.trailerAnimDrawn;
    stats.trailerAnimMissing = cache.trailerAnimMissing;
    stats.impactAnimAttempts = cache.impactAnimAttempts;
    stats.impactAnimDrawn = cache.impactAnimDrawn;
    stats.impactAnimMissing = cache.impactAnimMissing;
    stats.weaponAnimAttempts = cache.weaponAnimAttempts;
    stats.weaponAnimDrawn = cache.weaponAnimDrawn;
    stats.weaponAnimMissing = cache.weaponAnimMissing;
    stats.paletteAnimPaletteHits = cache.paletteAnimPaletteHits;
    stats.paletteFirersPaletteHits = cache.paletteFirersPaletteHits;
    stats.paletteExplicitHits = cache.paletteExplicitHits;
    stats.paletteArtHits = cache.paletteArtHits;
    stats.paletteColorHits = cache.paletteColorHits;
    stats.paletteUnitFallbacks = cache.paletteUnitFallbacks;
    stats.paletteIsoFallbacks = cache.paletteIsoFallbacks;
    stats.paletteUnknownHits = cache.paletteUnknownHits;
    stats.projectileEffectMs = cache.projectileEffectMs;
    stats.auxiliaryShpBytesCacheMissMs =
        cache.auxiliaryShpBytesCacheMissMs;
    stats.auxiliaryShpFrameCacheMissMs =
        cache.auxiliaryShpFrameCacheMissMs;
    if (detailedTiming) {
        emitRuntimeRenderDiagnostics(stats);
    }
    return stats;
}


bool runRuntimePlayerCheerSequenceCheck(std::string& error) {
    ArtType art; art.id="HotkeyCheer";
    art.sequenceFrames={{"Ready",true,0,1,0},{"Walk",true,8,6,0},{"Fire",true,20,6,0},{"Cheer",true,30,8,0}};
    WorldObjectInstance object; object.instanceId=42; object.kind=WorldObjectKind::Infantry;
    object.alive=true; object.health=100; object.mission="Guard";
    RuntimeMapRenderContext context; context.animationTick=1;
    std::unordered_map<int,int> cheering{{42,60}}; context.playerCheerUntilTick=&cheering;
    RuntimeMapRenderCache cache;
    const auto frame=selectRuntimeObjectSequenceFrame(object,context,&art,100,&cache);
    if (!frame.matched || frame.sequenceName!="Cheer" || frame.frameIndex<30 || frame.frameIndex>=38
        || object.mission!="Guard") { error="idle Cheer sequence failed"; return false; }
    context.animationTick=61;
    const auto expired=selectRuntimeObjectSequenceFrame(object,context,&art,100,&cache);
    if (expired.sequenceName=="Cheer") { error="Cheer did not expire"; return false; }
    context.animationTick=2; object.mission="Attack";
    const auto attack=selectRuntimeObjectSequenceFrame(object,context,&art,100,&cache);
    if (attack.sequenceName=="Cheer") { error="Cheer interrupted firing"; return false; }
    object.mission="Guard"; object.hasRenderPosition=true; object.renderMoveActive=true;
    const auto move=selectRuntimeObjectSequenceFrame(object,context,&art,100,&cache);
    if (move.sequenceName=="Cheer") { error="Cheer interrupted movement"; return false; }
    error.clear(); return true;
}

